-- FIXME: This could be abstracted and merged with PushColumnsBackground(), by creating a generic struct
-- with storage for backup cliprect + backup channel + storage for splitter pointer, new clip rect.
-- This would slightly simplify caller code.

-- Bg2 is used by Selectable (and possibly other widgets) to render to the background.
-- Unlike our Bg0/1 channel which we uses for RowBg/CellBg/Borders and where we guarantee all shapes to be CPU-clipped, the Bg2 channel being widgets-facing will rely on regular ClipRect.
function ImGui.TablePushBackgroundChannel()
    local g = GImGui
    local window = g.CurrentWindow
    local table_ = g.CurrentTable

    -- Optimization: avoid SetCurrentChannel() + PushClipRect()
    ImRect_Copy(table_.HostBackupInnerClipRect, window.ClipRect)
    ImGui.SetWindowClipRectBeforeSetChannel(window, table_.Bg2ClipRectForDrawCmd)
    table_.DrawSplitter:SetCurrentChannel(window.DrawList, table_.Bg2DrawChannelCurrent)
end

function ImGui.TablePopBackgroundChannel()
    local g = GImGui
    local window = g.CurrentWindow
    local table_ = g.CurrentTable

    -- Optimization: avoid PopClipRect() + SetCurrentChannel()
    ImGui.SetWindowClipRectBeforeSetChannel(window, table_.HostBackupInnerClipRect)
    table_.DrawSplitter:SetCurrentChannel(window.DrawList, table_.Columns[table_.CurrentColumn].DrawChannelCurrent)
end

-- Also see TableBeginCell()
function ImGui.TablePushColumnChannel(column_n)
    local g = GImGui
    local table_ = g.CurrentTable

    -- Optimization: avoid SetCurrentChannel() + PushClipRect()
    if band(table_.Flags, ImGuiTableFlags.NoClip) ~= 0 then
        return
    end
    local window = g.CurrentWindow
    local column = table_.Columns[column_n]
    ImGui.SetWindowClipRectBeforeSetChannel(window, column.ClipRect)
    table_.DrawSplitter:SetCurrentChannel(window.DrawList, column.DrawChannelCurrent)
end

function ImGui.TablePopColumnChannel()
    local g = GImGui
    local table_ = g.CurrentTable

    -- Optimization: avoid PopClipRect() + SetCurrentChannel()
    if band(table_.Flags, ImGuiTableFlags.NoClip) ~= 0 or (table_.CurrentColumn == -1) then -- Calling TreePop() after TableNextRow() is supported.
        return
    end
    local window = g.CurrentWindow
    local column = table_.Columns[table_.CurrentColumn]
    ImGui.SetWindowClipRectBeforeSetChannel(window, column.ClipRect)
    table_.DrawSplitter:SetCurrentChannel(window.DrawList, column.DrawChannelCurrent)
end

-- Allocate draw channels. Called by TableUpdateLayout()
-- - We allocate them following storage order instead of display order so reordering columns won't needlessly
--   increase overall dormant memory cost.
-- - We isolate headers draw commands in their own channels instead of just altering clip rects.
--   This is in order to facilitate merging of draw commands.
-- - After crossing FreezeRowsCount, all columns see their current draw channel changed to a second set of channels.
-- - We only use the dummy draw channel so we can push a null clipping rectangle into it without affecting other
--   channels, while simplifying per-row/per-cell overhead. It will be empty and discarded when merged.
-- - We allocate 1 or 2 background draw channels. This is because we know TablePushBackgroundChannel() is only used for
--   horizontal spanning. If we allowed vertical spanning we'd need one background draw channel per merge group (1-4).
-- Draw channel allocation (before merging):
-- - NoClip                       --> 2+D+1 channels: bg0/1 + bg2 + foreground (same clip rect == always 1 draw call)
-- - Clip                         --> 2+D+N channels
-- - FreezeRows                   --> 2+D+N*2 (unless scrolling value is zero)
-- - FreezeRows || FreezeColumns  --> 3+D+N*2 (unless scrolling value is zero)
-- Where D is 1 if any column is clipped or hidden (dummy channel) otherwise 0.
function ImGui.TableSetupDrawChannels(table_)
    local freeze_row_multiplier = (table_.FreezeRowsCount > 0) and 2 or 1
    local channels_for_row = (band(table_.Flags, ImGuiTableFlags.NoClip) ~= 0) and 1 or table_.ColumnsEnabledCount
    local channels_for_bg = 1 + 1 * freeze_row_multiplier
    local masks_differ = false
    for n = 0, table_.ColumnsCount - 1 do
        if (table_.VisibleMaskByIndex[n] == true) ~= (table_.EnabledMaskByIndex[n] == true) then
            masks_differ = true
            break
        end
    end
    local channels_for_dummy = (table_.ColumnsEnabledCount < table_.ColumnsCount or masks_differ) and 1 or 0
    local channels_total = channels_for_bg + (channels_for_row * freeze_row_multiplier) + channels_for_dummy
    table_.DrawSplitter:Split(table_.InnerWindow.DrawList, channels_total)
    table_.DummyDrawChannel = (channels_for_dummy > 0) and (channels_total - 1) or -1
    table_.Bg2DrawChannelCurrent = TABLE_DRAW_CHANNEL_BG2_FROZEN
    table_.Bg2DrawChannelUnfrozen = (table_.FreezeRowsCount > 0) and (2 + channels_for_row) or TABLE_DRAW_CHANNEL_BG2_FROZEN

    local draw_channel_current = 2
    for column_n = 0, table_.ColumnsCount - 1 do
        local column = table_.Columns[column_n]
        if column.IsVisibleX and column.IsVisibleY then
            column.DrawChannelFrozen = draw_channel_current
            column.DrawChannelUnfrozen = draw_channel_current + ((table_.FreezeRowsCount > 0) and (channels_for_row + 1) or 0)
            if band(table_.Flags, ImGuiTableFlags.NoClip) == 0 then
                draw_channel_current = draw_channel_current + 1
            end
        else
            column.DrawChannelFrozen = table_.DummyDrawChannel
            column.DrawChannelUnfrozen = table_.DummyDrawChannel
        end
        column.DrawChannelCurrent = column.DrawChannelFrozen
    end

    -- Initial draw cmd starts with a BgClipRect that matches the one of its host, to facilitate merge draw commands by default.
    -- All our cell highlight are manually clipped with BgClipRect. When unfreezing it will be made smaller to fit scrolling rect.
    -- (This technically isn't part of setting up draw channels, but is reasonably related to be done here)
    ImRect_Copy(table_.BgClipRect, table_.InnerClipRect)
    ImRect_Copy(table_.Bg0ClipRectForDrawCmd, table_.OuterWindow.ClipRect)
    ImRect_Copy(table_.Bg2ClipRectForDrawCmd, table_.HostClipRect)
    IM_ASSERT(table_.BgClipRect.Min.y <= table_.BgClipRect.Max.y)
end

-- This function reorder draw channels based on matching clip rectangle, to facilitate merging them. Called by EndTable().
-- For simplicity we call it TableMergeDrawChannels() but in fact it only reorder channels + overwrite ClipRect,
-- actual merging is done by table.DrawSplitter:Merge() which is called right after TableMergeDrawChannels().
--
-- Columns where the contents didn't stray off their local clip rectangle can be merged. To achieve
-- this we merge their clip rect and make them contiguous in the channel list, so they can be merged
-- by the call to DrawSplitter:Merge() following to the call to this function.
-- We reorder draw commands by arranging them into a maximum of 4 distinct groups:
--
--   1 group:               2 groups:              2 groups:              4 groups:
--   [ 0. ] no freeze       [ 0. ] row freeze      [ 01 ] col freeze      [ 01 ] row+col freeze
--   [ .. ]  or no scroll   [ 2. ]  and v-scroll   [ .. ]  and h-scroll   [ 23 ]  and v+h-scroll
--
-- Each column itself can use 1 channel (row freeze disabled) or 2 channels (row freeze enabled).
-- When the contents of a column didn't stray off its limit, we move its channels into the corresponding group
-- based on its position (within frozen rows/columns groups or not).
-- At the end of the operation our 1-4 groups will each have a ImDrawCmd using the same ClipRect.
-- This function assume that each column are pointing to a distinct draw channel,
-- otherwise merge_group.ChannelsCount will not match set bit count of merge_group.ChannelsMask.
--
-- Column channels will not be merged into one of the 1-4 groups in the following cases:
-- - The contents stray off its clipping rectangle (we only compare the MaxX value, not the MinX value).
--   Direct ImDrawList calls won't be taken into account by default, if you use them make sure the ImGui.* bounds
--   matches, by e.g. calling SetCursorScreenPos().
-- - The channel uses more than one draw command itself. We drop all our attempt at merging stuff here..
--   we could do better but it's going to be rare and probably not worth the hassle.
-- Columns for which the draw channel(s) haven't been merged with other will use their own ImDrawCmd.
--
-- This function is particularly tricky to understand.. take a breath.
-- (Lua: splitter channel n lives in splitter._Channels.Data[n + 1]; bit arrays are Lua sets)
function ImGui.TableMergeDrawChannels(table_)
    local splitter = table_.DrawSplitter
    local channels = splitter._Channels.Data
    local has_freeze_v = (table_.FreezeRowsCount > 0)
    local has_freeze_h = (table_.FreezeColumnsCount > 0)
    IM_ASSERT(splitter._Current == 0)

    -- Track which groups we are going to attempt to merge, and which channels goes into each group.
    local merge_group_mask = 0x00
    local merge_groups = {}
    for n = 0, 3 do
        merge_groups[n] = { ClipRect = ImRect(), ChannelsCount = 0, ChannelsMask = {} }
    end
    local max_draw_channels = (4 + table_.ColumnsCount * 2)
    local remaining_mask = {}

    -- 1. Scan channels and take note of those which can be merged
    for column_n = 0, table_.ColumnsCount - 1 do
        if BitTest(table_.VisibleMaskByIndex, column_n) then
            local column = table_.Columns[column_n]

            local merge_group_sub_count = has_freeze_v and 2 or 1
            for merge_group_sub_n = 0, merge_group_sub_count - 1 do
                repeat
                    local channel_no = (merge_group_sub_n == 0) and column.DrawChannelFrozen or column.DrawChannelUnfrozen

                    -- Don't attempt to merge if there are multiple draw calls within the column
                    local src_channel = channels[channel_no + 1]
                    local cmds = src_channel._CmdBuffer
                    if cmds.Size > 0 and cmds.Data[cmds.Size].ElemCount == 0 and cmds.Data[cmds.Size].UserCallback == nil then -- Equivalent of PopUnusedDrawCmd()
                        cmds:pop_back()
                    end
                    if cmds.Size ~= 1 then
                        break
                    end

                    -- Find out the width of this merge group and check if it will fit in our column
                    -- (note that we assume that rendering didn't stray on the left direction. we should need a CursorMinPos to detect it)
                    if band(column.Flags, ImGuiTableColumnFlags.NoClip) == 0 then
                        local content_max_x
                        if not has_freeze_v then
                            content_max_x = ImMax(column.ContentMaxXUnfrozen, column.ContentMaxXHeadersUsed) -- No row freeze
                        elseif merge_group_sub_n == 0 then
                            content_max_x = ImMax(column.ContentMaxXFrozen, column.ContentMaxXHeadersUsed)   -- Row freeze: use width before freeze
                        else
                            content_max_x = column.ContentMaxXUnfrozen                                        -- Row freeze: use width after freeze
                        end
                        if content_max_x > column.ClipRect.Max.x then
                            break
                        end
                    end

                    local merge_group_n = ((has_freeze_h and column_n < table_.FreezeColumnsCount) and 0 or 1) + ((has_freeze_v and merge_group_sub_n == 0) and 0 or 2)
                    IM_ASSERT(channel_no < max_draw_channels)
                    local merge_group = merge_groups[merge_group_n]
                    if merge_group.ChannelsCount == 0 then
                        merge_group.ClipRect = ImRect(FLT_MAX, FLT_MAX, -FLT_MAX, -FLT_MAX)
                    end
                    merge_group.ChannelsMask[channel_no] = true
                    merge_group.ChannelsCount = merge_group.ChannelsCount + 1
                    local cr = cmds.Data[1].ClipRect
                    merge_group.ClipRect:Add(ImRect(cr.x, cr.y, cr.z, cr.w))
                    merge_group_mask = bor(merge_group_mask, lshift(1, merge_group_n))
                until true
            end

            -- Invalidate current draw channel
            -- (we don't clear DrawChannelFrozen/DrawChannelUnfrozen solely to facilitate debugging/later inspection of data)
            column.DrawChannelCurrent = -1
        end
    end

    -- 2. Rewrite channel list in our preferred order
    if merge_group_mask ~= 0 then
        -- We skip channel 0 (Bg0/Bg1) and 1 (Bg2 frozen) from the shuffling since they won't move - see channels allocation in TableSetupDrawChannels().
        local LEADING_DRAW_CHANNELS = 2
        local dst_tmp = {}
        for n = LEADING_DRAW_CHANNELS, splitter._Count - 1 do
            remaining_mask[n] = true
        end
        remaining_mask[table_.Bg2DrawChannelUnfrozen] = nil
        IM_ASSERT(has_freeze_v == false or table_.Bg2DrawChannelUnfrozen ~= TABLE_DRAW_CHANNEL_BG2_FROZEN)
        local remaining_count = splitter._Count - (has_freeze_v and (LEADING_DRAW_CHANNELS + 1) or LEADING_DRAW_CHANNELS)
        --local host_rect = (table.InnerWindow == table.OuterWindow) and table.InnerClipRect or table.HostClipRect
        local host_rect = table_.HostClipRect
        for merge_group_n = 0, 3 do
            local merge_channels_count = merge_groups[merge_group_n].ChannelsCount
            if merge_channels_count ~= 0 then
                local merge_group = merge_groups[merge_group_n]
                local merge_clip_rect = Rect(merge_group.ClipRect)

                -- Extend outer-most clip limits to match those of host, so draw calls can be merged even if
                -- outer-most columns have some outer padding offsetting them from their parent ClipRect.
                -- The principal cases this is dealing with are:
                -- - On a same-window table (not scrolling = single group), all fitting columns ClipRect -> will extend and match host ClipRect -> will merge
                -- - Columns can use padding and have left-most ClipRect.Min.x and right-most ClipRect.Max.x != from host ClipRect -> will extend and match host ClipRect -> will merge
                -- FIXME-TABLE FIXME-WORKRECT: We are wasting a merge opportunity on tables without scrolling if column doesn't fit
                -- within host clip rect, solely because of the half-padding difference between window.WorkRect and window.InnerClipRect.
                if band(merge_group_n, 1) == 0 or not has_freeze_h then
                    merge_clip_rect.Min.x = ImMin(merge_clip_rect.Min.x, host_rect.Min.x)
                end
                if band(merge_group_n, 2) == 0 or not has_freeze_v then
                    merge_clip_rect.Min.y = ImMin(merge_clip_rect.Min.y, host_rect.Min.y)
                end
                if band(merge_group_n, 1) ~= 0 then
                    merge_clip_rect.Max.x = ImMax(merge_clip_rect.Max.x, host_rect.Max.x)
                end
                if band(merge_group_n, 2) ~= 0 and band(table_.Flags, ImGuiTableFlags.NoHostExtendY) == 0 then
                    merge_clip_rect.Max.y = ImMax(merge_clip_rect.Max.y, host_rect.Max.y)
                end
                --ImGui.GetForegroundDrawList():AddRect(merge_group.ClipRect.Min, merge_group.ClipRect.Max, IM_COL32(255, 0, 0, 200), 0.0, 0, 1.0) -- [DEBUG]
                --ImGui.GetForegroundDrawList():AddLine(merge_group.ClipRect.Min, merge_clip_rect.Min, IM_COL32(255, 100, 0, 200))
                --ImGui.GetForegroundDrawList():AddLine(merge_group.ClipRect.Max, merge_clip_rect.Max, IM_COL32(255, 100, 0, 200))
                remaining_count = remaining_count - merge_group.ChannelsCount
                for n in pairs(merge_group.ChannelsMask) do
                    remaining_mask[n] = nil
                end
                local n = 0
                while n < splitter._Count and merge_channels_count ~= 0 do
                    -- Copy + overwrite new clip rect
                    if merge_group.ChannelsMask[n] then
                        merge_group.ChannelsMask[n] = nil
                        merge_channels_count = merge_channels_count - 1

                        local channel = channels[n + 1]
                        IM_ASSERT(channel._CmdBuffer.Size == 1)
                        ImVec4_Copy(channel._CmdBuffer.Data[1].ClipRect, merge_clip_rect:ToVec4())
                        dst_tmp[#dst_tmp + 1] = channel
                    end
                    n = n + 1
                end
            end

            -- Make sure Bg2DrawChannelUnfrozen appears in the middle of our groups (whereas Bg0/Bg1 and Bg2 frozen are fixed to 0 and 1)
            if merge_group_n == 1 and has_freeze_v then
                dst_tmp[#dst_tmp + 1] = channels[table_.Bg2DrawChannelUnfrozen + 1]
            end
        end

        -- Append unmergeable channels that we didn't reorder at the end of the list
        local n = 0
        while n < splitter._Count and remaining_count ~= 0 do
            if remaining_mask[n] then
                dst_tmp[#dst_tmp + 1] = channels[n + 1]
                remaining_count = remaining_count - 1
            end
            n = n + 1
        end
        IM_ASSERT(#dst_tmp == splitter._Count - LEADING_DRAW_CHANNELS)
        for i = 1, #dst_tmp do
            channels[LEADING_DRAW_CHANNELS + i] = dst_tmp[i]
        end
    end
end

local function TableGetColumnBorderCol(table_, order_n, column_n)
    local is_hovered = (table_.HoveredColumnBorder == column_n)
    local is_resized = (table_.ResizedColumn == column_n) and (table_.InstanceInteracted == table_.InstanceCurrent)
    local is_frozen_separator = (table_.FreezeColumnsCount == order_n + 1)
    if is_resized or is_hovered then
        return ImGui.GetColorU32(is_resized and ImGuiCol.SeparatorActive or ImGuiCol.SeparatorHovered)
    end
    if is_frozen_separator or band(table_.Flags, bor(ImGuiTableFlags.NoBordersInBody, ImGuiTableFlags.NoBordersInBodyUntilResize)) ~= 0 then
        return table_.BorderColorStrong
    end
    return table_.BorderColorLight
end

-- FIXME-TABLE: This is a mess, need to redesign how we render borders (as some are also done in TableEndRow)
function ImGui.TableDrawBorders(table_)
    local inner_window = table_.InnerWindow
    if not table_.OuterWindow.ClipRect:Overlaps(table_.OuterRect) then
        return
    end

    local inner_drawlist = inner_window.DrawList
    table_.DrawSplitter:SetCurrentChannel(inner_drawlist, TABLE_DRAW_CHANNEL_BG0)
    inner_drawlist:PushClipRect(table_.Bg0ClipRectForDrawCmd.Min, table_.Bg0ClipRectForDrawCmd.Max, false)

    -- Draw inner border and resizing feedback
    local table_instance = ImGui.TableGetInstanceData(table_, table_.InstanceCurrent)
    local border_size = TABLE_BORDER_SIZE
    local draw_y1 = ImMax(table_.InnerRect.Min.y, ((table_.FreezeRowsCount >= 1) and table_.InnerRect.Min.y or table_.WorkRect.Min.y) + table_.AngledHeadersHeight) + ((band(table_.Flags, ImGuiTableFlags.BordersOuterH) ~= 0) and border_size or 0.0)
    local draw_y2_body = table_.InnerRect.Max.y
    local draw_y2_head = table_.IsUsingHeaders and ImMin(table_.InnerRect.Max.y, ((table_.FreezeRowsCount >= 1) and table_.InnerRect.Min.y or table_.WorkRect.Min.y) + table_instance.LastTopHeadersRowHeight) or draw_y1
    if band(table_.Flags, ImGuiTableFlags.BordersInnerV) ~= 0 then
        for order_n = 0, table_.ColumnsCount - 1 do
            repeat
                if not BitTest(table_.EnabledMaskByDisplayOrder, order_n) then
                    break
                end

                local column_n = table_.DisplayOrderToIndex[order_n]
                local column = table_.Columns[column_n]
                local is_hovered = (table_.HoveredColumnBorder == column_n)
                local is_resized = (table_.ResizedColumn == column_n) and (table_.InstanceInteracted == table_.InstanceCurrent)
                local is_resizable = band(column.Flags, bor(ImGuiTableColumnFlags.NoResize, ImGuiTableColumnFlags.NoDirectResize_)) == 0
                local is_frozen_separator = (table_.FreezeColumnsCount == order_n + 1)
                if column.MaxX > table_.InnerClipRect.Max.x and not is_resized then
                    break
                end

                -- Decide whether right-most column is visible
                if column.NextEnabledColumn == -1 and not is_resizable then
                    if band(table_.Flags, ImGuiTableFlags.SizingMask_) ~= ImGuiTableFlags.SizingFixedSame or band(table_.Flags, ImGuiTableFlags.NoHostExtendX) ~= 0 then
                        break
                    end
                end
                if column.MaxX <= column.ClipRect.Min.x then -- FIXME-TABLE FIXME-STYLE: Assume BorderSize==1, this is problematic if we want to increase the border size..
                    break
                end

                -- Draw in outer window so right-most column won't be clipped
                local draw_y2 = draw_y2_head
                if is_frozen_separator then
                    draw_y2 = draw_y2_body
                elseif band(table_.Flags, ImGuiTableFlags.NoBordersInBodyUntilResize) ~= 0 and (is_hovered or is_resized) then
                    draw_y2 = draw_y2_body
                elseif band(table_.Flags, bor(ImGuiTableFlags.NoBordersInBodyUntilResize, ImGuiTableFlags.NoBordersInBody)) == 0 then
                    draw_y2 = draw_y2_body
                end
                if draw_y2 > draw_y1 then
                    inner_drawlist:AddLineV(column.MaxX, draw_y1, draw_y2, TableGetColumnBorderCol(table_, order_n, column_n), border_size)
                end
            until true
        end
    end

    -- Draw outer border
    -- FIXME: could use AddRect or explicit VLine/HLine helper?
    if band(table_.Flags, ImGuiTableFlags.BordersOuter) ~= 0 then
        -- Display outer border offset by 1 which is a simple way to display it without adding an extra draw call
        -- (Without the offset, in outer_window it would be rendered behind cells, because child windows are above their
        -- parent. In inner_window, it won't reach out over scrollbars. Another weird solution would be to display part
        -- of it in inner window, and the part that's over scrollbars in the outer window..)
        -- Either solution currently won't allow us to use a larger border size: the border would clipped.
        local outer_border = table_.OuterRect
        local outer_col = table_.BorderColorStrong
        if band(table_.Flags, ImGuiTableFlags.BordersOuter) == ImGuiTableFlags.BordersOuter then
            inner_drawlist:AddRect(outer_border.Min, outer_border.Max, outer_col, 0.0, border_size)
        elseif band(table_.Flags, ImGuiTableFlags.BordersOuterV) ~= 0 then
            inner_drawlist:AddLineV(outer_border.Min.x, outer_border.Min.y, outer_border.Max.y, outer_col, border_size)
            inner_drawlist:AddLineV(outer_border.Max.x - border_size, outer_border.Min.y, outer_border.Max.y, outer_col, border_size)
        elseif band(table_.Flags, ImGuiTableFlags.BordersOuterH) ~= 0 then
            inner_drawlist:AddLineH(outer_border.Min.x, outer_border.Max.x, outer_border.Min.y, outer_col, border_size)
            inner_drawlist:AddLineH(outer_border.Min.x, outer_border.Max.x, outer_border.Max.y - border_size, outer_col, border_size)
        end
    end
    if band(table_.Flags, ImGuiTableFlags.BordersInnerH) ~= 0 and table_.RowPosY2 < table_.OuterRect.Max.y then
        -- Draw bottom-most row border between it is above outer border.
        local h_inset = (band(table_.Flags, ImGuiTableFlags.BordersOuterV) ~= 0) and border_size or 0.0
        local border_y = table_.RowPosY2
        if border_y >= table_.BgClipRect.Min.y and border_y < table_.BgClipRect.Max.y then
            inner_drawlist:AddLineH(table_.BorderX1 + h_inset, table_.BorderX2 - h_inset, border_y, table_.BorderColorLight, border_size)
        end
    end

    inner_drawlist:PopClipRect()
end

-------------------------------------------------------------------------------
-- [SECTION] Tables: Sorting
-------------------------------------------------------------------------------
-- - TableGetSortSpecs()
-- - TableFixColumnSortDirection() [Internal]
-- - TableGetColumnNextSortDirection() [Internal]
-- - TableSetColumnSortDirection() [Internal]
-- - TableSortSpecsSanitize() [Internal]
-- - TableSortSpecsBuild() [Internal]
-------------------------------------------------------------------------------

-- Return nil if no sort specs (most often when ImGuiTableFlags.Sortable is not set)
-- When 'sort_specs.SpecsDirty == true' you should sort your data. It will be true when sorting specs have
-- changed since last call, or the first time. Make sure to set 'SpecsDirty = false' after sorting,
-- else you may wastefully sort your data every frame!
-- Lifetime: don't hold on this table over multiple frames or past any subsequent call to BeginTable()!
-- PORT: Specs is a 1-based Lua array.
function ImGui.TableGetSortSpecs()
    local g = GImGui
    local table_ = g.CurrentTable
    if table_ == nil or band(table_.Flags, ImGuiTableFlags.Sortable) == 0 then
        return nil
    end

    -- Require layout (in case TableHeadersRow() hasn't been called) as it may alter IsSortSpecsDirty in some paths.
    if not table_.IsLayoutLocked then
        ImGui.TableUpdateLayout(table_)
    end

    ImGui.TableSortSpecsBuild(table_)
    return table_.SortSpecs
end

local function TableGetColumnAvailSortDirection(column, n)
    IM_ASSERT(n < column.SortDirectionsAvailCount)
    return band(rshift(column.SortDirectionsAvailList, lshift(n, 1)), 0x03)
end

-- Fix sort direction if currently set on a value which is unavailable (e.g. activating NoSortAscending/NoSortDescending)
function ImGui.TableFixColumnSortDirection(table_, column)
    if column.SortOrder == -1 or band(column.SortDirectionsAvailMask, lshift(1, column.SortDirection)) ~= 0 then
        return
    end
    column.SortDirection = TableGetColumnAvailSortDirection(column, 0)
    table_.IsSortSpecsDirty = true
end

-- Calculate next sort direction that would be set after clicking the column
-- - If the PreferSortDescending flag is set, we will default to a Descending direction on the first click.
-- - Note that the PreferSortAscending flag is never checked, it is essentially the default and therefore a no-op.
function ImGui.TableGetColumnNextSortDirection(column)
    IM_ASSERT(column.SortDirectionsAvailCount > 0)
    if column.SortOrder == -1 then
        return TableGetColumnAvailSortDirection(column, 0)
    end
    for n = 0, 2 do
        if column.SortDirection == TableGetColumnAvailSortDirection(column, n) then
            return TableGetColumnAvailSortDirection(column, (n + 1) % column.SortDirectionsAvailCount)
        end
    end
    IM_ASSERT(false)
    return ImGuiSortDirection.None
end

-- Note that the NoSortAscending/NoSortDescending flags are processed in TableSortSpecsSanitize(), and they may change/revert
-- the value of SortDirection. We could technically also do it here but it would be unnecessary and duplicate code.
function ImGui.TableSetColumnSortDirection(column_n, sort_direction, append_to_sort_specs)
    local g = GImGui
    local table_ = g.CurrentTable

    if band(table_.Flags, ImGuiTableFlags.SortMulti) == 0 then
        append_to_sort_specs = false
    end
    if band(table_.Flags, ImGuiTableFlags.SortTristate) == 0 then
        IM_ASSERT(sort_direction ~= ImGuiSortDirection.None)
    end

    local sort_order_max = 0
    if append_to_sort_specs then
        for other_column_n = 0, table_.ColumnsCount - 1 do
            sort_order_max = ImMax(sort_order_max, table_.Columns[other_column_n].SortOrder)
        end
    end

    local column = table_.Columns[column_n]
    column.SortDirection = sort_direction
    if column.SortDirection == ImGuiSortDirection.None then
        column.SortOrder = -1
    elseif column.SortOrder == -1 or not append_to_sort_specs then
        column.SortOrder = append_to_sort_specs and (sort_order_max + 1) or 0
    end

    for other_column_n = 0, table_.ColumnsCount - 1 do
        local other_column = table_.Columns[other_column_n]
        if other_column ~= column and not append_to_sort_specs then
            other_column.SortOrder = -1
        end
        ImGui.TableFixColumnSortDirection(table_, other_column)
    end
    table_.IsSettingsDirty = true
    table_.IsSortSpecsDirty = true
end

function ImGui.TableSortSpecsSanitize(table_)
    IM_ASSERT(band(table_.Flags, ImGuiTableFlags.Sortable) ~= 0)

    -- Clear SortOrder from hidden column and verify that there's no gap or duplicate.
    local sort_order_count = 0
    local sort_order_set = {} -- C++: ImU64 sort_order_mask
    local sort_order_dup = false
    for column_n = 0, table_.ColumnsCount - 1 do
        local column = table_.Columns[column_n]
        if column.SortOrder ~= -1 and not column.IsEnabled then
            column.SortOrder = -1
        end
        if column.SortOrder ~= -1 then
            sort_order_count = sort_order_count + 1
            if sort_order_set[column.SortOrder] then sort_order_dup = true end
            sort_order_set[column.SortOrder] = true
            IM_ASSERT(sort_order_count < 64)
        end
    end

    -- need_fix_linearize: (1 << count) != (mask + 1) <=> the set of sort orders isn't exactly {0..count-1}
    local need_fix_linearize = sort_order_dup
    for n = 0, sort_order_count - 1 do
        if not sort_order_set[n] then need_fix_linearize = true end
    end
    local need_fix_single_sort_order = (sort_order_count > 1) and band(table_.Flags, ImGuiTableFlags.SortMulti) == 0
    if need_fix_linearize or need_fix_single_sort_order then
        local fixed_mask = {}
        for sort_n = 0, sort_order_count - 1 do
            -- Fix: Rewrite sort order fields if needed so they have no gap or duplicate.
            -- (e.g. SortOrder 0 disappeared, SortOrder 1..2 exists --> rewrite then as SortOrder 0..1)
            local column_with_smallest_sort_order = -1
            for column_n = 0, table_.ColumnsCount - 1 do
                if not fixed_mask[column_n] and table_.Columns[column_n].SortOrder ~= -1 then
                    if column_with_smallest_sort_order == -1 or table_.Columns[column_n].SortOrder < table_.Columns[column_with_smallest_sort_order].SortOrder then
                        column_with_smallest_sort_order = column_n
                    end
                end
            end
            IM_ASSERT(column_with_smallest_sort_order ~= -1)
            fixed_mask[column_with_smallest_sort_order] = true
            table_.Columns[column_with_smallest_sort_order].SortOrder = sort_n

            -- Fix: Make sure only one column has a SortOrder if ImGuiTableFlags.MultiSortable is not set.
            if need_fix_single_sort_order then
                sort_order_count = 1
                for column_n = 0, table_.ColumnsCount - 1 do
                    if column_n ~= column_with_smallest_sort_order then
                        table_.Columns[column_n].SortOrder = -1
                    end
                end
                break
            end
        end
    end

    -- Fallback default sort order (if no column with the ImGuiTableColumnFlags.DefaultSort flag)
    if sort_order_count == 0 and band(table_.Flags, ImGuiTableFlags.SortTristate) == 0 then
        for column_n = 0, table_.ColumnsCount - 1 do
            local column = table_.Columns[column_n]
            if column.IsEnabled and band(column.Flags, ImGuiTableColumnFlags.NoSort) == 0 then
                sort_order_count = 1
                column.SortOrder = 0
                column.SortDirection = TableGetColumnAvailSortDirection(column, 0)
                break
            end
        end
    end

    table_.SortSpecsCount = sort_order_count
end

function ImGui.TableSortSpecsBuild(table_)
    local dirty = table_.IsSortSpecsDirty
    if dirty then
        ImGui.TableSortSpecsSanitize(table_)
        local multi = table_.SortSpecsMulti
        local want = (table_.SortSpecsCount <= 1) and 0 or table_.SortSpecsCount
        for n = #multi + 1, want do multi[n] = ImGuiTableColumnSortSpecs() end
        for n = #multi, want + 1, -1 do multi[n] = nil end
        table_.SortSpecs.SpecsDirty = true -- Mark as dirty for user
        table_.IsSortSpecsDirty = false -- Mark as not dirty for us
    end

    -- Write output
    -- May be able to move all SortSpecs data from table (48 bytes) to ImGuiTableTempData if we decide to write it back on every BeginTable()
    local sort_specs
    if table_.SortSpecsCount == 0 then
        sort_specs = nil
    elseif table_.SortSpecsCount == 1 then
        table_.SortSpecsSingleArray = table_.SortSpecsSingleArray or { table_.SortSpecsSingle }
        sort_specs = table_.SortSpecsSingleArray
    else
        sort_specs = table_.SortSpecsMulti
    end
    if dirty and sort_specs ~= nil then
        for column_n = 0, table_.ColumnsCount - 1 do
            local column = table_.Columns[column_n]
            if column.SortOrder ~= -1 then
                IM_ASSERT(column.SortOrder < table_.SortSpecsCount)
                local sort_spec = sort_specs[column.SortOrder + 1]
                sort_spec.ColumnUserID = column.UserData
                sort_spec.ColumnIndex = column_n
                sort_spec.SortOrder = column.SortOrder
                sort_spec.SortDirection = column.SortDirection
            end
        end
    end

    table_.SortSpecs.Specs = sort_specs
    table_.SortSpecs.SpecsCount = table_.SortSpecsCount
end

-------------------------------------------------------------------------------
-- [SECTION] Tables: Headers
-------------------------------------------------------------------------------
-- - TableGetHeaderRowHeight() [Internal]
-- - TableGetHeaderAngledMaxLabelWidth() [Internal]
-- - TableHeadersRow()
-- - TableHeader()
-- - TableAngledHeadersRow()
-- - TableAngledHeadersRowEx() [Internal]
-------------------------------------------------------------------------------

function ImGui.TableGetHeaderRowHeight()
    -- Caring for a minor edge case:
    -- Calculate row height, for the unlikely case that some labels may be taller than others.
    -- If we didn't do that, uneven header height would highlight but smaller one before the tallest wouldn't catch input for all height.
    -- In your custom header row you may omit this all together and just call TableNextRow() without a height...
    local g = GImGui
    local table_ = g.CurrentTable
    local row_height = g.FontSize
    for column_n = 0, table_.ColumnsCount - 1 do
        if BitTest(table_.EnabledMaskByIndex, column_n) then
            if band(table_.Columns[column_n].Flags, ImGuiTableColumnFlags.NoHeaderLabel) == 0 then
                row_height = ImMax(row_height, ImGui.CalcTextSize(ImGui.TableGetColumnName(table_, column_n)).y)
            end
        end
    end
    return row_height + g.Style.CellPadding.y * 2.0
end

function ImGui.TableGetHeaderAngledMaxLabelWidth()
    local g = GImGui
    local table_ = g.CurrentTable
    local width = 0.0
    for column_n = 0, table_.ColumnsCount - 1 do
        if BitTest(table_.EnabledMaskByIndex, column_n) then
            if band(table_.Columns[column_n].Flags, ImGuiTableColumnFlags.AngledHeader) ~= 0 then
                width = ImMax(width, ImGui.CalcTextSize(ImGui.TableGetColumnName(table_, column_n), nil, true).x)
            end
        end
    end
    return width + g.Style.CellPadding.y * 2.0 -- Swap padding
end

-- [Public] This is a helper to output TableHeader() calls based on the column names declared in TableSetupColumn().
-- The intent is that advanced users willing to create customized headers would not need to use this helper
-- and can create their own! For example: TableHeader() may be preceded by Checkbox() or other custom widgets.
-- See 'Demo->Tables->Custom headers' for a demonstration of implementing a custom version of this.
-- This code is intentionally written to not make much use of internal functions, to give you better direction
-- if you need to write your own.
-- FIXME-TABLE: TableOpenContextMenu() and TableGetHeaderRowHeight() are not public.
function ImGui.TableHeadersRow()
    local g = GImGui
    local table_ = g.CurrentTable
    IM_ASSERT_USER_ERROR_RET(table_ ~= nil, "Call should only be done while in BeginTable() scope!")

    -- Call layout if not already done. This is automatically done by TableNextRow: we do it here _only_ to make
    -- it easier to debug-step in TableUpdateLayout(). Your own version of this function doesn't need this.
    if not table_.IsLayoutLocked then
        ImGui.TableUpdateLayout(table_)
    end

    -- Open row
    local row_height = ImGui.TableGetHeaderRowHeight()
    ImGui.TableNextRow(ImGuiTableRowFlags.Headers, row_height)
    local row_y1 = ImGui.GetCursorScreenPos().y
    if table_.HostSkipItems then -- Merely an optimization, you may skip in your own code.
        return
    end

    local columns_count = ImGui.TableGetColumnCount()
    for column_n = 0, columns_count - 1 do
        if ImGui.TableSetColumnIndex(column_n) or table_.LastHeldHeaderColumn == column_n then
            -- Push an id to allow empty/unnamed headers. This is also idiomatic as it ensure there is a consistent ID path to access columns (for e.g. automation)
            local name = (band(ImGui.TableGetColumnFlags(column_n), ImGuiTableColumnFlags.NoHeaderLabel) ~= 0) and "" or ImGui.TableGetColumnName(column_n)
            ImGui.PushID(column_n)
            ImGui.TableHeader(name)
            ImGui.PopID()
        end
    end

    -- Allow opening popup from the right-most section after the last column.
    local mouse_pos = ImGui.GetMousePos()
    if ImGui.IsMouseReleased(1) and ImGui.TableGetHoveredColumn() == columns_count then
        if mouse_pos.y >= row_y1 and mouse_pos.y < row_y1 + row_height then
            ImGui.TableOpenContextMenu(columns_count) -- Will open a non-column-specific popup.
        end
    end
end

-- Emit a column header (text + optional sort order)
-- We cpu-clip text here so that all columns headers can be merged into a same draw call.
-- Note that because of how we cpu-clip and display sorting indicators, you _cannot_ use SameLine() after a TableHeader()
function ImGui.TableHeader(label)
    local g = GImGui
    local window = g.CurrentWindow
    if window.SkipItems then
        return
    end

    local table_ = g.CurrentTable
    IM_ASSERT_USER_ERROR_RET(table_ ~= nil, "Call should only be done while in BeginTable() scope!")
    IM_ASSERT(table_.CurrentColumn ~= -1)
    local column_n = table_.CurrentColumn
    local column = table_.Columns[column_n]

    -- Label
    if label == nil then
        label = ""
    end
    local label_end = ImGui.FindRenderedTextEnd(label)
    local label_size = ImGui.CalcTextSize(label, label_end, false)
    local label_pos = V2(window.DC.CursorPos)

    -- If we already got a row height, there's use that.
    -- FIXME-TABLE: Padding problem if the correct outer-padding CellBgRect strays off our ClipRect?
    local cell_r = ImGui.TableGetCellBgRect(table_, column_n)
    local label_height = ImMax(label_size.y, table_.RowMinHeight - table_.RowCellPaddingY * 2.0)

    -- Calculate ideal size for sort order arrow
    local w_arrow = 0.0
    local w_sort_text = 0.0
    local sort_arrow = false
    local sort_order_suf = ""
    local ARROW_SCALE = 0.65
    if band(table_.Flags, ImGuiTableFlags.Sortable) ~= 0 and band(column.Flags, ImGuiTableColumnFlags.NoSort) == 0 then
        w_arrow = ImTrunc(g.FontSize * ARROW_SCALE + g.Style.FramePadding.x)
        if column.SortOrder ~= -1 then
            sort_arrow = true
        end
        if column.SortOrder > 0 then
            sort_order_suf = string.format("%d", column.SortOrder + 1)
            w_sort_text = g.Style.ItemInnerSpacing.x + ImGui.CalcTextSize(sort_order_suf).x
        end
    end

    -- We feed our unclipped width to the column without writing on CursorMaxPos, so that column is still considered for merging.
    local max_pos_x = label_pos.x + label_size.x + w_sort_text + w_arrow
    column.ContentMaxXHeadersUsed = ImMax(column.ContentMaxXHeadersUsed, sort_arrow and cell_r.Max.x or ImMin(max_pos_x, cell_r.Max.x))
    column.ContentMaxXHeadersIdeal = ImMax(column.ContentMaxXHeadersIdeal, max_pos_x)

    -- Keep header highlighted when context menu is open.
    local id = window:GetID(label)
    local bb = ImRect(cell_r.Min.x, cell_r.Min.y, cell_r.Max.x, ImMax(cell_r.Max.y, cell_r.Min.y + label_height + g.Style.CellPadding.y * 2.0))
    ImGui.ItemSize(ImVec2(0.0, label_height)) -- Don't declare unclipped width, it'll be fed ContentMaxPosHeadersIdeal
    if not ImGui.ItemAdd(bb, id) then
        return
    end

    --GetForegroundDrawList():AddRect(cell_r.Min, cell_r.Max, IM_COL32(255, 0, 0, 255)) -- [DEBUG]
    --GetForegroundDrawList():AddRect(bb.Min, bb.Max, IM_COL32(255, 0, 0, 255)) -- [DEBUG]

    -- Using AllowOverlap mode because we cover the whole cell, and we want user to be able to submit subsequent items.
    local highlight = (table_.HighlightColumnHeader == column_n)
    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id, ImGuiButtonFlags.AllowOverlap)
    if held or hovered or highlight then
        local col = ImGui.GetColorU32(held and ImGuiCol.HeaderActive or (hovered and ImGuiCol.HeaderHovered or ImGuiCol.Header))
        --RenderFrame(bb.Min, bb.Max, col, false, 0.0)
        ImGui.TableSetBgColor(ImGuiTableBgTarget.CellBg, col, table_.CurrentColumn)
    else
        -- Submit single cell bg color in the case we didn't submit a full header row
        if band(table_.RowFlags, ImGuiTableRowFlags.Headers) == 0 then
            ImGui.TableSetBgColor(ImGuiTableBgTarget.CellBg, ImGui.GetColorU32(ImGuiCol.TableHeaderBg), table_.CurrentColumn)
        end
    end
    ImGui.RenderNavCursor(bb, id, ImGuiNavRenderCursorFlags.Compact, 0.0)
    if held then
        table_.HeldHeaderColumn = column_n
    end
    window.DC.CursorPos.y = window.DC.CursorPos.y - g.Style.ItemSpacing.y * 0.5

    -- Drag and drop to re-order columns.
    -- FIXME-TABLE: Scroll request while reordering a column and it lands out of the scrolling zone.
    if held and band(table_.Flags, ImGuiTableFlags.Reorderable) ~= 0 and ImGui.IsMouseDragging(0) and not g.DragDropActive then
        -- - While moving a column it will jump on the other side of the mouse, so we also test for MouseDelta.x
        -- - We need to handle reordering across hidden columns.
        --   In the configuration below, moving C to the right of E will lead to:
        --      ... C [D] E  --->  ... [D] E  C   (Column name/index)
        --      ... 2  3  4        ...  2  3  4   (Display order)
        -- - The other constraints are enforced by TableQueueSetColumnDisplayOrder() which might early out.
        table_.InstanceInteracted = table_.InstanceCurrent
        if g.IO.MouseDelta.x < 0.0 and g.IO.MousePos.x < cell_r.Min.x then
            local prev_column = (column.PrevEnabledColumn ~= -1) and table_.Columns[column.PrevEnabledColumn] or nil
            if prev_column then
                ImGui.TableQueueSetColumnDisplayOrder(table_, column_n, prev_column.DisplayOrder)
            end
        end
        if g.IO.MouseDelta.x > 0.0 and g.IO.MousePos.x > cell_r.Max.x then
            local next_column = (column.NextEnabledColumn ~= -1) and table_.Columns[column.NextEnabledColumn] or nil
            if next_column then
                ImGui.TableQueueSetColumnDisplayOrder(table_, column_n, next_column.DisplayOrder)
            end
        end
    end

    -- Sort order arrow
    -- - Only clip label for a visible arrow. Auto-fit still accounts for a possible arrow, but when
    --   manually sized smaller we don't clip the label for the sake of an arrow that isn't displayed.
    local ellipsis_max = ImMax(cell_r.Max.x - (sort_arrow and (w_arrow + w_sort_text) or 0.0), label_pos.x)
    if band(table_.Flags, ImGuiTableFlags.Sortable) ~= 0 and band(column.Flags, ImGuiTableColumnFlags.NoSort) == 0 then
        if column.SortOrder ~= -1 then
            local x = ImMax(cell_r.Min.x, cell_r.Max.x - w_arrow - w_sort_text)
            local y = label_pos.y
            if column.SortOrder > 0 then
                ImGui.PushStyleColor(ImGuiCol.Text, ImGui.GetColorU32(ImGuiCol.Text, 0.70))
                ImGui.RenderText(ImVec2(x + g.Style.ItemInnerSpacing.x, y), sort_order_suf)
                ImGui.PopStyleColor()
                x = x + w_sort_text
            end
            ImGui.RenderArrow(window.DrawList, ImVec2(x, y), ImGui.GetColorU32(ImGuiCol.Text), (column.SortDirection == ImGuiSortDirection.Ascending) and ImGuiDir.Up or ImGuiDir.Down, ARROW_SCALE)
        end

        -- Handle clicking on column header to adjust Sort Order
        if pressed and table_.ReorderColumn ~= column_n then
            local sort_direction = ImGui.TableGetColumnNextSortDirection(column)
            ImGui.TableSetColumnSortDirection(column_n, sort_direction, g.IO.KeyShift)
        end
    end

    -- Render clipped label. Clipping here ensure that in the majority of situations, all our header cells will
    -- be merged into a single draw call.
    --window.DrawList:AddCircleFilled(ImVec2(ellipsis_max, label_pos.y), 40, IM_COL32_WHITE)
    ImGui.RenderTextEllipsis(window.DrawList, label_pos, ImVec2(ellipsis_max, bb.Max.y), ellipsis_max, label, label_end, label_size)

    local text_clipped = label_size.x > (ellipsis_max - label_pos.x)
    if text_clipped and hovered and g.ActiveId == 0 then
        ImGui.SetItemTooltip("%s", string.sub(label, 1, label_end - 1))
    end

    -- We don't use BeginPopupContextItem() because we want the popup to stay up even after the column is hidden
    if ImGui.IsPopupOpenRequestForItem(ImGuiPopupFlags.None, id) then
        ImGui.TableOpenContextMenu(column_n)
    end
end

-- Unlike TableHeadersRow() it is not expected that you can reimplement or customize this with custom widgets.
-- FIXME: No hit-testing/button on the angled header.
function ImGui.TableAngledHeadersRow()
    local g = GImGui
    local table_ = g.CurrentTable
    local temp_data = table_.TempData
    temp_data.AngledHeadersRequests:resize(0)

    -- Which column needs highlight?
    local row_id = ImGui.GetID("##AngledHeaders")
    local table_instance = ImGui.TableGetInstanceData(table_, table_.InstanceCurrent)
    local highlight_column_n = (table_.LastHeldHeaderColumn ~= -1) and table_.LastHeldHeaderColumn or table_.HighlightColumnHeader
    if highlight_column_n == -1 and table_.HoveredColumnBody ~= -1 then
        if table_instance.HoveredRowLast == 0 and table_.HoveredColumnBorder == -1 and (g.ActiveId == 0 or g.ActiveId == row_id or (table_.IsActiveIdInTable or g.DragDropActive)) then
            highlight_column_n = table_.HoveredColumnBody
        end
    end

    -- Build up request
    local col_header_bg = ImGui.GetColorU32(ImGuiCol.TableHeaderBg)
    local col_text = ImGui.GetColorU32(ImGuiCol.Text)
    for order_n = 0, table_.ColumnsCount - 1 do
        if BitTest(table_.EnabledMaskByDisplayOrder, order_n) then
            local column_n = table_.DisplayOrderToIndex[order_n]
            local column = table_.Columns[column_n]
            if band(column.Flags, ImGuiTableColumnFlags.AngledHeader) ~= 0 then -- Note: can't rely on ImGuiTableColumnFlags.IsVisible test here.
                temp_data.AngledHeadersRequests:push_back({ Index = column_n, TextColor = col_text, BgColor0 = col_header_bg, BgColor1 = (column_n == highlight_column_n) and ImGui.GetColorU32(ImGuiCol.Header) or 0 })
            end
        end
    end

    -- Render row
    ImGui.TableAngledHeadersRowEx(row_id, g.Style.TableAngledHeadersAngle, 0.0, temp_data.AngledHeadersRequests.Data, temp_data.AngledHeadersRequests.Size)
end

local function ImTextCountLines(text, text_begin, text_end)
    local count = 0
    local p = text_begin
    while p < text_end do
        local line_end = string.find(text, "\n", p, true)
        if line_end == nil or line_end >= text_end then p = text_end else p = line_end + 1 end
        count = count + 1
    end
    return count
end

-- Important: data must be fed left to right
--- @param data       ImGuiTableHeaderData[] # 1-based array
--- @param data_count int
function ImGui.TableAngledHeadersRowEx(row_id, angle, max_label_width, data, data_count)
    local g = GImGui
    local table_ = g.CurrentTable
    local window = g.CurrentWindow
    local draw_list = window.DrawList
    IM_ASSERT_USER_ERROR_RET(table_ ~= nil, "Call should only be done while in BeginTable() scope!")
    IM_ASSERT(table_.CurrentRow == -1, "Must be first row")

    if max_label_width == 0.0 then
        max_label_width = ImGui.TableGetHeaderAngledMaxLabelWidth()
    end

    -- Angle argument expressed in (-IM_PI/2 .. +IM_PI/2) as it is easier to think about for user.
    local flip_label = (angle < 0.0)
    angle = angle - IM_PI * 0.5
    local cos_a = ImCos(angle)
    local sin_a = ImSin(angle)
    local label_cos_a = flip_label and ImCos(angle + IM_PI) or cos_a
    local label_sin_a = flip_label and ImSin(angle + IM_PI) or sin_a
    local unit_right = ImVec2(cos_a, sin_a)

    -- Calculate our base metrics and set angled headers data _before_ the first call to TableNextRow()
    -- FIXME-STYLE: Would it be better for user to submit 'max_label_width' or 'row_height' ? One can be derived from the other.
    local header_height = g.FontSize + g.Style.CellPadding.x * 2.0
    local row_height = ImTrunc(ImAbs(ImRotate(ImVec2(max_label_width, flip_label and header_height or -header_height), cos_a, sin_a).y))
    table_.AngledHeadersHeight = row_height
    table_.AngledHeadersSlope = (sin_a ~= 0.0) and (cos_a / sin_a) or 0.0
    local header_angled_vector = unit_right * (row_height / -sin_a) -- vector from bottom-left to top-left, and from bottom-right to top-right

    -- Declare row, override and draw our own background
    -- FIXME-TABLE: Generally broken when overlapping frozen columns limit.
    ImGui.TableNextRow(ImGuiTableRowFlags.Headers, row_height)
    ImGui.TableNextColumn()
    local row_r = ImRect(table_.WorkRect.Min.x, table_.BgClipRect.Min.y, table_.WorkRect.Max.x, table_.RowPosY2)
    table_.DrawSplitter:SetCurrentChannel(draw_list, TABLE_DRAW_CHANNEL_BG0)
    local clip_rect_min_x = table_.BgClipRect.Min.x
    if table_.FreezeColumnsCount > 0 then
        clip_rect_min_x = ImMax(clip_rect_min_x, table_.Columns[table_.DisplayOrderToIndex[table_.FreezeColumnsCount - 1]].MaxX)
    end
    ImGui.TableSetBgColor(ImGuiTableBgTarget.RowBg0, 0) -- Cancel
    ImGui.PushClipRect(table_.BgClipRect.Min, table_.BgClipRect.Max, false) -- Span all columns
    draw_list:AddRectFilled(ImVec2(table_.BgClipRect.Min.x, row_r.Min.y), ImVec2(table_.BgClipRect.Max.x, row_r.Max.y), ImGui.GetColorU32(ImGuiCol.TableHeaderBg, 0.25)) -- FIXME-STYLE: Change row background with an arbitrary color.
    ImGui.PushClipRect(ImVec2(clip_rect_min_x, table_.BgClipRect.Min.y), table_.BgClipRect.Max, true) -- Span all columns

    ImGui.ButtonBehavior(row_r, row_id)
    ImGui.KeepAliveID(row_id)

    local ascent_scaled = g.FontBaked.Ascent * g.FontBakedScale -- FIXME: Standardize those scaling factors better
    local line_off_for_ascent_x = (ImMax((g.FontSize - ascent_scaled) * 0.5, 0.0) / -sin_a) * (flip_label and -1.0 or 1.0)
    local padding = g.Style.CellPadding -- We will always use swapped component
    local align = g.Style.TableAngledHeadersTextAlign

    -- Draw background and labels in first pass, then all borders.
    local max_x = -FLT_MAX
    for pass = 0, 1 do
        for order_n = 0, data_count - 1 do
            local request = data[order_n + 1]
            local column_n = request.Index
            local column = table_.Columns[column_n]

            local bg_shape = {}
            bg_shape[0] = ImVec2(column.MaxX, row_r.Max.y)
            bg_shape[1] = ImVec2(column.MinX, row_r.Max.y)
            bg_shape[2] = bg_shape[1] + header_angled_vector
            bg_shape[3] = bg_shape[0] + header_angled_vector
            if pass == 0 then
                -- Draw shape
                draw_list:AddQuadFilled(bg_shape[0], bg_shape[1], bg_shape[2], bg_shape[3], request.BgColor0)
                draw_list:AddQuadFilled(bg_shape[0], bg_shape[1], bg_shape[2], bg_shape[3], request.BgColor1) -- Optional highlight
                max_x = ImMax(max_x, bg_shape[3].x)

                -- Draw label
                -- - First draw at an offset where RenderTextXXX() function won't meddle with applying current ClipRect, then transform to final offset.
                -- - Handle multiple lines manually, as we want each lines to follow on the horizontal border, rather than see a whole block rotated.
                local label_name = ImGui.TableGetColumnName(table_, column_n)
                local label_name_end = ImGui.FindRenderedTextEnd(label_name)
                local line_off_step_x = (g.FontSize / -sin_a)
                local label_lines = ImTextCountLines(label_name, 1, label_name_end)

                -- Left<>Right alignment
                local line_off_curr_x = flip_label and ((label_lines - 1) * line_off_step_x) or 0.0
                local line_off_for_align_x = ImFloor(ImMax((((column.MaxX - column.MinX) - padding.x * 2.0) - (label_lines * line_off_step_x)), 0.0) * align.x)
                line_off_curr_x = line_off_curr_x + line_off_for_align_x - line_off_for_ascent_x

                -- Register header width
                local w = column.WorkMinX + ImCeil(label_lines * line_off_step_x - line_off_for_align_x)
                column.ContentMaxXHeadersUsed = w; column.ContentMaxXHeadersIdeal = w

                local p = 1
                while p < label_name_end do
                    local label_name_eol = string.find(label_name, "\n", p, true)
                    if label_name_eol == nil or label_name_eol > label_name_end then
                        label_name_eol = label_name_end
                    end
                    local line = string.sub(label_name, p, label_name_eol - 1)

                    -- FIXME: Individual line clipping for right-most column is broken for negative angles.
                    local label_size = ImGui.CalcTextSize(line)
                    local clip_width = max_label_width - padding.y -- Using padding.y*2.0f would be symmetrical but hide more text.
                    local clip_height = ImMin(label_size.y, column.ClipRect.Max.x - column.WorkMinX - line_off_curr_x)
                    local clip_r = ImRect(window.ClipRect.Min, window.ClipRect.Min + ImVec2(clip_width, clip_height))
                    local vtx_idx_begin = draw_list._VtxCurrentIdx
                    ImGui.PushStyleColor(ImGuiCol.Text, request.TextColor)
                    ImGui.RenderTextEllipsis(draw_list, clip_r.Min, clip_r.Max, clip_r.Max.x, line, #line + 1, label_size)
                    ImGui.PopStyleColor()
                    local vtx_idx_end = draw_list._VtxCurrentIdx

                    -- Up<>Down alignment
                    local available_space = ImMax(clip_width - label_size.x + ImAbs(padding.x * cos_a) * 2.0 - ImAbs(padding.y * sin_a) * 2.0, 0.0)
                    local vertical_offset = available_space * align.y * (flip_label and -1.0 or 1.0)

                    -- Rotate and offset label
                    local pivot_in = ImVec2(window.ClipRect.Min.x - vertical_offset, window.ClipRect.Min.y + label_size.y)
                    local pivot_out = ImVec2(column.WorkMinX, row_r.Max.y)
                    line_off_curr_x = line_off_curr_x + (flip_label and -line_off_step_x or line_off_step_x)
                    pivot_out = pivot_out + unit_right * padding.y
                    if flip_label then
                        pivot_out = pivot_out + unit_right * (clip_width - ImMax(0.0, clip_width - label_size.x))
                    end
                    pivot_out.x = pivot_out.x + (flip_label and (line_off_curr_x + line_off_step_x) or line_off_curr_x)
                    ImGui.ShadeVertsTransformPos(draw_list, vtx_idx_begin, vtx_idx_end, pivot_in, label_cos_a, label_sin_a, pivot_out) -- Rotate and offset
                    --if g.IO.KeyShift then local fg_dl = GetForegroundDrawList(); vtx_idx_begin = fg_dl._VtxCurrentIdx; fg_dl:AddRect(clip_r.Min, clip_r.Max, IM_COL32(0, 255, 0, 255), 0.0, 0, 1.0); ShadeVertsTransformPos(fg_dl, vtx_idx_begin, fg_dl._VtxCurrentIdx, pivot_in, label_cos_a, label_sin_a, pivot_out) end

                    p = label_name_eol + 1
                end
            end
            if pass == 1 then
                -- Draw border
                local border_size = TABLE_BORDER_SIZE
                draw_list:AddLine(bg_shape[0] + ImVec2(border_size * 0.5, 0.0), bg_shape[3] + ImVec2(border_size * 0.5, 0.0), TableGetColumnBorderCol(table_, order_n, column_n), border_size)
            end
        end
    end
    ImGui.PopClipRect()
    ImGui.PopClipRect()
    table_.TempData.AngledHeadersExtraWidth = ImMax(0.0, max_x - table_.Columns[table_.RightMostEnabledColumn].MaxX)
end

-------------------------------------------------------------------------------
-- [SECTION] Tables: Context Menu
-------------------------------------------------------------------------------
-- - TableOpenContextMenu() [Internal]
-- - TableBeginContextMenuPopup() [Internal]
-- - TableDrawDefaultContextMenu() [Internal]
-------------------------------------------------------------------------------

-- Use -1 to open menu not specific to a given column.
function ImGui.TableOpenContextMenu(column_n)
    if column_n == nil then column_n = -1 end
    local g = GImGui
    local table_ = g.CurrentTable
    if column_n == -1 and table_.CurrentColumn ~= -1 then -- When called within a column automatically use this one (for consistency)
        column_n = table_.CurrentColumn
    end
    if column_n == table_.ColumnsCount then -- To facilitate using with TableGetHoveredColumn()
        column_n = -1
    end
    IM_ASSERT(column_n >= -1 and column_n < table_.ColumnsCount)
    if band(table_.Flags, bor(ImGuiTableFlags.Resizable, ImGuiTableFlags.Reorderable, ImGuiTableFlags.Hideable)) ~= 0 then
        table_.IsContextPopupOpen = true
        table_.ContextPopupColumn = column_n
        table_.InstanceInteracted = table_.InstanceCurrent
        local context_menu_id = ImHashStr("##ContextMenu", nil, table_.ID)
        ImGui.OpenPopupEx(context_menu_id, ImGuiPopupFlags.None)
    end
end

function ImGui.TableBeginContextMenuPopup(table_)
    if not table_.IsContextPopupOpen or table_.InstanceCurrent ~= table_.InstanceInteracted then
        return false
    end
    local context_menu_id = ImHashStr("##ContextMenu", nil, table_.ID)
    if ImGui.BeginPopupEx(context_menu_id, bor(ImGuiWindowFlags.AlwaysAutoResize, ImGuiWindowFlags.NoTitleBar, ImGuiWindowFlags.NoSavedSettings)) then
        return true
    end
    table_.IsContextPopupOpen = false
    return false
end

-- FIXME: Copied from MenuItem() for the purpose of being able to pass _SelectOnRelease (#9312)
local function MenuItemForColumnReorder(label, selected, enabled)
    local g = GImGui
    local window = g.CurrentWindow

    local label_size = ImGui.CalcTextSize(label, nil, true)
    local offsets = window.DC.MenuColumns
    local checkmark_w = IM_TRUNC(g.FontSize * 1.20)
    local min_w = offsets:DeclColumns(0.0, label_size.x, 0.0, checkmark_w) -- Feedback for next frame
    local stretch_w = ImMax(0.0, ImGui.GetContentRegionAvail().x - min_w)
    local text_pos = ImVec2(window.DC.CursorPos.x, window.DC.CursorPos.y + window.DC.CurrLineTextBaseOffset)

    local id = ImGui.GetID(label)
    local selectable_flags = bor(ImGuiSelectableFlags.SelectOnRelease, ImGuiSelectableFlags.SpanAvailWidth)
    if g.ActiveId == id then
        selectable_flags = bor(selectable_flags, ImGuiSelectableFlags.Highlight) -- Stays highlighted while dragging.
    end
    local has_been_moved = (g.ActiveId == id) and g.ActiveIdHasBeenEditedBefore -- But disable toggling once moved.

    ImGui.BeginDisabled(not enabled) -- Don't use ImGuiSelectableFlags.Disabled so that Check mark is also affected.
    local ret = ImGui.Selectable(label, false, selectable_flags, ImVec2(min_w, label_size.y)) and not has_been_moved -- Can't use IsMouseDragging(0) as button is released already.
    if band(g.LastItemData.StatusFlags, ImGuiItemStatusFlags.Visible) ~= 0 and selected then
        ImGui.RenderCheckMark(window.DrawList, text_pos + ImVec2(offsets.OffsetMark + stretch_w + g.FontSize * 0.40, g.FontSize * 0.134 * 0.5), ImGui.GetColorU32(ImGuiCol.Text), g.FontSize * 0.866)
    end
    ImGui.EndDisabled()

    return ret
end

-- Output context menu into current window (generally a popup)
-- FIXME-TABLE: Ideally this should be writable by the user. Full programmatic access to that data?
-- Sections to display are pulled from 'flags_for_section_to_display', which is typically == table.Flags.
-- - ImGuiTableFlags.Resizable   -> display Sizing menu items
-- - ImGuiTableFlags.Reorderable -> display "Reset Order"
---- ImGuiTableFlags.Sortable   -> display sorting options (disabled)
-- - ImGuiTableFlags.Hideable    -> display columns visibility menu items
-- It means if you have a custom context menus you can call this section and omit some sections, and add your own.
function ImGui.TableDrawDefaultContextMenu(table_, flags_for_section_to_display)
    local g = GImGui
    local window = g.CurrentWindow
    if window.SkipItems then
        return
    end

    local want_separator = false
    local context_column_n = (table_.ContextPopupColumn >= 0 and table_.ContextPopupColumn < table_.ColumnsCount) and table_.ContextPopupColumn or -1
    local context_column = (context_column_n ~= -1) and table_.Columns[context_column_n] or nil

    -- Sizing
    if band(flags_for_section_to_display, ImGuiTableFlags.Resizable) ~= 0 then
        if context_column ~= nil then
            local can_resize = band(context_column.Flags, ImGuiTableColumnFlags.NoResize) == 0 and context_column.IsEnabled
            if ImGui.MenuItem(ImGui.LocalizeGetMsg(ImGuiLocKey.TableSizeOne), nil, false, can_resize) then -- "###SizeOne"
                ImGui.TableSetColumnWidthAutoSingle(table_, context_column_n)
            end
        end

        local size_all_desc
        if table_.ColumnsEnabledFixedCount == table_.ColumnsEnabledCount and band(table_.Flags, ImGuiTableFlags.SizingMask_) ~= ImGuiTableFlags.SizingFixedSame then
            size_all_desc = ImGui.LocalizeGetMsg(ImGuiLocKey.TableSizeAllFit)        -- "###SizeAll" All fixed
        else
            size_all_desc = ImGui.LocalizeGetMsg(ImGuiLocKey.TableSizeAllDefault)    -- "###SizeAll" All stretch or mixed
        end
        if ImGui.MenuItem(size_all_desc, nil) then
            ImGui.TableSetColumnWidthAutoAll(table_)
        end
        want_separator = true
    end

    -- Reset Order/Visibility etc.
    if band(flags_for_section_to_display, bor(ImGuiTableFlags.Reorderable, ImGuiTableFlags.Hideable)) ~= 0 then
        if ImGui.BeginMenu(ImGui.LocalizeGetMsg(ImGuiLocKey.TableReset)) then
            --if ImGui.MenuItem(ImGui.LocalizeGetMsg(ImGuiLocKey.TableResetAll)) then -- FIXME: Hiding because altering Sort Order + requesting auto-fit simultaneously has a tendency to exhibit a sizing glitch.
            --    table_.IsResetAllRequest = true
            --end
            if band(flags_for_section_to_display, ImGuiTableFlags.Reorderable) ~= 0 then
                if ImGui.MenuItem(ImGui.LocalizeGetMsg(ImGuiLocKey.TableResetOrder), nil, false, not table_.IsDefaultDisplayOrder) then -- PS: cannot be hidden because it would mess with drag reordering.
                    table_.IsResetDisplayOrderRequest = true
                end
            end
            if band(flags_for_section_to_display, ImGuiTableFlags.Hideable) ~= 0 then
                if ImGui.MenuItem(ImGui.LocalizeGetMsg(ImGuiLocKey.TableResetVisibility), nil, false, not table_.IsDefaultVisibility) then
                    table_.IsResetVisibilityRequest = true
                end
            end
            ImGui.EndMenu()
        end
    end

    -- Sorting
    -- (modify TableOpenContextMenu() to add _Sortable flag if enabling this)
    -- #if 0
    --if band(flags_for_section_to_display, ImGuiTableFlags.Sortable) ~= 0 and column ~= nil and band(column.Flags, ImGuiTableColumnFlags.NoSort) == 0 then
    --    if want_separator then ImGui.Separator() end
    --    want_separator = true
    --    local append_to_sort_specs = g.IO.KeyShift
    --    if ImGui.MenuItem("Sort in Ascending Order", nil, column.SortOrder ~= -1 and column.SortDirection == ImGuiSortDirection.Ascending, band(column.Flags, ImGuiTableColumnFlags.NoSortAscending) == 0) then
    --        ImGui.TableSetColumnSortDirection(table_, column_n, ImGuiSortDirection.Ascending, append_to_sort_specs)
    --    end
    --    if ImGui.MenuItem("Sort in Descending Order", nil, column.SortOrder ~= -1 and column.SortDirection == ImGuiSortDirection.Descending, band(column.Flags, ImGuiTableColumnFlags.NoSortDescending) == 0) then
    --        ImGui.TableSetColumnSortDirection(table_, column_n, ImGuiSortDirection.Descending, append_to_sort_specs)
    --    end
    --end
    -- #endif

    -- Hiding / Visibility
    if band(flags_for_section_to_display, ImGuiTableFlags.Hideable) ~= 0 then
        if want_separator then
            ImGui.Separator()
        end
        want_separator = true

        -- While reordering: we calculate min/max allowed range once here so we can avoid a O(N log N) in the loop (because the query itself does a sweep scan).
        -- This assume that reordering constraints output a single range, otherwise would need to either call TableGetMaxDisplayOrderAllowed() for each item below, or cache this once per frame into columns.
        local is_reordering = (g.ActiveId ~= 0 and g.ActiveIdWindow == g.CurrentWindow and table_.ReorderColumn ~= -1 and g.ActiveIdHasBeenEditedBefore) -- FIXME: This is a bit of a hack.
        local reorder_src_order = is_reordering and table_.Columns[table_.ReorderColumn].DisplayOrder or -1
        local reorder_min_order = is_reordering and TableGetMaxDisplayOrderAllowed(table_, reorder_src_order, 0) or 0
        local reorder_max_order = is_reordering and TableGetMaxDisplayOrderAllowed(table_, reorder_src_order, table_.ColumnsCount - 1) or (table_.ColumnsCount - 1)
        ImGui.PushItemFlag(ImGuiItemFlags.AutoClosePopups, false)
        for order_n = 0, table_.ColumnsCount - 1 do
            local column_n = table_.DisplayOrderToIndex[order_n]
            local column = table_.Columns[column_n]
            if band(column.Flags, ImGuiTableColumnFlags.Disabled) == 0 then
                local name = ImGui.TableGetColumnName(table_, column_n)
                if name == nil or name == "" then
                    name = "<Unknown>"
                end

                -- Make sure we can't hide the last active column
                local menu_item_enabled = band(column.Flags, ImGuiTableColumnFlags.NoHide) == 0
                if column.IsUserEnabled and table_.ColumnsEnabledCount <= 1 then
                    menu_item_enabled = false
                end
                if is_reordering and (column.DisplayOrder < reorder_min_order or column.DisplayOrder > reorder_max_order) then
                    menu_item_enabled = false
                end
                if MenuItemForColumnReorder(name, column.IsUserEnabled, menu_item_enabled) then
                    column.IsUserEnabledNextFrame = not column.IsUserEnabled
                end

                -- Drag to reorder
                -- FIXME: It is currently not possible to reorder columns marked with ImGuiTableColumnFlags.NoHide.
                if ImGui.IsItemActive() and ImGui.IsMouseDragging(0) and g.ActiveIdSource == ImGuiInputSource.Mouse and band(table_.Flags, ImGuiTableFlags.Reorderable) ~= 0 then
                    g.ActiveIdHasBeenEditedBefore = true -- Disable toggle in MenuItemForColumnReorder() + start dimming to display allowed reorder targets.
                    table_.ReorderColumn = column_n
                    if not ImGui.IsItemHovered() then
                        local reorder_dir = (g.IO.MousePos.y < (g.LastItemData.Rect.Min.y + g.LastItemData.Rect.Max.y) * 0.5) and -1 or 1
                        local reorder_amount = ((reorder_dir < 0) and (g.LastItemData.Rect.Min.y - g.IO.MousePos.y) or (g.IO.MousePos.y - g.LastItemData.Rect.Max.y)) / g.LastItemData.Rect:GetHeight()
                        local dst_order = column.DisplayOrder + ImTrunc(ImCeil(reorder_amount)) * reorder_dir -- Estimated target order, will be validated and clamped.
                        ImGui.TableQueueSetColumnDisplayOrder(table_, column_n, dst_order)
                    end
                end
            end
        end
        ImGui.PopItemFlag()
    end
end

-------------------------------------------------------------------------------
-- [SECTION] Tables: Settings (.ini data)
-------------------------------------------------------------------------------
-- FIXME: The binding/finding/creating flow are too confusing.
-------------------------------------------------------------------------------
-- - TableSettingsInit() [Internal]
-- - TableSettingsCreate() [Internal]
-- - TableSettingsFindByID() [Internal]
-- - TableGetBoundSettings() [Internal]
-- - TableResetSettings()
-- - TableSaveSettings() [Internal]
-- - TableLoadSettings() [Internal]
-- - TableLoadSettingsForColumns() [Internal]
-- - TableSettingsHandler_ClearAll() [Internal]
-- - TableSettingsHandler_ApplyAll() [Internal]
-- - TableSettingsHandler_ReadOpen() [Internal]
-- - TableSettingsHandler_ReadLine() [Internal]
-- - TableSettingsHandler_WriteAll() [Internal]
-- - TableSettingsAddSettingsHandler() [Internal]
-------------------------------------------------------------------------------
-- [Init] 1: TableSettingsHandler_ReadXXXX()   Load and parse .ini file into TableSettings.
-- [Main] 2: TableLoadSettings()               When table is created, bind Table to TableSettings, serialize TableSettings data into Table.
-- [Main] 3: TableSaveSettings()               When table properties are modified, serialize Table data into bound or new TableSettings, mark .ini as dirty.
-- [Main] 4: TableSettingsHandler_WriteAll()   When .ini file is dirty (which can come from other source), save TableSettings into .ini file.
-------------------------------------------------------------------------------

-- Clear and initialize empty settings instance
local function TableSettingsInit(settings, id, columns_count, columns_count_max)
    for k, v in pairs(ImGuiTableSettings()) do settings[k] = v end
    for n = 0, columns_count_max - 1 do
        settings.Columns[n] = ImGuiTableColumnSettings()
    end
    settings.ID = id
    settings.ColumnsCount = columns_count
    settings.ColumnsCountMax = columns_count_max
    settings.WantApply = true
end

function ImGui.TableSettingsCreate(id, columns_count)
    local g = GImGui
    local settings = ImGui.TableSettingsFindByID(id)
    if settings then
        if settings.ColumnsCountMax >= columns_count then
            TableSettingsInit(settings, id, columns_count, settings.ColumnsCountMax) -- Recycle
            return settings
        end
        settings.ID = 0 -- Invalidate storage, we won't fit because of a count change
    end
    settings = ImGuiTableSettings()
    g.SettingsTables:push_back(settings)
    TableSettingsInit(settings, id, columns_count, columns_count)
    return settings
end

-- Find existing settings
function ImGui.TableSettingsFindByID(id)
    -- FIXME-OPT: Might want to store a lookup map for this?
    local g = GImGui
    for _, settings in g.SettingsTables:iter() do
        if settings.ID == id then
            return settings
        end
    end
    return nil
end

local function SettingsTablesOffsetFromPtr(settings)
    local g = GImGui
    return g.SettingsTables:find_index(settings) or -1
end

-- Get settings for a given table, nil if none
function ImGui.TableGetBoundSettings(table_)
    if table_.SettingsOffset == -1 then
        return nil
    end
    local g = GImGui
    local settings = g.SettingsTables.Data[table_.SettingsOffset]
    IM_ASSERT(settings.ID == table_.ID)
    return settings
end

-- Restore initial state of table (with or without saved settings)
function ImGui.TableResetSettings(table_)
    table_.IsInitializing = true; table_.IsSettingsDirty = true
    table_.IsResetAllRequest = false
    table_.IsSettingsRequestLoad = false                    -- Don't reload from ini
    table_.SettingsLoadedFlags = ImGuiTableFlags.None       -- Mark as nothing loaded so our initialized data becomes authoritative
end

function ImGui.TableSaveSettings(table_)
    table_.IsSettingsDirty = false
    if band(table_.Flags, ImGuiTableFlags.NoSavedSettings) ~= 0 then
        return
    end

    -- Bind or create settings data
    local settings = ImGui.TableGetBoundSettings(table_)
    if settings ~= nil and table_.ColumnsCount > settings.ColumnsCountMax then
        settings.ID = 0 -- Invalidate storage, we won't fit because of a count change
        settings = nil
    end
    if settings == nil then
        settings = ImGui.TableSettingsCreate(table_.ID, table_.ColumnsCount)
        table_.SettingsOffset = SettingsTablesOffsetFromPtr(settings)
    end
    settings.ColumnsCount = table_.ColumnsCount

    -- Serialize ImGuiTable/ImGuiTableColumn into ImGuiTableSettings/ImGuiTableColumnSettings
    IM_ASSERT(settings.ID == table_.ID)
    IM_ASSERT(settings.ColumnsCount == table_.ColumnsCount and settings.ColumnsCountMax >= settings.ColumnsCount)

    local save_ref_scale = false
    settings.SaveFlags = ImGuiTableFlags.None
    for n = 0, table_.ColumnsCount - 1 do
        local column = table_.Columns[n]
        local column_settings = settings.Columns[n]
        local width_or_weight = (band(column.Flags, ImGuiTableColumnFlags.WidthStretch) ~= 0) and column.StretchWeight or column.WidthRequest
        column_settings.ID = column.ID
        column_settings.WidthOrWeight = width_or_weight
        column_settings.Index = n
        column_settings.DisplayOrder = column.DisplayOrder
        column_settings.SortOrder = column.SortOrder
        column_settings.SortDirection = column.SortDirection
        column_settings.IsEnabled = column.IsUserEnabled and 1 or 0
        column_settings.IsStretch = (band(column.Flags, ImGuiTableColumnFlags.WidthStretch) ~= 0) and 1 or 0
        if band(column.Flags, ImGuiTableColumnFlags.WidthStretch) == 0 then
            save_ref_scale = true
        end

        -- We skip saving some data in the .ini file when they are unnecessary to restore our state.
        -- Note that fixed width where initial width was derived from auto-fit will always be saved as InitStretchWeightOrWidth will be 0.0f.
        -- FIXME-TABLE: We don't have logic to easily compare SortOrder to DefaultSortOrder yet so it's always saved when present.
        if width_or_weight ~= column.InitStretchWeightOrWidth then
            settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Resizable)
        end
        if column.DisplayOrder ~= n then
            settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Reorderable)
        end
        if column.SortOrder ~= -1 then
            settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Sortable, ImGuiTableFlags.Reorderable) -- Because SortOrder saving itself is gated, make sure every column is saved (#9519)
        end
        if column.IsUserEnabled ~= (band(column.Flags, ImGuiTableColumnFlags.DefaultHide) == 0) then
            settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Hideable)
        end
    end
    settings.SaveFlags = band(settings.SaveFlags, table_.Flags)
    settings.RefScale = save_ref_scale and table_.RefScale or 0.0

    ImGui.MarkIniSettingsDirty()
end

function ImGui.TableLoadSettings(table_)
    if band(table_.Flags, ImGuiTableFlags.NoSavedSettings) ~= 0 then
        table_.IsSettingsRequestLoad = false -- Done
        return
    end

    -- Bind settings
    local settings
    if table_.SettingsOffset == -1 then
        settings = ImGui.TableSettingsFindByID(table_.ID)
        if settings == nil then
            return
        end
        if settings.ColumnsCount ~= table_.ColumnsCount then -- Allow settings if columns count changed. We could otherwise decide to return...
            table_.IsSettingsDirty = true
        end
        table_.SettingsOffset = SettingsTablesOffsetFromPtr(settings)
    else
        settings = ImGui.TableGetBoundSettings(table_)
    end

    table_.SettingsLoadedFlags = settings.SaveFlags
    table_.RefScale = settings.RefScale
    -- TableUpdateLayout() will then call TableLoadSettingsForColumns() to apply the data.
end

-- NB: This was written to be similar to the logic in TableReconcileColumns().
function ImGui.TableLoadSettingsForColumns(table_)
    for n = 0, table_.ColumnsSize - 1 do
        table_.Columns[n].IsLoadedSettings = false
    end
    local settings = ImGui.TableGetBoundSettings(table_)
    if settings == nil then
        return
    end

    table_.SettingsLoadedFlags = bor(table_.SettingsLoadedFlags, ImGuiTableFlags.Reorderable) -- We handle above in code above.

    -- Serialize ImGuiTableSettings/ImGuiTableColumnSettings into ImGuiTable/ImGuiTableColumn
    local column_settings = settings.Columns

    -- Fast path
    local matches = 0
    for n = 0, table_.ColumnsCount - 1 do
        if n >= settings.ColumnsCount or column_settings[n].ID ~= table_.Columns[n].ID then
            break
        end
        ImGui.TableLoadSettingsForColumn(table_.Columns[n], column_settings[n], settings.SaveFlags)
        matches = matches + 1
    end
    if matches == settings.ColumnsCount then
        return
    end
    local settings_start_n = matches -- Small optimization
    for n = settings_start_n, settings.ColumnsCount - 1 do
        column_settings[n].IsLoaded = false
    end

    -- Find matches for named columns
    for c = 0, table_.ColumnsSize - 1 do
        local column = table_.Columns[c]
        if column.ID ~= 0 and not column.IsLoadedSettings then
            for n = settings_start_n, settings.ColumnsCount - 1 do
                if column_settings[n].ID == column.ID and not column_settings[n].IsLoaded then
                    ImGui.TableLoadSettingsForColumn(column, column_settings[n], settings.SaveFlags)
                    matches = matches + 1
                    break
                end
            end
        end
    end

    -- Remaining entries are matched sequentially
    local dst_idx = 0
    for n = settings_start_n, settings.ColumnsCount - 1 do
        if not column_settings[n].IsLoaded then
            while dst_idx < table_.ColumnsCount and table_.Columns[dst_idx].IsLoadedSettings do
                dst_idx = dst_idx + 1
            end
            if dst_idx >= table_.ColumnsCount then
                break
            end
            ImGui.TableLoadSettingsForColumn(table_.Columns[dst_idx], column_settings[n], settings.SaveFlags)
            dst_idx = dst_idx + 1
        end
    end
end

function ImGui.TableLoadSettingsForColumn(column, column_settings, load_flags)
    column.IsLoadedSettings = true
    column_settings.IsLoaded = true
    if band(load_flags, ImGuiTableFlags.Resizable) ~= 0 then
        if column_settings.IsStretch ~= 0 then
            column.StretchWeight = column_settings.WidthOrWeight
        else
            column.WidthRequest = column_settings.WidthOrWeight
        end
        column.AutoFitQueue = 0x00
    end
    if band(load_flags, ImGuiTableFlags.Reorderable) ~= 0 then
        column.DisplayOrder = column_settings.DisplayOrder
    else
        column.DisplayOrder = column_settings.Index -- Because default depends on previous Index, we need to set that up and cannot rely on TableInitColumnDefaults()
    end
    if band(load_flags, ImGuiTableFlags.Hideable) ~= 0 and column_settings.IsEnabled ~= -1 then
        local v = (column_settings.IsEnabled == 1)
        column.IsUserEnabled = v; column.IsUserEnabledNextFrame = v
    end
    column.SortOrder = column_settings.SortOrder
    column.SortDirection = column_settings.SortDirection
end

-- Fix invalid display order data: compact values (0,1,3 -> 0,1,2); preserve relative order (0,3,1 -> 0,2,1); deduplicate (0,4,1,1 -> 0,3,1,2)
function ImGui.TableFixDisplayOrder(table_)
    if band(table_.Flags, ImGuiTableFlags.Reorderable) == 0 then
        for n = 0, table_.ColumnsCount - 1 do
            table_.Columns[n].DisplayOrder = n
            table_.DisplayOrderToIndex[n] = n
        end
        return
    end
    local fdo_columns = {}
    for n = 0, table_.ColumnsCount - 1 do
        fdo_columns[n + 1] = n
    end
    -- Sort by DisplayOrder and then Index
    -- Assume ImGuiTableColumnIdx == signed short, to turn -1 into a large value so that it always sort after.
    local function key(idx)
        local o = table_.Columns[idx].DisplayOrder
        if o < 0 then o = o + 0x10000 end
        return o
    end
    table.sort(fdo_columns, function(lhs_idx, rhs_idx)
        local a, b = key(lhs_idx), key(rhs_idx)
        if a ~= b then return a < b end
        return lhs_idx < rhs_idx
    end)
    for n = 0, table_.ColumnsCount - 1 do
        table_.Columns[fdo_columns[n + 1]].DisplayOrder = n
    end
    for n = 0, table_.ColumnsCount - 1 do
        table_.DisplayOrderToIndex[table_.Columns[n].DisplayOrder] = n
    end
end

local function ForEachTable(g, fn)
    for i = 0, g.Tables:GetMapSize() - 1 do
        local t = g.Tables:GetByIndex(i)
        if t then fn(t) end
    end
end

local function TableSettingsHandler_ClearAll(ctx, handler)
    local g = ctx
    ForEachTable(g, function(t) t.SettingsOffset = -1 end)
    g.SettingsTables:clear()
end

-- Apply to existing windows (if any)
local function TableSettingsHandler_ApplyAll(ctx, handler)
    local g = ctx
    ForEachTable(g, function(t)
        t.IsSettingsRequestLoad = true
        t.SettingsOffset = -1
    end)
end

local function TableSettingsHandler_ReadOpen(ctx, handler, name)
    -- FIXME: As topology changes are allowed, strictly speaking a >= IMGUI_TABLE_MAX_COLUMNS tables stored in .ini file
    -- that was emitted with a higher max count could still be meaningful in some unlikely cases.
    -- We might want to use another MAX defined as (1<<(sizeof(ImGuiTableColumnIdx)*8-1))-1.
    local id, columns_count = string.match(name, "^0x(%x+),(%-?%d+)")
    if id == nil then
        return nil
    end
    id = tonumber(id, 16); columns_count = tonumber(columns_count)
    if columns_count <= 0 or columns_count >= IMGUI_TABLE_MAX_COLUMNS then
        return nil
    end
    return ImGui.TableSettingsCreate(id, columns_count)
end

local function TableSettingsHandler_ReadLine(ctx, handler, settings, line)
    -- "Column 0  UserID=0x42AD2D21 Width=100 Visible=1 Order=0 Sort=0v"
    if settings == nil then return end
    local f = string.match(line, "^RefScale=([%-%d%.eE+]+)")
    if f then settings.RefScale = tonumber(f); return end
    local n = string.match(line, "^LastUsed=(%d+)")
    if n then settings.LastUsedDate = tonumber(n); return end

    local column_n, rest = string.match(line, "^Column (%-?%d+)(.*)$")
    if column_n then
        column_n = tonumber(column_n)
        if column_n < 0 or column_n >= settings.ColumnsCount then
            return
        end
        local column = settings.Columns[column_n]
        column.Index = column_n
        local function take(pattern)
            local a, b, r = string.match(rest, "^%s*" .. pattern .. "()")
            if a == nil then return nil end
            if r == nil then r = b; b = nil end
            rest = string.sub(rest, r)
            return a, b
        end
        take("UserID=0x(%x+)") -- FIXME-LEGACY: Removed 2025/11/12, was never properly set.
        local v = take("Width=(%-?%d+)")
        if v then column.WidthOrWeight = tonumber(v); column.IsStretch = 0; settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Resizable) end
        v = take("Weight=([%-%d%.eE+]+)")
        if v then column.WidthOrWeight = tonumber(v); column.IsStretch = 1; settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Resizable) end
        v = take("Visible=(%-?%d+)")
        if v then column.IsEnabled = tonumber(v); settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Hideable) end
        v = take("Order=(%-?%d+)")
        if v then column.DisplayOrder = tonumber(v); settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Reorderable) end
        local c
        v, c = take("Sort=(%-?%d+)(.)")
        if v then column.SortOrder = tonumber(v); column.SortDirection = (c == "^") and ImGuiSortDirection.Descending or ImGuiSortDirection.Ascending; settings.SaveFlags = bor(settings.SaveFlags, ImGuiTableFlags.Sortable) end
        v = take("ID=0x(%x+)")
        if v then column.ID = tonumber(v, 16) end
    end
end

local function TableSettingsHandler_WriteAll(ctx, handler, buf)
    local g = ctx
    for _, settings in g.SettingsTables:iter() do
        if settings.ID ~= 0 then -- Skip ditched settings
            -- TableSaveSettings() may clear some of those flags when we establish that the data can be stripped
            -- (e.g. Order was unchanged)
            local save_size    = band(settings.SaveFlags, ImGuiTableFlags.Resizable) ~= 0
            local save_visible = band(settings.SaveFlags, ImGuiTableFlags.Hideable) ~= 0
            local save_order   = band(settings.SaveFlags, ImGuiTableFlags.Reorderable) ~= 0
            local save_sort    = band(settings.SaveFlags, ImGuiTableFlags.Sortable) ~= 0
            -- We need to save the [Table] entry even if all the bools are false, since this records a table with "default settings".

            buf:appendf("[%s][0x%08X,%d]\n", handler.TypeName, settings.ID, settings.ColumnsCount)
            if settings.RefScale ~= 0.0 then
                buf:appendf("RefScale=%g\n", settings.RefScale)
            end
            for column_n = 0, settings.ColumnsCount - 1 do
                local column = settings.Columns[column_n]
                -- "Column 0  UserID=0x42AD2D21 Width=100 Visible=1 Order=0 Sort=0v"
                local save_column = save_size or save_visible or save_order or (save_sort and column.SortOrder ~= -1)
                if save_column then
                    buf:appendf("Column %-2d", column_n)
                    if save_size and column.IsStretch ~= 0 then buf:appendf(" Weight=%.4f", column.WidthOrWeight) end
                    if save_size and column.IsStretch == 0 then buf:appendf(" Width=%d", ImTrunc(column.WidthOrWeight)) end
                    if save_visible then buf:appendf(" Visible=%d", column.IsEnabled) end
                    if save_order then buf:appendf(" Order=%d", column.DisplayOrder) end
                    if save_sort and column.SortOrder ~= -1 then buf:appendf(" Sort=%d%s", column.SortOrder, (column.SortDirection == ImGuiSortDirection.Ascending) and "v" or "^") end
                    if column.ID ~= 0 then buf:appendf(" ID=0x%08X", column.ID) end
                    buf:append("\n")
                end
            end
            if g.IO.ConfigIniSettingsSaveLastUsedDate and settings.LastUsedDate ~= 0 then
                buf:appendf("LastUsed=%08d\n", settings.LastUsedDate)
            end
            buf:append("\n")
        end
    end
end

function ImGui.TableSettingsAddSettingsHandler()
    local ini_handler = ImGuiSettingsHandler()
    ini_handler.TypeName = "Table"
    ini_handler.TypeHash = ImHashStr("Table")
    ini_handler.ClearAllFn = TableSettingsHandler_ClearAll
    ini_handler.ReadOpenFn = TableSettingsHandler_ReadOpen
    ini_handler.ReadLineFn = TableSettingsHandler_ReadLine
    ini_handler.ApplyAllFn = TableSettingsHandler_ApplyAll
    ini_handler.WriteAllFn = TableSettingsHandler_WriteAll
    ImGui.AddSettingsHandler(ini_handler)
end

-------------------------------------------------------------------------------
-- [SECTION] Tables: Garbage Collection
-------------------------------------------------------------------------------
-- - TableRemove() [Internal]
-- - TableGcCompactTransientBuffers() [Internal]
-- - TableGcCompactSettings() [Internal]
-------------------------------------------------------------------------------

-- Remove Table data (currently only used by TestEngine)
function ImGui.TableRemove(table_)
    --IMGUI_DEBUG_PRINT("TableRemove() id=0x%08X\n", table_.ID)
    local g = GImGui
    local table_idx = g.Tables:GetIndex(table_)
    g.Tables:Remove(table_.ID, table_)
    g.TablesLastTimeActive.Data[table_idx + 1] = -1.0
end

-- Free up/compact internal Table buffers for when it gets unused
-- Overloads: (ImGuiTable) / (ImGuiTableTempData)
function ImGui.TableGcCompactTransientBuffers(t)
    if not t then return end
    if t.TableIndex ~= nil then -- ImGuiTableTempData
        t.AngledHeadersRequests:clear()
        t.DrawSplitter:ClearFreeMemory()
        t.LastTimeActive = -1.0
        return
    end
    --IMGUI_DEBUG_PRINT("TableGcCompactTransientBuffers() id=0x%08X\n", t.ID)
    local g = GImGui
    local table_ = t
    IM_ASSERT(table_.MemoryCompacted == false)
    table_.SortSpecs.Specs = nil
    table.clear(table_.SortSpecsMulti)
    table_.IsSortSpecsDirty = true -- FIXME: In theory shouldn't have to leak into user performing a sort on resume.
    table.clear(table_.ColumnsNames)
    table_.MemoryCompacted = true
    for n = 0, table_.ColumnsCount - 1 do
        table_.Columns[n].NameOffset = -1
    end
    g.TablesLastTimeActive.Data[g.Tables:GetIndex(table_) + 1] = -1.0
end

-- Compact and remove unused or resize settings data (only TestEngine mark unused, but resizing table down can lead to compaction)
function ImGui.TableGcCompactSettings()
    local g = GImGui
    local has_dead = false
    for _, settings in g.SettingsTables:iter() do
        if settings.ID == 0 then has_dead = true end
    end
    if not has_dead then
        return
    end
    local new_list = ImVector()
    for _, settings in g.SettingsTables:iter() do
        if settings.ID ~= 0 then new_list:push_back(settings) end
    end
    g.SettingsTables = new_list
    ForEachTable(g, function(t) t.SettingsOffset = -1 end)
end

-------------------------------------------------------------------------------
-- [SECTION] Columns, BeginColumns, EndColumns, etc.
-- (This is a legacy API, prefer using BeginTable/EndTable!)
-------------------------------------------------------------------------------
-- FIXME: sizing is lossy when columns width is very small (default width may turn negative etc.)
-------------------------------------------------------------------------------
-- - GetColumnIndex()
-- - GetColumnsCount()
-- - GetColumnOffset()
-- - GetColumnWidth()
-- - SetColumnOffset()
-- - SetColumnWidth()
-- - PushColumnClipRect() [Internal]
-- - PushColumnsBackground() [Internal]
-- - PopColumnsBackground() [Internal]
-- - FindOrCreateColumns() [Internal]
-- - GetColumnsID() [Internal]
-- - BeginColumns()
-- - NextColumn()
-- - EndColumns()
-- - Columns()
-------------------------------------------------------------------------------
-- (Lua: columns.Columns is an ImVector, column n lives in .Data[n + 1])

function ImGui.GetColumnIndex()
    local window = ImGui.GetCurrentWindowRead()
    return window.DC.CurrentColumns and window.DC.CurrentColumns.Current or 0
end

function ImGui.GetColumnsCount()
    local window = ImGui.GetCurrentWindowRead()
    return window.DC.CurrentColumns and window.DC.CurrentColumns.Count or 1
end

function ImGui.GetColumnOffsetFromNorm(columns, offset_norm)
    return offset_norm * (columns.OffMaxX - columns.OffMinX)
end

function ImGui.GetColumnNormFromOffset(columns, offset)
    return offset / (columns.OffMaxX - columns.OffMinX)
end

local COLUMNS_HIT_RECT_HALF_THICKNESS = 4.0

local function GetDraggedColumnOffset(columns, column_index)
    -- Active (dragged) column always follow mouse. The reason we need this is that dragging a column to the right edge of an auto-resizing
    -- window creates a feedback loop because we store normalized positions. So while dragging we enforce absolute positioning.
    local g = GImGui
    local window = g.CurrentWindow
    IM_ASSERT(column_index > 0) -- We are not supposed to drag column 0.
    IM_ASSERT(g.ActiveId == band(columns.ID + column_index, 0xFFFFFFFF))

    local x = g.IO.MousePos.x - g.ActiveIdClickOffset.x + ImTrunc(COLUMNS_HIT_RECT_HALF_THICKNESS * g.CurrentDpiScale) - window.Pos.x
    x = ImMax(x, ImGui.GetColumnOffset(column_index - 1) + g.Style.ColumnsMinSpacing)
    if band(columns.Flags, ImGuiOldColumnFlags.NoPreserveWidths) ~= 0 then
        x = ImMin(x, ImGui.GetColumnOffset(column_index + 1) - g.Style.ColumnsMinSpacing)
    end

    return x
end

function ImGui.GetColumnOffset(column_index)
    if column_index == nil then column_index = -1 end
    local window = ImGui.GetCurrentWindowRead()
    local columns = window.DC.CurrentColumns
    if columns == nil then
        return 0.0
    end

    if column_index < 0 then
        column_index = columns.Current
    end
    IM_ASSERT(column_index < columns.Columns.Size)

    local t = columns.Columns.Data[column_index + 1].OffsetNorm
    local x_offset = ImLerp(columns.OffMinX, columns.OffMaxX, t)
    return x_offset
end

local function GetColumnWidthEx(columns, column_index, before_resize)
    if column_index < 0 then
        column_index = columns.Current
    end

    local d = columns.Columns.Data
    local offset_norm
    if before_resize then
        offset_norm = d[column_index + 2].OffsetNormBeforeResize - d[column_index + 1].OffsetNormBeforeResize
    else
        offset_norm = d[column_index + 2].OffsetNorm - d[column_index + 1].OffsetNorm
    end
    return ImGui.GetColumnOffsetFromNorm(columns, offset_norm)
end

function ImGui.GetColumnWidth(column_index)
    if column_index == nil then column_index = -1 end
    local g = GImGui
    local window = g.CurrentWindow
    local columns = window.DC.CurrentColumns
    if columns == nil then
        return ImGui.GetContentRegionAvail().x
    end

    if column_index < 0 then
        column_index = columns.Current
    end
    local d = columns.Columns.Data
    return ImGui.GetColumnOffsetFromNorm(columns, d[column_index + 2].OffsetNorm - d[column_index + 1].OffsetNorm)
end

function ImGui.SetColumnOffset(column_index, offset)
    local g = GImGui
    local window = g.CurrentWindow
    local columns = window.DC.CurrentColumns
    IM_ASSERT(columns ~= nil)

    if column_index < 0 then
        column_index = columns.Current
    end
    IM_ASSERT(column_index < columns.Columns.Size)

    local preserve_width = band(columns.Flags, ImGuiOldColumnFlags.NoPreserveWidths) == 0 and (column_index < columns.Count - 1)
    local width = preserve_width and GetColumnWidthEx(columns, column_index, columns.IsBeingResized) or 0.0

    if band(columns.Flags, ImGuiOldColumnFlags.NoForceWithinWindow) == 0 then
        offset = ImMin(offset, columns.OffMaxX - g.Style.ColumnsMinSpacing * (columns.Count - column_index))
    end
    columns.Columns.Data[column_index + 1].OffsetNorm = ImGui.GetColumnNormFromOffset(columns, offset - columns.OffMinX)

    if preserve_width then
        ImGui.SetColumnOffset(column_index + 1, offset + ImMax(g.Style.ColumnsMinSpacing, width))
    end
end

function ImGui.SetColumnWidth(column_index, width)
    local window = ImGui.GetCurrentWindowRead()
    local columns = window.DC.CurrentColumns
    IM_ASSERT(columns ~= nil)

    if column_index < 0 then
        column_index = columns.Current
    end
    ImGui.SetColumnOffset(column_index + 1, ImGui.GetColumnOffset(column_index) + width)
end

function ImGui.PushColumnClipRect(column_index)
    local window = ImGui.GetCurrentWindowRead()
    local columns = window.DC.CurrentColumns
    if column_index < 0 then
        column_index = columns.Current
    end

    local column = columns.Columns.Data[column_index + 1]
    ImGui.PushClipRect(column.ClipRect.Min, column.ClipRect.Max, false)
end

-- Get into the columns background draw command (which is generally the same draw command as before we called BeginColumns)
function ImGui.PushColumnsBackground()
    local window = ImGui.GetCurrentWindowRead()
    local columns = window.DC.CurrentColumns
    if columns.Count == 1 then
        return
    end

    -- Optimization: avoid SetCurrentChannel() + PushClipRect()
    ImRect_Copy(columns.HostBackupClipRect, window.ClipRect)
    ImGui.SetWindowClipRectBeforeSetChannel(window, columns.HostInitialClipRect)
    columns.Splitter:SetCurrentChannel(window.DrawList, 0)
end

function ImGui.PopColumnsBackground()
    local window = ImGui.GetCurrentWindowRead()
    local columns = window.DC.CurrentColumns
    if columns.Count == 1 then
        return
    end

    -- Optimization: avoid PopClipRect() + SetCurrentChannel()
    ImGui.SetWindowClipRectBeforeSetChannel(window, columns.HostBackupClipRect)
    columns.Splitter:SetCurrentChannel(window.DrawList, columns.Current + 1)
end

function ImGui.FindOrCreateColumns(window, id)
    -- We have few columns per window so for now we don't need bother much with turning this into a faster lookup.
    for _, c in window.ColumnsStorage:iter() do
        if c.ID == id then
            return c
        end
    end

    local columns = ImGuiOldColumns()
    window.ColumnsStorage:push_back(columns)
    columns.ID = id
    return columns
end

function ImGui.GetColumnsID(str_id, columns_count)
    local window = ImGui.GetCurrentWindow()

    -- Differentiate column ID with an arbitrary prefix for cases where users name their columns set the same as another widget.
    -- In addition, when an identifier isn't explicitly provided we include the number of columns in the hash to make it uniquer.
    ImGui.PushID(0x11223347 + (str_id and 0 or columns_count))
    local id = window:GetID(str_id or "columns")
    ImGui.PopID()

    return id
end

function ImGui.BeginColumns(str_id, columns_count, flags)
    if flags == nil then flags = 0 end
    local g = GImGui
    local window = ImGui.GetCurrentWindow()

    IM_ASSERT(columns_count >= 1)
    IM_ASSERT(window.DC.CurrentColumns == nil) -- Nested columns are currently not supported

    -- Acquire storage for the columns set
    local id = ImGui.GetColumnsID(str_id, columns_count)
    local columns = ImGui.FindOrCreateColumns(window, id)
    IM_ASSERT(columns.ID == id)
    columns.Current = 0
    columns.Count = columns_count
    columns.Flags = flags
    window.DC.CurrentColumns = columns
    window.DC.NavIsScrollPushableX = false -- Shortcut for NavUpdateCurrentWindowIsScrollPushableX();

    columns.HostCursorPosY = window.DC.CursorPos.y
    columns.HostCursorMaxPosX = window.DC.CursorMaxPos.x
    ImRect_Copy(columns.HostInitialClipRect, window.ClipRect)
    ImRect_Copy(columns.HostBackupParentWorkRect, window.ParentWorkRect)
    ImRect_Copy(window.ParentWorkRect, window.WorkRect)

    -- Set state for first column
    -- We aim so that the right-most column will have the same clipping width as other after being clipped by parent ClipRect
    local column_padding = g.Style.ItemSpacing.x
    local half_clip_extend_x = ImTrunc(ImMax(window.WindowPadding.x * 0.5, window.WindowBorderSize))
    local max_1 = window.WorkRect.Max.x + column_padding - ImMax(column_padding - window.WindowPadding.x, 0.0)
    local max_2 = window.WorkRect.Max.x + half_clip_extend_x
    columns.OffMinX = window.DC.Indent.x - column_padding + ImMax(column_padding - window.WindowPadding.x, 0.0)
    columns.OffMaxX = ImMax(ImMin(max_1, max_2) - window.Pos.x, columns.OffMinX + 1.0)
    columns.LineMinY = window.DC.CursorPos.y; columns.LineMaxY = window.DC.CursorPos.y

    -- Clear data if columns count changed
    if columns.Columns.Size ~= 0 and columns.Columns.Size ~= columns_count + 1 then
        columns.Columns:resize(0)
    end

    -- Initialize default widths
    columns.IsFirstFrame = (columns.Columns.Size == 0)
    if columns.Columns.Size == 0 then
        for n = 0, columns_count do
            local column = ImGuiOldColumnData()
            column.OffsetNorm = n / columns_count
            columns.Columns:push_back(column)
        end
    end

    for n = 0, columns_count - 1 do
        -- Compute clipping rectangle
        local column = columns.Columns.Data[n + 1]
        local clip_x1 = IM_ROUND(window.Pos.x + ImGui.GetColumnOffset(n))
        local clip_x2 = IM_ROUND(window.Pos.x + ImGui.GetColumnOffset(n + 1) - 1.0)
        column.ClipRect = ImRect(clip_x1, -FLT_MAX, clip_x2, FLT_MAX)
        column.ClipRect:ClipWithFull(window.ClipRect)
    end

    if columns.Count > 1 then
        columns.Splitter:Split(window.DrawList, 1 + columns.Count)
        columns.Splitter:SetCurrentChannel(window.DrawList, 1)
        ImGui.PushColumnClipRect(0)
    end

    -- We don't generally store Indent.x inside ColumnsOffset because it may be manipulated by the user.
    local offset_0 = ImGui.GetColumnOffset(columns.Current)
    local offset_1 = ImGui.GetColumnOffset(columns.Current + 1)
    local width = offset_1 - offset_0
    ImGui.PushItemWidth(width * 0.65)
    window.DC.ColumnsOffset.x = ImMax(column_padding - window.WindowPadding.x, 0.0)
    window.DC.CursorPos.x = IM_TRUNC(window.Pos.x + window.DC.Indent.x + window.DC.ColumnsOffset.x)
    window.WorkRect.Max.x = window.Pos.x + offset_1 - column_padding
    window.WorkRect.Max.y = window.ContentRegionRect.Max.y
end

function ImGui.NextColumn()
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems or window.DC.CurrentColumns == nil then
        return
    end

    local g = GImGui
    local columns = window.DC.CurrentColumns

    if columns.Count == 1 then
        window.DC.CursorPos.x = IM_TRUNC(window.Pos.x + window.DC.Indent.x + window.DC.ColumnsOffset.x)
        IM_ASSERT(columns.Current == 0)
        return
    end

    -- Next column
    columns.Current = columns.Current + 1
    if columns.Current == columns.Count then
        columns.Current = 0
    end

    ImGui.PopItemWidth()

    -- Optimization: avoid PopClipRect() + SetCurrentChannel() + PushClipRect()
    -- (which would needlessly attempt to update commands in the wrong channel, then pop or overwrite them),
    local column = columns.Columns.Data[columns.Current + 1]
    ImGui.SetWindowClipRectBeforeSetChannel(window, column.ClipRect)
    columns.Splitter:SetCurrentChannel(window.DrawList, columns.Current + 1)

    local column_padding = g.Style.ItemSpacing.x
    columns.LineMaxY = ImMax(columns.LineMaxY, window.DC.CursorPos.y)
    if columns.Current > 0 then
        -- Columns 1+ ignore IndentX (by canceling it out)
        -- FIXME-COLUMNS: Unnecessary, could be locked?
        window.DC.ColumnsOffset.x = ImGui.GetColumnOffset(columns.Current) - window.DC.Indent.x + column_padding
    else
        -- New row/line: column 0 honor IndentX.
        window.DC.ColumnsOffset.x = ImMax(column_padding - window.WindowPadding.x, 0.0)
        window.DC.IsSameLine = false
        columns.LineMinY = columns.LineMaxY
    end
    window.DC.CursorPos.x = IM_TRUNC(window.Pos.x + window.DC.Indent.x + window.DC.ColumnsOffset.x)
    window.DC.CursorPos.y = columns.LineMinY
    window.DC.CurrLineSize.x = 0.0; window.DC.CurrLineSize.y = 0.0
    window.DC.CurrLineTextBaseOffset = 0.0

    -- FIXME-COLUMNS: Share code with BeginColumns() - move code on columns setup.
    local offset_0 = ImGui.GetColumnOffset(columns.Current)
    local offset_1 = ImGui.GetColumnOffset(columns.Current + 1)
    local width = offset_1 - offset_0
    ImGui.PushItemWidth(width * 0.65)
    window.WorkRect.Max.x = window.Pos.x + offset_1 - column_padding
end

function ImGui.EndColumns()
    local g = GImGui
    local window = ImGui.GetCurrentWindow()
    local columns = window.DC.CurrentColumns
    IM_ASSERT(columns ~= nil)

    ImGui.PopItemWidth()
    if columns.Count > 1 then
        ImGui.PopClipRect()
        columns.Splitter:Merge(window.DrawList)
    end

    local flags = columns.Flags
    columns.LineMaxY = ImMax(columns.LineMaxY, window.DC.CursorPos.y)
    window.DC.CursorPos.y = columns.LineMaxY
    if band(flags, ImGuiOldColumnFlags.GrowParentContentsSize) == 0 then
        window.DC.CursorMaxPos.x = columns.HostCursorMaxPosX -- Restore cursor max pos, as columns don't grow parent
    end

    -- Draw columns borders and handle resize
    -- The IsBeingResized flag ensure we preserve pre-resize columns width so back-and-forth are not lossy
    local is_being_resized = false
    if band(flags, ImGuiOldColumnFlags.NoBorder) == 0 and not window.SkipItems then
        -- We clip Y boundaries CPU side because very long triangles are mishandled by some GPU drivers.
        local y1 = ImMax(columns.HostCursorPosY, window.ClipRect.Min.y)
        local y2 = ImMin(window.DC.CursorPos.y, window.ClipRect.Max.y)
        local dragging_column = -1
        for n = 1, columns.Count - 1 do
            local column = columns.Columns.Data[n + 1]
            local x = window.Pos.x + ImGui.GetColumnOffset(n)
            local column_id = band(columns.ID + n, 0xFFFFFFFF)
            local column_hit_hw = ImTrunc(COLUMNS_HIT_RECT_HALF_THICKNESS * g.CurrentDpiScale)
            local column_hit_rect = ImRect(ImVec2(x - column_hit_hw, y1), ImVec2(x + column_hit_hw, y2))
            if ImGui.ItemAdd(column_hit_rect, column_id, nil, ImGuiItemFlags.NoNav) then
                local hovered, held = false, false
                if band(flags, ImGuiOldColumnFlags.NoResize) == 0 then
                    local _
                    _, hovered, held = ImGui.ButtonBehavior(column_hit_rect, column_id)
                    if hovered or held then
                        ImGui.SetMouseCursor(ImGuiMouseCursor.ResizeEW)
                    end
                    if held and band(column.Flags, ImGuiOldColumnFlags.NoResize) == 0 then
                        dragging_column = n
                    end
                end

                -- Draw column
                local col = ImGui.GetColorU32(held and ImGuiCol.SeparatorActive or (hovered and ImGuiCol.SeparatorHovered or ImGuiCol.Separator))
                local xi = IM_TRUNC(x)
                window.DrawList:AddLineV(xi, y1 + 1.0, y2, col)
            end
        end

        -- Apply dragging after drawing the column lines, so our rendered lines are in sync with how items were displayed during the frame.
        if dragging_column ~= -1 then
            if not columns.IsBeingResized then
                for n = 0, columns.Count do
                    local c = columns.Columns.Data[n + 1]
                    c.OffsetNormBeforeResize = c.OffsetNorm
                end
            end
            columns.IsBeingResized = true; is_being_resized = true
            local x = GetDraggedColumnOffset(columns, dragging_column)
            ImGui.SetColumnOffset(dragging_column, x)
        end
    end
    columns.IsBeingResized = is_being_resized

    ImRect_Copy(window.WorkRect, window.ParentWorkRect)
    ImRect_Copy(window.ParentWorkRect, columns.HostBackupParentWorkRect)
    window.DC.CurrentColumns = nil
    window.DC.ColumnsOffset.x = 0.0
    window.DC.CursorPos.x = IM_TRUNC(window.Pos.x + window.DC.Indent.x + window.DC.ColumnsOffset.x)
    ImGui.NavUpdateCurrentWindowIsScrollPushableX()
end

--- @param columns_count? int
--- @param id?            string
--- @param borders?       bool
function ImGui.Columns(columns_count, id, borders)
    if columns_count == nil then columns_count = 1 end
    if borders == nil then borders = true end
    local window = ImGui.GetCurrentWindow()
    IM_ASSERT(columns_count >= 1)

    local flags = borders and 0 or ImGuiOldColumnFlags.NoBorder
    --flags = bor(flags, ImGuiOldColumnFlags.NoPreserveWidths) -- NB: Legacy behavior
    local columns = window.DC.CurrentColumns
    if columns ~= nil and columns.Count == columns_count and columns.Flags == flags then
        return
    end

    if columns ~= nil then
        ImGui.EndColumns()
    end

    if columns_count ~= 1 then
        ImGui.BeginColumns(id, columns_count, flags)
    end
end

return true -- [Roblox] ModuleScripts must return exactly one value
end

__FILES['imgui_widgets.lua'] = function()
--- Dear ImGui WIP
-- (widgets code)

--
-- Index of this file:
--
-- [SECTION] Widgets: Text, etc.
-- [SECTION] Widgets: Value helpers
-- [SECTION] Widgets: Main (Button, Image, Checkbox, RadioButton, ProgressBar, Bullet, etc.)
-- [SECTION] Widgets: Low-level Layout helpers (Spacing, Dummy, NewLine, Separator, etc.)
-- [SECTION] Widgets: ComboBox
-- [SECTION] Data Type and Data Formatting Helpers
-- [SECTION] Widgets: DragScalar, DragFloat, DragInt, etc.
-- [SECTION] Widgets: SliderScalar, SliderFloat, SliderInt, etc.
-- [SECTION] Widgets: InputScalar, InputFloat, InputInt, etc.
-- [SECTION] Widgets: InputText, InputTextMultiline
-- [SECTION] Widgets: ColorEdit, ColorPicker, ColorButton, etc.
-- [SECTION] Widgets: TreeNode, CollapsingHeader, etc.
-- [SECTION] Widgets: Selectable
-- [SECTION] Widgets: ListBox
-- [SECTION] Widgets: PlotLines, PlotHistogram
-- [SECTION] Widgets: MenuItem, BeginMenu, EndMenu, etc.
-- [SECTION] Widgets: BeginTabBar, EndTabBar, etc.
-- [SECTION] Widgets: BeginTabItem, EndTabItem, etc.
--

--- @type ImGuiContext?
local GImGui

-- Sets local `GImGui` in this file(imgui_widgets.lua).
-- This is currently only used in main code `ImGui.SetCurrentContext()`
--- @param ctx ImGuiContext?
function ImGui._SetCurrentContext_Widgets(ctx)
    GImGui = ctx
end

-------------------------------------------------------------------------------
-- Data
-------------------------------------------------------------------------------

-- Widgets
local DRAGDROP_HOLD_TO_OPEN_TIMER = 0.70 -- Time for drag-hold to activate items accepting the ImGuiButtonFlags.PressedOnDragDropHold button behavior.
local DRAG_MOUSE_THRESHOLD_FACTOR = 0.50 -- Multiplier for the default value of io.MouseDragThreshold to make DragFloat/DragInt react faster to mouse drags.

local IM_S8_MIN = -128
local IM_S8_MAX = 127
local IM_U8_MIN = 0
local IM_U8_MAX = 0xFF
local IM_S16_MIN = -32768
local IM_S16_MAX = 32767
local IM_U16_MIN = 0
local IM_U16_MAX = 0xFFFF
local IM_S32_MIN = INT_MIN -- (-2147483647 - 1), (0x80000000);
local IM_S32_MAX = INT_MAX -- (2147483647), (0x7FFFFFFF)
local IM_U32_MIN = 0
local IM_U32_MAX = UINT_MAX -- (0xFFFFFFFF)

-------------------------------------------------------------------------------
-- [SECTION] Widgets: Text, etc.
-------------------------------------------------------------------------------
-- - TextEx() [Internal]
-- - TextUnformatted()
-- - Text()
-- - TextV()
-- - TextColored()
-- - TextDisabled()
-- - TextWrapped()
-- - TextAligned()
-- - LabelText()
-- - BulletText()
-------------------------------------------------------------------------------

--- @param text      string
--- @param text_end? int
--- @param flags?    ImGuiTextFlags

function ImGui.TextEx(text, text_end, flags)
    if not flags then flags = 0 end

    local g = GImGui
    local window = g.CurrentWindow
    if window.SkipItems then
        return
    end

    -- Accept null ranges
    if not text or text == "" then
        text = ""
        text_end = 1
    end

    -- Calculate length
    if text_end == nil then
        text_end = #text + 1
    end

    local text_pos = ImVec2(window.DC.CursorPos.x, window.DC.CursorPos.y + window.DC.CurrLineTextBaseOffset)
    local wrap_pos_x = window.DC.TextWrapPos
    local wrap_enabled = (wrap_pos_x >= 0.0)
    if (text_end - 1 <= 2000) or wrap_enabled then
        -- Common case
        local wrap_width = wrap_enabled and ImGui.CalcWrapWidthForPos(window.DC.CursorPos, wrap_pos_x) or 0.0
        local text_size = ImGui.CalcTextSize(text, text_end, false, wrap_width)

        local bb = ImRect(text_pos, text_pos + text_size)
        ImGui.ItemSize(text_size, 0.0)
        if not ImGui.ItemAdd(bb, 0) then
            return
        end

        -- Render (we don't hide text after ## in this end-user function)
        ImGui.RenderTextWrapped(bb.Min, text, text_end, wrap_width)
    else
        -- Long text!
        -- Perform manual coarse clipping to optimize for long multi-line text
        -- - From this point we will only compute the width of lines that are visible. Optimization only available when word-wrapping is disabled.
        -- - We also don't vertically center the text within the line full height, which is unlikely to matter because we are likely the biggest and only item on the line.
        local line = 1
        local line_height = ImGui.GetTextLineHeight()
        local text_size = ImVec2(0, 0)

        -- Lines to skip (can't skip when logging text)
        local pos = ImVec2(text_pos.x, text_pos.y)
        if not g.LogEnabled then
            local lines_skippable = ImFloor((window.ClipRect.Min.y - text_pos.y) / line_height)
            if lines_skippable > 0 then
                local lines_skipped = 0
                while line < text_end and lines_skipped < lines_skippable do
                    local line_end = ImMemchr(text, "\n", line)
                    if not line_end then
                        line_end = text_end
                    end
                    if bit32.band(flags, ImGuiTextFlags.NoWidthForLargeClippedText) == 0 then
                        local line_size = ImGui.CalcTextSizeEx(text, line, line_end)
                        text_size.x = ImMax(text_size.x, line_size.x)
                    end
                    line = line_end + 1
                    lines_skipped = lines_skipped + 1
                end
                pos.y = pos.y + lines_skipped * line_height
            end
        end

        -- Lines to render
        if line < text_end then
            local line_rect = ImRect(pos, pos + ImVec2(FLT_MAX, line_height))
            while line < text_end do
                if ImGui.IsClippedEx(line_rect, 0) then
                    break
                end

                local line_end = ImMemchr(text, "\n", line)
                if not line_end then
                    line_end = text_end
                end

                local line_size = ImGui.CalcTextSizeEx(text, line, line_end)
                text_size.x = ImMax(text_size.x, line_size.x)
                ImGui.RenderText(pos, text, line, nil, false)
                line = line_end + 1
                line_rect.Min.y = line_rect.Min.y + line_height
                line_rect.Max.y = line_rect.Max.y + line_height
                pos.y = pos.y + line_height
            end

            -- Count remaining lines
            local lines_skipped = 0
            while line < text_end do
                local line_end = ImMemchr(text, "\n", line)
                if not line_end then
                    line_end = text_end
                end
                if bit32.band(flags, ImGuiTextFlags.NoWidthForLargeClippedText) == 0 then
                    local line_size = ImGui.CalcTextSizeEx(text, line, line_end)
                    text_size.x = ImMax(text_size.x, line_size.x)
                end
                line = line_end + 1
                lines_skipped = lines_skipped + 1
            end
            pos.y = pos.y + lines_skipped * line_height
        end
        text_size.y = pos.y - text_pos.y

        local bb = ImRect(text_pos, text_pos + text_size)
        ImGui.ItemSize(text_size, 0.0)
        ImGui.ItemAdd(bb, 0)
    end
end

--- @param text      string
--- @param text_end? int
function ImGui.TextUnformatted(text, text_end)
    ImGui.TextEx(text, text_end, ImGuiTextFlags.NoWidthForLargeClippedText)
end

--- @param fmt string
--- @param ... any

function ImGui.TextV(fmt, ...)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local text = ImFormatString(fmt, ...)
    ImGui.TextEx(text, nil, ImGuiTextFlags.NoWidthForLargeClippedText)
end

--- @param fmt string
--- @param ... any

function ImGui.Text(fmt, ...)
    if select('#', ...) > 0 then
        ImGui.TextV(fmt, ...)
    else
        ImGui.TextEx(fmt)
    end
end

--- @param col ImVec4
--- @param fmt string
--- @param ... any
function ImGui.TextColored(col, fmt, ...)
    ImGui.PushStyleColor(ImGuiCol.Text, col)
    ImGui.TextV(fmt, ...)
    ImGui.PopStyleColor()
end

--- @param fmt string
--- @param ... any
function ImGui.TextDisabled(fmt, ...)
    local g = GImGui
    ImGui.PushStyleColor(ImGuiCol.Text, g.Style.Colors[ImGuiCol.TextDisabled])
    ImGui.TextV(fmt, ...)
    ImGui.PopStyleColor()
end

--- @param fmt string
--- @param ... any
function ImGui.TextWrapped(fmt, ...)
    local g = GImGui
    local need_backup = (g.CurrentWindow.DC.TextWrapPos < 0.0) -- Keep existing wrap position if one is already set
    if need_backup then
        ImGui.PushTextWrapPos(0.0)
    end
    ImGui.TextV(fmt, ...)
    if need_backup then
        ImGui.PopTextWrapPos()
    end
end

-- align_x: 0.0f = left, 0.5f = center, 1.0f = right.
-- size_x < 0.0f (e.g. -FLT_MIN): shortcut for GetContentRegionAvail().x
-- FIXME-WIP: Works but API is likely to be reworked. This is designed for 1 item on the line. (#7024, #9455)
--- @param align_x float
--- @param size_x  float
--- @param fmt     string
--- @param ...     any
function ImGui.TextAligned(align_x, size_x, fmt, ...)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local text = ImFormatString(fmt, ...)
    local text_end = #text + 1
    local text_size = ImGui.CalcTextSize(text, text_end)
    size_x = ImGui.CalcItemSize(ImVec2(size_x, 0.0), 0.0, text_size.y).x

    local pos = ImVec2(window.DC.CursorPos.x, window.DC.CursorPos.y + window.DC.CurrLineTextBaseOffset)
    local pos_max = ImVec2(pos.x + size_x, window.ClipRect.Max.y)
    local size = ImVec2(ImMin(size_x, text_size.x), text_size.y)
    window.DC.CursorMaxPos.x = ImMax(window.DC.CursorMaxPos.x, pos.x + text_size.x)
    window.DC.IdealMaxPos.x = ImMax(window.DC.IdealMaxPos.x, pos.x + text_size.x)
    if align_x > 0.0 and text_size.x < size_x then
        pos.x = pos.x + ImTrunc((size_x - text_size.x) * align_x)
    end
    ImGui.RenderTextEllipsis(window.DrawList, pos, pos_max, pos_max.x, text, text_end, text_size)

    local backup_max_pos = ImVec2()
    ImVec2_Copy(backup_max_pos, window.DC.CursorMaxPos)
    ImGui.ItemSize(size)
    ImGui.ItemAdd(ImRect(pos, pos + size), 0)
    window.DC.CursorMaxPos.x = backup_max_pos.x -- Cancel out extending content to 'size' to use 'text_size' allowing auto-resize to function with align_x > 0.0f

    if size_x < text_size.x and ImGui.IsItemHovered(bit32.bor(ImGuiHoveredFlags.NoNavOverride, ImGuiHoveredFlags.AllowWhenDisabled, ImGuiHoveredFlags.ForTooltip)) then
        ImGui.SetTooltip("%.*s", text_end - 1, text)
    end
end

-- Add a label+text combo aligned to other label+value widgets
--- @param label string
--- @param fmt   string
--- @param ...   any
function ImGui.LabelText(label, fmt, ...)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    local style = g.Style
    local w = ImGui.CalcItemWidth()

    local value_text = ImFormatString(fmt, ...)
    local value_text_end = #value_text + 1
    local value_size = ImGui.CalcTextSize(value_text, value_text_end, false)
    local label_end = ImGui.FindRenderedTextEnd(label)
    local label_size = ImGui.CalcTextSize(label, label_end, false)

    local pos = ImVec2()
    ImVec2_Copy(pos, window.DC.CursorPos)
    local value_bb = ImRect(pos, pos + ImVec2(w, value_size.y + style.FramePadding.y * 2))
    local total_bb = ImRect(pos, pos + ImVec2(w + ((label_size.x > 0.0) and (style.ItemInnerSpacing.x + label_size.x) or 0.0), ImMax(value_size.y, label_size.y) + style.FramePadding.y * 2))
    ImGui.ItemSize(total_bb, style.FramePadding.y)
    if not ImGui.ItemAdd(total_bb, 0) then
        return
    end

    -- Render
    ImGui.RenderTextClipped(value_bb.Min + style.FramePadding, value_bb.Max, value_text, value_text_end, value_size, ImVec2(0.0, 0.0))
    if label_size.x > 0.0 then
        ImGui.RenderText(ImVec2(value_bb.Max.x + style.ItemInnerSpacing.x, value_bb.Min.y + style.FramePadding.y), label, 1, label_end, false)
    end
end

-- Text with a little bullet aligned to the typical tree node.
--- @param fmt string
--- @param ... any
function ImGui.BulletText(fmt, ...)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    local style = g.Style

    local text = ImFormatString(fmt, ...)
    local text_end = #text + 1
    local label_size = ImGui.CalcTextSize(text, text_end, false)
    local total_size = ImVec2(g.FontSize + ((label_size.x > 0.0) and (label_size.x + style.FramePadding.x * 2) or 0.0), label_size.y) -- Empty text doesn't add padding
    local pos = ImVec2()
    ImVec2_Copy(pos, window.DC.CursorPos)
    pos.y = pos.y + window.DC.CurrLineTextBaseOffset
    ImGui.ItemSize(total_size, 0.0)
    local bb = ImRect(pos, pos + total_size)
    if not ImGui.ItemAdd(bb, 0) then
        return
    end

    -- Render
    local text_col = ImGui.GetColorU32(ImGuiCol.Text)
    ImGui.RenderBullet(window.DrawList, bb.Min + ImVec2(style.FramePadding.x + g.FontSize * 0.5, g.FontSize * 0.5), text_col)
    ImGui.RenderText(bb.Min + ImVec2(g.FontSize + style.FramePadding.x * 2, 0.0), text, 1, text_end, false)
end

-- va_list variants: identical to the varargs versions in Lua
ImGui.TextColoredV = ImGui.TextColored
ImGui.TextDisabledV = ImGui.TextDisabled
ImGui.TextWrappedV = ImGui.TextWrapped
ImGui.TextAlignedV = ImGui.TextAligned
ImGui.LabelTextV = ImGui.LabelText
ImGui.BulletTextV = ImGui.BulletText

-------------------------------------------------------------------------------
-- [SECTION] Widgets: Value helpers
-- Those is not very useful, legacy API.
-------------------------------------------------------------------------------
-- - Value()
-------------------------------------------------------------------------------

-- Value(prefix, b) / Value(prefix, int) / Value(prefix, float, float_format)
-- Lua can't tell int from float: integers without float_format print as %d, otherwise %.3f
function ImGui.Value(prefix, v, float_format)
    if type(v) == "boolean" then
        ImGui.Text("%s: %s", prefix, v and "true" or "false")
    elseif float_format then
        ImGui.Text("%s: " .. float_format, prefix, v)
    elseif math.floor(v) == v then
        ImGui.Text("%s: %d", prefix, v)
    else
        ImGui.Text("%s: %.3f", prefix, v)
    end
end

-------------------------------------------------------------------------------
-- [SECTION] Widgets: Main
-------------------------------------------------------------------------------
-- - ButtonBehavior() [Internal]
-- - Button()
-- - SmallButton()
-- - InvisibleButton()
-- - ArrowButton()
-- - CloseButton() [Internal]
-- - CollapseButton() [Internal]
-- - GetWindowScrollbarID() [Internal]
-- - GetWindowScrollbarRect() [Internal]
-- - Scrollbar() [Internal]
-- - ScrollbarEx() [Internal]
-- - Image()
-- - ImageButton()
-- - Checkbox()
-- - CheckboxFlagsT() [Internal]
-- - CheckboxFlags()
-- - RadioButton()
-- - ProgressBar()
-- - Bullet()
-- - Hyperlink()
-------------------------------------------------------------------------------

-- The ButtonBehavior() function is key to many interactions and used by many/most widgets.
-- Because we handle so many cases (keyboard/gamepad navigation, drag and drop) and many specific behavior (via ImGuiButtonFlags),
-- this code is a little complex.
-- By far the most common path is interacting with the Mouse using the default ImGuiButtonFlags.PressedOnClickRelease button behavior.
-- See the series of events below and the corresponding state reported by dear imgui:
-------------------------------------------------------------------------------
-- with PressedOnClickRelease:             return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
--   Frame N+0 (mouse is outside bb)        -             -                -               -                  -                    -
--   Frame N+1 (mouse moves inside bb)      -             true             -               -                  -                    -
--   Frame N+2 (mouse button is down)       -             true             true            true               -                    true
--   Frame N+3 (mouse button is down)       -             true             true            -                  -                    -
--   Frame N+4 (mouse moves outside bb)     -             -                true            -                  -                    -
--   Frame N+5 (mouse moves inside bb)      -             true             true            -                  -                    -
--   Frame N+6 (mouse button is released)   true          true             -               -                  true                 -
--   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
--   Frame N+8 (mouse moves outside bb)     -             -                -               -                  -                    -
-------------------------------------------------------------------------------
-- with PressedOnClick:                    return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
--   Frame N+2 (mouse button is down)       true          true             true            true               -                    true
--   Frame N+3 (mouse button is down)       -             true             true            -                  -                    -
--   Frame N+6 (mouse button is released)   -             true             -               -                  true                 -
--   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
-------------------------------------------------------------------------------
-- with PressedOnRelease:                  return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
--   Frame N+2 (mouse button is down)       -             true             -               -                  -                    true
--   Frame N+3 (mouse button is down)       -             true             -               -                  -                    -
--   Frame N+6 (mouse button is released)   true          true             -               -                  -                    -
--   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
-------------------------------------------------------------------------------
-- with PressedOnDoubleClick:              return-value  IsItemHovered()  IsItemActive()  IsItemActivated()  IsItemDeactivated()  IsItemClicked()
--   Frame N+0 (mouse button is down)       -             true             -               -                  -                    true
--   Frame N+1 (mouse button is down)       -             true             -               -                  -                    -
--   Frame N+2 (mouse button is released)   -             true             -               -                  -                    -
--   Frame N+3 (mouse button is released)   -             true             -               -                  -                    -
--   Frame N+4 (mouse button is down)       true          true             true            true               -                    true
--   Frame N+5 (mouse button is down)       -             true             true            -                  -                    -
--   Frame N+6 (mouse button is released)   -             true             -               -                  true                 -
--   Frame N+7 (mouse button is released)   -             true             -               -                  -                    -
-------------------------------------------------------------------------------
-- Note that some combinations are supported,
-- - PressedOnDragDropHold can generally be associated with any flag.
-- - PressedOnDoubleClick can be associated by PressedOnClickRelease/PressedOnRelease, in which case the second release event won't be reported.
-------------------------------------------------------------------------------
-- The behavior of the return-value changes when ImGuiItemFlags.ButtonRepeat is set:
--                                         Repeat+                  Repeat+           Repeat+             Repeat+
--                                         PressedOnClickRelease    PressedOnClick    PressedOnRelease    PressedOnDoubleClick
-------------------------------------------------------------------------------
--   Frame N+0 (mouse button is down)       -                        true              -                   true
--   ...                                    -                        -                 -                   -
--   Frame N + RepeatDelay                  true                     true              -                   true
--   ...                                    -                        -                 -                   -
--   Frame N + RepeatDelay + RepeatRate*N   true                     true              -                   true
-------------------------------------------------------------------------------

-- - FIXME: For refactor we could output flags, incl mouse hovered vs nav keyboard vs nav triggered etc.
--   And better standardize how widgets use 'GetColor32((held && hovered) ? ... : hovered ? ...)' vs 'GetColor32(held ? ... : hovered ? ...);'
--   For mouse feedback we typically prefer the 'held && hovered' test, but for nav feedback not always. Outputting hovered=true on Activation may be misleading.
-- - Since v1.91.2 (Sept 2024) we included io.ConfigDebugHighlightIdConflicts feature.
--   One idiom which was previously valid which will now emit a warning is when using multiple overlaid ButtonBehavior()
--   with same ID and different MouseButton (see #8030). You can fix it by:
--       (1) switching to use a single ButtonBehavior() with multiple _MouseButton flags.
--    or (2) surrounding those calls with PushItemFlag(ImGuiItemFlags.AllowDuplicateId, true); ... PopItemFlag()
-- Returns (pressed, hovered, held).
--- @param bb     ImRect
--- @param id     ImGuiID
--- @param flags? ImGuiButtonFlags

function ImGui.ButtonBehavior(bb, id, flags)
    if flags == nil then flags = 0 end

    local g = GImGui

    local window = g.CurrentWindow

    -- Default behavior inherited from item flags
    -- Note that _both_ ButtonFlags and ItemFlags are valid sources, so copy one into the item_flags and only check that.
    local item_flags = (g.LastItemData.ID == id) and g.LastItemData.ItemFlags or g.CurrentItemFlags
    if bit32.band(flags, ImGuiButtonFlags.AllowOverlap) ~= 0 then
        item_flags = bit32.bor(item_flags, ImGuiItemFlags.AllowOverlap)
    end
    if bit32.band(item_flags, ImGuiItemFlags.NoFocus) ~= 0 then
        flags = bit32.bor(flags, ImGuiButtonFlags.NoFocus, ImGuiButtonFlags.NoNavFocus)
    end

    -- Default only reacts to left mouse button
    if bit32.band(flags, ImGuiButtonFlags.MouseButtonMask_) == 0 then
        flags = bit32.bor(flags, ImGuiButtonFlags.MouseButtonLeft)
    end

    -- Default behavior requires click + release inside bounding box
    if bit32.band(flags, ImGuiButtonFlags.PressedOnMask_) == 0 then
        flags = bit32.bor(flags, (bit32.band(item_flags, ImGuiItemFlags.ButtonRepeat) ~= 0) and ImGuiButtonFlags.PressedOnClick or ImGuiButtonFlags.PressedOnDefault_)
    end

    local backup_hovered_window = g.HoveredWindow
    local flatten_hovered_children = (bit32.band(flags, ImGuiButtonFlags.FlattenChildren) ~= 0) and g.HoveredWindow and g.HoveredWindow.RootWindowDockTree == window.RootWindowDockTree
    if flatten_hovered_children then
        g.HoveredWindow = window
    end

    local pressed = false
    local hovered = ImGui.ItemHoverable(bb, id, item_flags)

    -- Special mode for Drag and Drop used by openables (tree nodes, tabs etc.)
    -- where holding the button pressed for a long time while drag a payload item triggers the button.
    if g.DragDropActive then
        if (bit32.band(flags, ImGuiButtonFlags.PressedOnDragDropHold) ~= 0) and (bit32.band(g.DragDropSourceFlags, ImGuiDragDropFlags.SourceNoHoldToOpenOthers) == 0) and ImGui.IsItemHovered(ImGuiHoveredFlags.AllowWhenBlockedByActiveItem) then
            hovered = true
            ImGui.SetHoveredID(id)

            if (g.HoveredIdTimer - g.IO.DeltaTime <= DRAGDROP_HOLD_TO_OPEN_TIMER) and (g.HoveredIdTimer >= DRAGDROP_HOLD_TO_OPEN_TIMER) then
                pressed = true
                g.DragDropHoldJustPressedId = id
                ImGui.FocusWindow(window)
            end
        end

        if (g.DragDropAcceptIdPrev == id) and (bit32.band(g.DragDropAcceptFlagsPrev, ImGuiDragDropFlags.AcceptDrawAsHovered) ~= 0) then
            hovered = true
        end
    end

    if (flatten_hovered_children) then
        g.HoveredWindow = backup_hovered_window
    end

    -- Mouse handling
    local test_owner_id = (bit32.band(flags, ImGuiButtonFlags.NoTestKeyOwner) ~= 0) and ImGuiKeyOwner_Any or id
    if hovered then
        IM_ASSERT(id ~= 0) -- Lazily check inside rare path.

        -- Poll mouse buttons
        -- - 'mouse_button_clicked' is generally carried into ActiveIdMouseButton when setting ActiveId.
        -- - Technically we only need some values in one code path, but since this is gated by hovered test this is fine.
        local mouse_button_clicked = -1
        local mouse_button_released = -1
        for button = 0, 2 do
            if bit32.band(flags, bit32.lshift(ImGuiButtonFlags.MouseButtonLeft, button)) ~= 0 then -- Handle ImGuiButtonFlags.MouseButtonRight and ImGuiButtonFlags.MouseButtonMiddle here.
                if (ImGui.IsMouseClickedEx(button, ImGuiInputFlags.None, test_owner_id) and mouse_button_clicked == -1) then mouse_button_clicked = button end
                if (ImGui.IsMouseReleased(button, test_owner_id) and mouse_button_released == -1) then mouse_button_released = button end
            end
        end

        -- Process initial action
        local mods_ok = (bit32.band(flags, ImGuiButtonFlags.NoKeyModsAllowed) == 0) or (not g.IO.KeyCtrl and not g.IO.KeyShift and not g.IO.KeyAlt)
        if mods_ok then
            if mouse_button_clicked ~= -1 and g.ActiveId ~= id then
                --- @cast mouse_button_clicked ImGuiMouseButton

                if bit32.band(flags, ImGuiButtonFlags.NoSetKeyOwner) == 0 then
                    ImGui.SetKeyOwner(ImGui.MouseButtonToKey(mouse_button_clicked), id)
                end

                if bit32.band(flags, bit32.bor(ImGuiButtonFlags.PressedOnClickRelease, ImGuiButtonFlags.PressedOnClickReleaseAnywhere)) ~= 0 then
                    ImGui.SetActiveID(id, window)
                    g.ActiveIdMouseButton = mouse_button_clicked

                    if bit32.band(flags, ImGuiButtonFlags.NoNavFocus) == 0 then
                        ImGui.SetFocusID(id, window)
                        ImGui.FocusWindow(window)
                    elseif bit32.band(flags, ImGuiButtonFlags.NoFocus) == 0 then
                        ImGui.FocusWindow(window, ImGuiFocusRequestFlags.RestoreFocusedChild) -- Still need to focus and bring to front, but try to avoid losing NavId when navigating a child
                    end
                end

                if (bit32.band(flags, ImGuiButtonFlags.PressedOnClick) ~= 0) or ((bit32.band(flags, ImGuiButtonFlags.PressedOnDoubleClick) ~= 0) and g.IO.MouseClickedCount[mouse_button_clicked] == 2) then
                    pressed = true

                    if bit32.band(flags, ImGuiButtonFlags.NoHoldingActiveId) ~= 0 then
                        ImGui.ClearActiveID()
                    else
                        ImGui.SetActiveID(id, window) -- Hold on ID
                    end

                    g.ActiveIdMouseButton = mouse_button_clicked

                    if bit32.band(flags, ImGuiButtonFlags.NoNavFocus) == 0 then
                        ImGui.SetFocusID(id, window)
                        ImGui.FocusWindow(window)
                    elseif bit32.band(flags, ImGuiButtonFlags.NoFocus) == 0 then
                        ImGui.FocusWindow(window, ImGuiFocusRequestFlags.RestoreFocusedChild) -- Still need to focus and bring to front, but try to avoid losing NavId when navigating a child
                    end
                end

                if bit32.band(flags, ImGuiButtonFlags.PressedOnRelease) ~= 0 then
                    -- FIXME: Traditionally ImGuiButtonFlags.PressedOnRelease never took ActiveId. Adding it in 2026-03-20 since ImGuiButtonFlags.NoHoldingActiveId can always be added.
                    -- We don't yet perform an explicit ClearActiveID() to reduce scope of change, but this possibility could be investigated.
                    if bit32.band(flags, ImGuiButtonFlags.NoHoldingActiveId) == 0 then
                        ImGui.SetActiveID(id, window) -- Hold on ID
                    end
                    g.ActiveIdMouseButton = mouse_button_clicked
                end
            end

            if bit32.band(flags, ImGuiButtonFlags.PressedOnRelease) ~= 0 then
                if mouse_button_released ~= -1 then
                    local has_repeated_at_least_once = (bit32.band(item_flags, ImGuiItemFlags.ButtonRepeat) ~= 0) and g.IO.MouseDownDurationPrev[mouse_button_released] >= g.IO.KeyRepeatDelay -- Repeat mode trumps on release behavior

                    if not has_repeated_at_least_once then
                        pressed = true
                    end

                    if bit32.band(flags, ImGuiButtonFlags.NoNavFocus) == 0 then
                        ImGui.SetFocusID(id, window) -- FIXME: Lack of FocusWindow() call here is inconsistent with other paths. Research why.
                    end

                    ImGui.ClearActiveID()
                end
            end

            -- 'Repeat' mode acts when held regardless of _PressedOn flags (see table above).
            -- Relies on repeat logic of IsMouseClicked() but we may as well do it ourselves if we end up exposing finer RepeatDelay/RepeatRate settings.
            if g.ActiveId == id and (bit32.band(item_flags, ImGuiItemFlags.ButtonRepeat) ~= 0) then
                if g.IO.MouseDownDuration[g.ActiveIdMouseButton] > 0.0 and ImGui.IsMouseClickedEx(g.ActiveIdMouseButton, ImGuiInputFlags.Repeat, test_owner_id) then
                    pressed = true
                end
            end
        end

        if pressed and g.IO.ConfigNavCursorVisibleAuto then
            g.NavCursorVisible = false
        end
    end

    -- Keyboard/Gamepad navigation handling
    -- We report navigated and navigation-activated items as hovered but we don't set g.HoveredId to not interfere with mouse.
    if bit32.band(item_flags, ImGuiItemFlags.Disabled) == 0 then
        if g.NavId == id and g.NavCursorVisible and g.NavHighlightItemUnderNav then
            if bit32.band(flags, ImGuiButtonFlags.NoHoveredOnFocus) == 0 then
                hovered = true
            end
        end
        if g.NavActivateDownId == id then
            local nav_activated_by_code = (g.NavActivateId == id)
            local nav_activated_by_inputs = (g.NavActivatePressedId == id)
            if not nav_activated_by_inputs and bit32.band(item_flags, ImGuiItemFlags.ButtonRepeat) ~= 0 then
                -- Avoid pressing multiple keys from triggering excessive amount of repeat events
                local key1 = ImGui.GetKeyData(g, ImGuiKey.Space)
                local key2 = ImGui.GetKeyData(g, ImGuiKey.Enter)
                local key3 = ImGui.GetKeyData(g, ImGuiKey.NavGamepadActivate)
                local t1 = ImMax(ImMax(key1.DownDuration, key2.DownDuration), key3.DownDuration)
                nav_activated_by_inputs = ImGui.CalcTypematicRepeatAmount(t1 - g.IO.DeltaTime, t1, g.IO.KeyRepeatDelay, g.IO.KeyRepeatRate) > 0
            end
            if nav_activated_by_code or nav_activated_by_inputs then
                -- Set active id so it can be queried by user via IsItemActive(), equivalent of holding the mouse button.
                pressed = true
                ImGui.SetActiveID(id, window)
                g.ActiveIdSource = g.NavInputSource
                if bit32.band(flags, ImGuiButtonFlags.NoNavFocus) == 0 and bit32.band(g.NavActivateFlags, ImGuiActivateFlags.FromShortcut) == 0 then
                    ImGui.SetFocusID(id, window)
                end
                if bit32.band(g.NavActivateFlags, ImGuiActivateFlags.FromShortcut) ~= 0 then
                    g.ActiveIdFromShortcut = true
                end
            end
        end
    end

    -- Process while held
    local held = false
    if g.ActiveId == id then
        if g.ActiveIdSource == ImGuiInputSource.Mouse then
            if g.ActiveIdIsJustActivated then
                g.ActiveIdClickOffset = g.IO.MousePos - bb.Min
            end

            local mouse_button = g.ActiveIdMouseButton
            if mouse_button == -1 then
                -- Fallback for the rare situation were g.ActiveId was set programmatically or from another widget (e.g. #6304).
                ImGui.ClearActiveID()
            elseif ImGui.IsMouseDown(mouse_button, test_owner_id) then
                held = true
            else
                local release_in = hovered and (bit32.band(flags, ImGuiButtonFlags.PressedOnClickRelease) ~= 0)
                local release_anywhere = (bit32.band(flags, ImGuiButtonFlags.PressedOnClickReleaseAnywhere) ~= 0)

                if (release_in or release_anywhere) and not g.DragDropActive then
                    -- Report as pressed when releasing the mouse (this is the most common path)
                    local is_double_click_release = (bit32.band(flags, ImGuiButtonFlags.PressedOnDoubleClick) ~= 0) and g.IO.MouseReleased[mouse_button] and g.IO.MouseClickedLastCount[mouse_button] == 2

                    local is_repeating_already = (bit32.band(item_flags, ImGuiItemFlags.ButtonRepeat) ~= 0) and g.IO.MouseDownDurationPrev[mouse_button] >= g.IO.KeyRepeatDelay -- Repeat mode trumps <on release>

                    local is_button_avail_or_owned = ImGui.TestKeyOwner(ImGui.MouseButtonToKey(mouse_button), test_owner_id)

                    if not is_double_click_release and not is_repeating_already and is_button_avail_or_owned then
                        pressed = true
                    end
                end

                ImGui.ClearActiveID()
            end

            if bit32.band(flags, ImGuiButtonFlags.NoNavFocus) == 0 and g.IO.ConfigNavCursorVisibleAuto then
                g.NavCursorVisible = false
            end
        elseif g.ActiveIdSource == ImGuiInputSource.Keyboard or g.ActiveIdSource == ImGuiInputSource.Gamepad then
            -- When activated using Nav, we hold on the ActiveID until activation button is released
            if g.NavActivateDownId == id then
                held = true -- hovered == true not true as we are already likely hovered on direct activation.
            else
                ImGui.ClearActiveID()
            end
        end

        if pressed then
            g.ActiveIdHasBeenPressedBefore = true
        end
    end

    -- Activation highlight (this may be a remote activation)
    if g.NavHighlightActivatedId == id and (bit32.band(item_flags, ImGuiItemFlags.Disabled) == 0) then
        hovered = true
    end

    return pressed, hovered, held
end

--- @param label     string
--- @param size_arg? ImVec2
--- @param flags?    ImGuiButtonFlags
--- @return bool

function ImGui.ButtonEx(label, size_arg, flags)
    if size_arg == nil then size_arg = ImVec2(0, 0) end
    if flags    == nil then flags    = 0            end

    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return false
    end

    local g = GImGui
    local style = g.Style
    local id = window:GetID(label)
    local label_end = ImGui.FindRenderedTextEnd(label)
    local label_size = ImGui.CalcTextSize(label, label_end, false)

    local pos = ImVec2() -- Don't modify the cursor!
    ImVec2_Copy(pos, window.DC.CursorPos)
    if bit32.band(flags, ImGuiButtonFlags.AlignTextBaseLine) ~= 0 and style.FramePadding.y < window.DC.CurrLineTextBaseOffset then -- Try to vertically align buttons that are smaller/have no padding so that text baseline matches (bit hacky, since it shouldn't be a flag)
        pos.y = pos.y + window.DC.CurrLineTextBaseOffset - style.FramePadding.y
    end
    local size = ImGui.CalcItemSize(size_arg, label_size.x + style.FramePadding.x * 2.0, label_size.y + style.FramePadding.y * 2.0)

    local bb = ImRect(pos, pos + size)
    ImGui.ItemSize(size, style.FramePadding.y)
    if not ImGui.ItemAdd(bb, id) then
        return false
    end

    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id, flags)

    -- Render
    local col
    if held and hovered then
        col = ImGui.GetColorU32(ImGuiCol.ButtonActive)
    elseif hovered then
        col = ImGui.GetColorU32(ImGuiCol.ButtonHovered)
    else
        col = ImGui.GetColorU32(ImGuiCol.Button)
    end

    ImGui.RenderNavCursor(bb, id)
    ImGui.RenderFrame(bb.Min, bb.Max, col, true, style.FrameRounding)

    -- if (g.LogEnabled)
    --     LogSetNextTextDecoration("[", "]");
    ImGui.RenderTextClipped(bb.Min + style.FramePadding, bb.Max - style.FramePadding, label, label_end, label_size, style.ButtonTextAlign, bb)

    -- Automatically close popups
    --if (pressed && !(flags & ImGuiButtonFlags.DontClosePopups) && (window->Flags & ImGuiWindowFlags.Popup))
    --    CloseCurrentPopup();

    -- IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags);
    return pressed
end

--- @param label     string
--- @param size_arg? ImVec2
--- @return bool
function ImGui.Button(label, size_arg)
    return ImGui.ButtonEx(label, size_arg, ImGuiButtonFlags.None)
end

-- Small buttons fits within text without additional vertical spacing.
--- @param label string
--- @return bool
function ImGui.SmallButton(label)
    local g = GImGui
    local backup_padding_y = g.Style.FramePadding.y
    g.Style.FramePadding.y = 0.0
    local pressed = ImGui.ButtonEx(label, ImVec2(0, 0), ImGuiButtonFlags.AlignTextBaseLine)
    g.Style.FramePadding.y = backup_padding_y
    return pressed
end

-- Tip: use ImGui.PushID()/PopID() to push indices or pointers in the ID stack.
-- Then you can keep 'str_id' empty or the same for all your buttons (instead of creating a string based on a non-string id)
--- @param str_id   string
--- @param size_arg ImVec2
--- @param flags?   ImGuiButtonFlags
function ImGui.InvisibleButton(str_id, size_arg, flags)
    if flags == nil then flags = 0 end

    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return false
    end

    -- Ensure zero-size fits to contents
    local size = ImGui.CalcItemSize(ImVec2(size_arg.x ~= 0.0 and size_arg.x or -FLT_MIN, size_arg.y ~= 0.0 and size_arg.y or -FLT_MIN), 0.0, 0.0)

    local id = window:GetID(str_id)
    local bb = ImRect(window.DC.CursorPos, window.DC.CursorPos + size)
    ImGui.ItemSize(size)

    local item_flags = (bit32.band(flags, ImGuiButtonFlags.EnableNav) ~= 0) and ImGuiItemFlags.None or ImGuiItemFlags.NoNav
    if not ImGui.ItemAdd(bb, id, nil, item_flags) then
        return false
    end

    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id, flags)
    ImGui.RenderNavCursor(bb, id)

    -- IMGUI_TEST_ENGINE_ITEM_INFO(id, str_id, g.LastItemData.StatusFlags)
    return pressed
end

--- @param str_id string
--- @param dir    ImGuiDir
--- @param size   ImVec2
--- @param flags? ImGuiButtonFlags
function ImGui.ArrowButtonEx(str_id, dir, size, flags)
    if flags == nil then flags = 0 end

    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return false
    end

    local g = GImGui
    local id = window:GetID(str_id)
    local bb = ImRect(window.DC.CursorPos, window.DC.CursorPos + size)
    local default_size = ImGui.GetFrameHeight()
    ImGui.ItemSize(size, (size.y >= default_size) and g.Style.FramePadding.y or -1.0)
    if not ImGui.ItemAdd(bb, id) then
        return false
    end

    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id, flags)

    -- Render
    local bg_col = ImGui.GetColorU32((held and hovered) and ImGuiCol.ButtonActive or hovered and ImGuiCol.ButtonHovered or ImGuiCol.Button)
    local text_col = ImGui.GetColorU32(ImGuiCol.Text)
    ImGui.RenderNavCursor(bb, id)
    ImGui.RenderFrame(bb.Min, bb.Max, bg_col, true, g.Style.FrameRounding)
    ImGui.RenderArrow(window.DrawList, bb.Min + ImVec2(ImMax(0.0, (size.x - g.FontSize) * 0.5), ImMax(0.0, (size.y - g.FontSize) * 0.5)), text_col, dir)

    -- IMGUI_TEST_ENGINE_ITEM_INFO(id, str_id, g.LastItemData.StatusFlags)
    return pressed
end

--- @param str_id string
--- @param dir    ImGuiDir
function ImGui.ArrowButton(str_id, dir)
    local sz = ImGui.GetFrameHeight()
    return ImGui.ArrowButtonEx(str_id, dir, ImVec2(sz, sz), ImGuiButtonFlags.None)
end

-- Button to close a window
--- @param id  ImGuiID
--- @param pos ImVec2
--- @return bool
function ImGui.CloseButton(id, pos)
    local g = GImGui

    local window = g.CurrentWindow

    -- Tweak 1: Shrink hit-testing area if button covers an abnormally large proportion of the visible region. That's in order to facilitate moving the window away. (#3825)
    -- This may better be applied as a general hit-rect reduction mechanism for all widgets to ensure the area to move window is always accessible?
    local bb = ImRect(pos, pos + ImVec2(g.FontSize, g.FontSize))
    local bb_interact = ImRect()
    ImRect_Copy(bb_interact, bb)

    local area_to_visible_ratio = window.OuterRectClipped:GetArea() / bb:GetArea()
    if area_to_visible_ratio < 1.5 then
        bb_interact:Expand(ImTrunc(bb_interact:GetSize() * -0.25))
    end

    -- Tweak 2: We intentionally allow interaction when clipped so that a mechanical Alt,Right,Activate sequence can always close a window.
    -- (this isn't the common behavior of buttons, but it doesn't affect the user because navigation tends to keep items visible in scrolling layer).
    local is_clipped = not ImGui.ItemAdd(bb_interact, id)

    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id)
    if is_clipped then
        return pressed
    end

    -- Render
    local bg_col
    if held then
        bg_col = ImGui.GetColorU32(ImGuiCol.ButtonActive)
    else
        bg_col = ImGui.GetColorU32(ImGuiCol.ButtonHovered)
    end

    if hovered then
        window.DrawList:AddRectFilled(bb.Min, bb.Max, bg_col)
    end

    local cross_center = bb:GetCenter() - ImVec2(0.5, 0.5)
    local cross_extent = g.FontSize * 0.5 * 0.7071 - 1
    local cross_col = ImGui.GetColorU32(ImGuiCol.Text)
    local cross_thickness = 1.0 -- FIXME-DPI
    window.DrawList:AddLine(cross_center + ImVec2(cross_extent, cross_extent), cross_center + ImVec2(-cross_extent, -cross_extent), cross_col, cross_thickness)
    window.DrawList:AddLine(cross_center + ImVec2(cross_extent, -cross_extent), cross_center + ImVec2(-cross_extent, cross_extent), cross_col, cross_thickness)

    return pressed
end

--- @return bool
function ImGui.CollapseButton(id, pos)
    local g = GImGui

    local window = g.CurrentWindow

    local bb = ImRect(pos, pos + ImVec2(g.FontSize, g.FontSize))

    local is_clipped = not ImGui.ItemAdd(bb, id)

    local pressed, hovered = ImGui.ButtonBehavior(bb, id)

    -- Render
    if hovered then
        window.DrawList:AddRectFilled(bb.Min, bb.Max, ImGui.GetColorU32(ImGuiCol.ButtonHovered))
    end

    if window.Collapsed then
        ImGui.RenderArrow(window.DrawList, bb.Min, ImGui.GetColorU32(ImGuiCol.Text), ImGuiDir.Right, 1)
    else
        ImGui.RenderArrow(window.DrawList, bb.Min, ImGui.GetColorU32(ImGuiCol.Text), ImGuiDir.Down, 1)
    end

    return pressed
end

--- @param window ImGuiWindow
--- @param axis   ImGuiAxis
--- @return ImGuiID
function ImGui.GetWindowScrollbarID(window, axis)
    if axis == ImGuiAxis.X then
        return window:GetID("#SCROLLX")
    else
        return window:GetID("#SCROLLY")
    end
end

-- Return scrollbar rectangle, must only be called for corresponding axis if window.ScrollbarX/Y is set.
--- @param window ImGuiWindow
--- @param axis   ImGuiAxis
--- @return ImRect
--- @nodiscard
function ImGui.GetWindowScrollbarRect(window, axis)
    local g = GImGui
    local outer_rect = window:Rect()
    local inner_rect = window.InnerRect

    -- (ScrollbarSizes.x = width of Y scrollbar; ScrollbarSizes.y = height of X scrollbar)
    local scrollbar_size = window.ScrollbarSizes[axis == ImGuiAxis.X and ImGuiAxis.Y or ImGuiAxis.X]
    IM_ASSERT(scrollbar_size >= 0.0)

    local border_size = IM_ROUND(window.WindowBorderSize * 0.5)
    local border_top = (bit32.band(window.Flags, ImGuiWindowFlags.MenuBar) ~= 0) and IM_ROUND(g.Style.FrameBorderSize * 0.5) or (bit32.band(window.Flags, ImGuiWindowFlags.NoTitleBar) ~= 0 and border_size or 0)

    if axis == ImGuiAxis.X then
        return ImRect(inner_rect.Min.x + border_size, ImMax(outer_rect.Min.y + border_size, outer_rect.Max.y - border_size - scrollbar_size), inner_rect.Max.x - border_size, outer_rect.Max.y - border_size)
    else
        return ImRect(ImMax(outer_rect.Min.x, outer_rect.Max.x - border_size - scrollbar_size), inner_rect.Min.y + border_top, outer_rect.Max.x - border_size, inner_rect.Max.y - border_size)
    end
end

--- @param window    ImGuiWindow
--- @param bb        ImRect
--- @param threshold float
--- @param axis      ImGuiAxis
function ImGui.ExtendHitBoxWhenNearViewportEdge(window, bb, threshold, axis)
    local window_rect = window.RootWindow:Rect()
    local viewport_rect = window.Viewport:GetMainRect()

    if window_rect.Min[axis] == viewport_rect.Min[axis] and bb.Min[axis] > window_rect.Min[axis] and bb.Min[axis] - threshold <= window_rect.Min[axis] then
        bb.Min[axis] = window_rect.Min[axis]
    end

    if window_rect.Max[axis] == viewport_rect.Max[axis] and bb.Max[axis] < window_rect.Max[axis] and bb.Max[axis] + threshold >= window_rect.Max[axis] then
        bb.Max[axis] = window_rect.Max[axis]
    end
end

-- Vertical/Horizontal scrollbar
-- The entire piece of code below is rather confusing because:
-- - We handle absolute seeking (when first clicking outside the grab) and relative manipulation (afterward or when clicking inside the grab)
-- - We store values as normalized ratio and in a form that allows the window content to change while we are holding on a scrollbar
-- - We handle both horizontal and vertical scrollbars, which makes the terminology not ideal.
-- Still, the code should probably be made simpler..
--- @param bb_frame            ImRect
--- @param id                  ImGuiID
--- @param axis                ImGuiAxis
--- @param p_scroll_v          number
--- @param size_visible_v      number
--- @param size_contents_v     number
--- @param draw_rounding_flags ImDrawFlags
--- @return bool   is_held
--- @return number scroll_v # Updated p_scroll_v
function ImGui.ScrollbarEx(bb_frame, id, axis, p_scroll_v, size_visible_v, size_contents_v, draw_rounding_flags)
    local g = GImGui
    local window = g.CurrentWindow
    if window.SkipItems then
        return false, p_scroll_v
    end

    local bb_frame_width = bb_frame:GetWidth()
    local bb_frame_height = bb_frame:GetHeight()
    if bb_frame_width <= 0.0 or bb_frame_height <= 0.0 then
        return false, p_scroll_v
    end

    -- When we are too small, start hiding and disabling the grab (this reduce visual noise on very small window and facilitate using the window resize grab)
    local alpha = 1.0
    if axis == ImGuiAxis.Y and bb_frame_height < bb_frame_width then
        alpha = ImSaturate(bb_frame_height / ImMax(bb_frame_width * 2.0, 1.0))
    end
    if alpha <= 0.0 then
        return false, p_scroll_v
    end

    local style = g.Style
    local allow_interaction = (alpha >= 1.0)

    local bb = ImRect()
    ImRect_Copy(bb, bb_frame)

    local padding = IM_TRUNC(ImMin(style.ScrollbarPadding, ImMin(bb_frame_width, bb_frame_height) * 0.5))
    bb:Expand(-padding)

    -- V denote the main, longer axis of the scrollbar (= height for a vertical scrollbar)
    local scrollbar_size_v
    if axis == ImGuiAxis.X then
        scrollbar_size_v = bb:GetWidth()
    else
        scrollbar_size_v = bb:GetHeight()
    end

    if scrollbar_size_v < 1.0 then
        return false, p_scroll_v
    end

    -- Calculate the height of our grabbable box. It generally represent the amount visible (vs the total scrollable amount)
    -- But we maintain a minimum size in pixel to allow for the user to still aim inside.
    IM_ASSERT(ImMax(size_contents_v, size_visible_v) > 0.0) -- Adding this assert to check if the ImMax(XXX,1.0f) is still needed. PLEASE CONTACT ME if this triggers.
    local win_size_v = ImMax(ImMax(size_contents_v, size_visible_v), 1)
    local grab_h_minsize = ImMin(bb:GetSize()[axis], style.GrabMinSize)
    local grab_h_pixels = ImTrunc(ImClamp(scrollbar_size_v * (size_visible_v / win_size_v), grab_h_minsize, scrollbar_size_v))
    local grab_h_norm = grab_h_pixels / scrollbar_size_v

    -- As a special thing, we allow scrollbar near the edge of a screen/viewport to be reachable with mouse at the extreme edge (#9276)
    local bb_hit = ImRect()
    ImRect_Copy(bb_hit, bb_frame)
    ImGui.ExtendHitBoxWhenNearViewportEdge(window, bb_hit, g.Style.WindowBorderSize, ImGuiAxis.X + ImGuiAxis.Y - axis) -- swap axis here

    -- Handle input right away. None of the code of Begin() is relying on scrolling position before calling Scrollbar().
    ImGui.ItemAdd(bb_frame, id, nil, ImGuiItemFlags.NoNav)
    local pressed, hovered, held = ImGui.ButtonBehavior(bb_hit, id, ImGuiButtonFlags.NoNavFocus)

    local scroll_max = ImMax(1, size_contents_v - size_visible_v)
    local scroll_ratio = ImSaturate(p_scroll_v / scroll_max)
    local grab_v_norm = scroll_ratio * (scrollbar_size_v - grab_h_pixels) / scrollbar_size_v -- Grab position in normalized space
    if held and allow_interaction and grab_h_norm < 1.0 then
        local scrollbar_pos_v = bb.Min[axis]
        local mouse_pos_v = g.IO.MousePos[axis]

        -- Click position in scrollbar normalized space (0.0f->1.0f)
        local clicked_v_norm = ImSaturate((mouse_pos_v - scrollbar_pos_v) / scrollbar_size_v)

        local held_dir
        if clicked_v_norm < grab_v_norm then
            held_dir = -1
        elseif clicked_v_norm > grab_v_norm + grab_h_norm then
            held_dir = 1
        else
            held_dir = 0
        end
        if g.ActiveIdIsJustActivated then
            -- On initial click when held_dir == 0 (clicked over grab): calculate the distance between mouse and the center of the grab
            local scroll_to_clicked_location = (g.IO.ConfigScrollbarScrollByPage == false) or g.IO.KeyShift or held_dir == 0

            if scroll_to_clicked_location then
                g.ScrollbarSeekMode = 0
            else
                g.ScrollbarSeekMode = held_dir
            end

            if held_dir == 0 and not g.IO.KeyShift then
                g.ScrollbarClickDeltaToGrabCenter = clicked_v_norm - grab_v_norm - grab_h_norm * 0.5
            else
                g.ScrollbarClickDeltaToGrabCenter = 0.0
            end
        end

        -- Apply scroll (p_scroll_v will generally point on one member of window.Scroll)
        -- It is ok to modify Scroll here because we are being called in Begin() after the calculation of ContentSize and before setting up our starting position
        if g.ScrollbarSeekMode == 0 then
            -- Absolute seeking
            scroll_v_norm = ImSaturate((clicked_v_norm - g.ScrollbarClickDeltaToGrabCenter - grab_h_norm * 0.5) / (1.0 - grab_h_norm))
            p_scroll_v = scroll_v_norm * scroll_max
        else
            -- Page by page
            if ImGui.IsMouseClickedEx(ImGuiMouseButton.Left, ImGuiInputFlags.Repeat) and held_dir == g.ScrollbarSeekMode then
                local page_dir
                if g.ScrollbarSeekMode > 0.0 then
                    page_dir = 1.0
                else
                    page_dir = -1.0
                end
                p_scroll_v = ImClamp(p_scroll_v + page_dir * size_visible_v, 0, scroll_max)
            end
        end

        -- Update values for rendering
        scroll_ratio = ImSaturate(p_scroll_v / scroll_max)
        grab_v_norm = scroll_ratio * (scrollbar_size_v - grab_h_pixels) / scrollbar_size_v

        -- Update distance to grab now that we have seek'ed and saturated
        --if (seek_absolute)
        --    g.ScrollbarClickDeltaToGrabCenter = clicked_v_norm - grab_v_norm - grab_h_norm * 0.5f;
    end

    -- Render
    local bg_col = ImGui.GetColorU32(ImGuiCol.ScrollbarBg)
    local grab_col
    if held then
        grab_col = ImGui.GetColorU32(ImGuiCol.ScrollbarGrabActive, alpha)
    elseif hovered then
        grab_col = ImGui.GetColorU32(ImGuiCol.ScrollbarGrabHovered, alpha)
    else
        grab_col = ImGui.GetColorU32(ImGuiCol.ScrollbarGrab, alpha)
    end
    window.DrawList:AddRectFilled(bb_frame.Min, bb_frame.Max, bg_col, window.WindowRounding, draw_rounding_flags)
    local grab_rect
    if axis == ImGuiAxis.X then
        local x1 = ImLerp(bb.Min.x, bb.Max.x, grab_v_norm)
        grab_rect = ImRect(x1, bb.Min.y, x1 + grab_h_pixels, bb.Max.y)
    else
        local y1 = ImLerp(bb.Min.y, bb.Max.y, grab_v_norm)
        grab_rect = ImRect(bb.Min.x, y1, bb.Max.x, y1 + grab_h_pixels)
    end

    window.DrawList:AddRectFilled(grab_rect.Min, grab_rect.Max, grab_col, style.ScrollbarRounding)

    return held, p_scroll_v
end

--- @param axis ImGuiAxis
function ImGui.Scrollbar(axis)
    local g = GImGui
    local window = g.CurrentWindow
    local id = ImGui.GetWindowScrollbarID(window, axis)

    -- Calculate scrollbar bounding box
    local bb = ImGui.GetWindowScrollbarRect(window, axis)
    local rounding_corners = ImGui.CalcRoundingFlagsForRectInRect(bb, window:Rect(), g.Style.WindowBorderSize)
    local size_visible = window.InnerRect.Max[axis] - window.InnerRect.Min[axis]
    local size_contents = window.ContentSize[axis] + window.WindowPadding[axis] * 2.0
    local scroll = window.Scroll[axis]
    local held
    held, scroll = ImGui.ScrollbarEx(bb, id, axis, scroll, size_visible, size_contents, rounding_corners)
    window.Scroll[axis] = scroll
end

-- - Read about ImTextureID/ImTextureRef here: https://github.com/ocornut/imgui/wiki/Image-Loading-and-Displaying-Examples
-- - 'uv0' and 'uv1' are texture coordinates. Read about them from the same link above.
--- @param tex_ref    ImTextureRef
--- @param image_size ImVec2
--- @param uv0?       ImVec2
--- @param uv1?       ImVec2
--- @param bg_col?    ImVec4
--- @param tint_col?  ImVec4
function ImGui.ImageWithBg(tex_ref, image_size, uv0, uv1, bg_col, tint_col)
    if uv0      == nil then uv0      = ImVec2(0, 0)       end
    if uv1      == nil then uv1      = ImVec2(1, 1)       end
    if bg_col   == nil then bg_col   = ImVec4(0, 0, 0, 0) end
    if tint_col == nil then tint_col = ImVec4(1, 1, 1, 1) end

    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    local padding = ImVec2(g.Style.ImageBorderSize, g.Style.ImageBorderSize)
    local bb = ImRect(window.DC.CursorPos, window.DC.CursorPos + image_size + padding * 2.0)
    ImGui.ItemSize(bb)
    if not ImGui.ItemAdd(bb, 0) then
        return
    end

    -- Render
    local rounding = g.Style.ImageRounding
    if bg_col.w > 0.0 then
        window.DrawList:AddRectFilled(bb.Min + padding, bb.Max - padding, ImGui.GetColorU32(bg_col), rounding)
    end
    if rounding > 0.0 then
        window.DrawList:AddImageRounded(tex_ref, bb.Min + padding, bb.Max - padding, uv0, uv1, ImGui.GetColorU32(tint_col), rounding)
    else
        window.DrawList:AddImage(tex_ref, bb.Min + padding, bb.Max - padding, uv0, uv1, ImGui.GetColorU32(tint_col))
    end
    if g.Style.ImageBorderSize > 0.0 then
        window.DrawList:AddRect(bb.Min, bb.Max, ImGui.GetColorU32(ImGuiCol.Border), rounding, g.Style.ImageBorderSize, ImDrawFlags.None)
    end
end

--- @param tex_ref    ImTextureRef
--- @param image_size ImVec2
--- @param uv0?       ImVec2
--- @param uv1?       ImVec2
function ImGui.Image(tex_ref, image_size, uv0, uv1)
    ImGui.ImageWithBg(tex_ref, image_size, uv0, uv1)
end

--- @param id         ImGuiID
--- @param tex_ref    ImTextureRef
--- @param image_size ImVec2
--- @param uv0        ImVec2
--- @param uv1        ImVec2
--- @param bg_col     ImVec4
--- @param tint_col   ImVec4
--- @param flags?     ImGuiButtonFlags
function ImGui.ImageButtonEx(id, tex_ref, image_size, uv0, uv1, bg_col, tint_col, flags)
    if flags == nil then flags = 0 end

    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return false
    end

    local g = GImGui
    local padding = g.Style.FramePadding
    local bb = ImRect(window.DC.CursorPos, window.DC.CursorPos + image_size + padding * 2.0)
    ImGui.ItemSize(bb)
    if not ImGui.ItemAdd(bb, id) then
        return false
    end

    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id, flags)

    -- Render
    local col = ImGui.GetColorU32((held and hovered) and ImGuiCol.ButtonActive or hovered and ImGuiCol.ButtonHovered or ImGuiCol.Button)
    ImGui.RenderNavCursor(bb, id)
    ImGui.RenderFrame(bb.Min, bb.Max, col, true, g.Style.FrameRounding)
    if bg_col.w > 0.0 then
        window.DrawList:AddRectFilled(bb.Min + padding, bb.Max - padding, ImGui.GetColorU32(bg_col))
    end
    local image_rounding = ImMax(g.Style.FrameRounding - ImMax(padding.x, padding.y), g.Style.ImageRounding)
    if image_rounding > 0.0 then
        window.DrawList:AddImageRounded(tex_ref, bb.Min + padding, bb.Max - padding, uv0, uv1, ImGui.GetColorU32(tint_col), image_rounding)
    else
        window.DrawList:AddImage(tex_ref, bb.Min + padding, bb.Max - padding, uv0, uv1, ImGui.GetColorU32(tint_col))
    end

    return pressed
end

-- - ImageButton() adds style.FramePadding*2.0f to provided size. This is in order to facilitate fitting an image in a button.
-- - ImageButton() draws a background based on regular Button() color + optionally an inner background if specified. (#8165) -- FIXME: Maybe that's not the best design?
--- @param str_id     string
--- @param tex_ref    ImTextureRef
--- @param image_size ImVec2
--- @param uv0        ImVec2
--- @param uv1        ImVec2
--- @param bg_col     ImVec4
--- @param tint_col   ImVec4
function ImGui.ImageButton(str_id, tex_ref, image_size, uv0, uv1, bg_col, tint_col)
    local g = GImGui
    local window = g.CurrentWindow
    if window.SkipItems then
        return false
    end

    return ImGui.ImageButtonEx(window:GetID(str_id), tex_ref, image_size, uv0, uv1, bg_col, tint_col)
end

--- @param label string
--- @param v     bool
--- @return bool is_pressed
--- @return bool is_checked # The updated `v` passed in

function ImGui.Checkbox(label, v)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return false, v
    end

    local g = GImGui
    local style = g.Style
    local id = window:GetID(label)
    local label_end = ImGui.FindRenderedTextEnd(label)
    local label_size = ImGui.CalcTextSize(label, label_end, false)

    local square_sz = ImGui.GetFrameHeight()
    local pos = ImVec2()
    ImVec2_Copy(pos, window.DC.CursorPos)

    local total_width
    if label_size.x > 0.0 then
        total_width = square_sz + style.ItemInnerSpacing.x + label_size.x
    else
        total_width = square_sz
    end
    local total_bb = ImRect(pos, pos + ImVec2(total_width, label_size.y + style.FramePadding.y * 2.0))
    ImGui.ItemSize(total_bb, style.FramePadding.y)
    local is_visible = ImGui.ItemAdd(total_bb, id)
    local is_multi_select = (bit32.band(g.LastItemData.ItemFlags, ImGuiItemFlags.IsMultiSelect) ~= 0)
    if not is_visible then
        if not is_multi_select or not g.BoxSelectState.UnclipMode or not g.BoxSelectState.UnclipRect:Overlaps(total_bb) then -- Extra layer of "no logic clip" for box-select support
            -- IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Checkable | (*v ? ImGuiItemStatusFlags_Checked : 0))
            return false, v
        end
    end

    -- Range-Selection/Multi-selection support (header)
    local checked = v
    if is_multi_select then
        -- TODO: MultiSelectItemHeader()
    end

    local pressed, hovered, held = ImGui.ButtonBehavior(total_bb, id)

    -- Range-Selection/Multi-selection support (footer)
    if is_multi_select then
        -- TODO: MultiSelectItemFooter()
    elseif pressed then
        checked = not checked
    end

    if v ~= checked then
        v = checked
        pressed = true -- return value
        ImGui.MarkItemEdited(id)
    end

    local check_bb = ImRect(pos, pos + ImVec2(square_sz, square_sz))
    local mixed_value = (bit32.band(g.LastItemData.ItemFlags, ImGuiItemFlags.MixedValue) ~= 0)
    if is_visible then
        ImGui.RenderNavCursor(total_bb, id)

        local bg_col = ImGui.GetColorU32((held and hovered) and ImGuiCol.FrameBgActive or (hovered and ImGuiCol.FrameBgHovered or ((mixed_value or checked) and ImGuiCol.CheckboxSelectedBg or ImGuiCol.FrameBg)))
        local check_col = ImGui.GetColorU32(ImGuiCol.CheckMark)
        ImGui.RenderFrame(check_bb.Min, check_bb.Max, bg_col, true, style.FrameRounding)

        if mixed_value then
            -- Undocumented tristate/mixed/indeterminate checkbox (#2644)
            -- This may seem awkwardly designed because the aim is to make ImGuiItemFlags.MixedValue supported by all widgets (not just checkbox)
            local pad_val = ImMax(1.0, IM_TRUNC(square_sz / 3.6))
            local pad = ImVec2(pad_val, pad_val)
            window.DrawList:AddRectFilled(check_bb.Min + pad, check_bb.Max - pad, check_col, style.FrameRounding)
        elseif v then
            local pad = ImMax(1.0, IM_TRUNC(square_sz / 6.0))
            ImGui.RenderCheckMark(window.DrawList, check_bb.Min + ImVec2(pad, pad), check_col, square_sz - pad * 2.0)
        end
    end

    local label_pos = ImVec2(check_bb.Max.x + style.ItemInnerSpacing.x, check_bb.Min.y + style.FramePadding.y)
    if g.LogEnabled then
        -- ImGui.LogRenderedText(label_pos, mixed_value and "[~]" or (v and "[x]" or "[ ]"))
    end

    if is_visible and label_size.x > 0.0 then
        ImGui.RenderText(label_pos, label, 1, label_end, false)
    end

    -- IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags | ImGuiItemStatusFlags_Checkable | (*v ? ImGuiItemStatusFlags_Checked : 0))
    return pressed, v
end

--- @param label       string
--- @param flags       int
--- @param flags_value int
--- @return bool is_pressed
--- @return int  flags_new  # Updated `flags`
function ImGui.CheckboxFlags(label, flags, flags_value)
    local all_on = bit32.band(flags, flags_value) == flags_value
    local any_on = bit32.band(flags, flags_value) ~= 0
    local pressed
    if not all_on and any_on then
        local g = GImGui
        g.NextItemData.ItemFlagsSet = bit32.bor(g.NextItemData.ItemFlagsSet, ImGuiItemFlags.MixedValue)
        pressed, all_on = ImGui.Checkbox(label, all_on)
    else
        pressed, all_on = ImGui.Checkbox(label, all_on)
    end
    if pressed then
        if all_on then
            flags = bit32.bor(flags, flags_value)
        else
            flags = bit32.band(flags, bit32.bnot(flags_value))
        end
    end

    return pressed, flags
end
ImGui.CheckboxFlagsT = ImGui.CheckboxFlags

--- @param label  string
--- @param active bool
--- @return bool is_pressed
function ImGui.RadioButtonEx(label, active)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return false
    end

    local g = GImGui
    local style = g.Style
    local id = window:GetID(label)
    local label_end = ImGui.FindRenderedTextEnd(label)
    local label_size = ImGui.CalcTextSize(label, label_end, false)

    local square_sz = ImGui.GetFrameHeight()
    local pos = ImVec2()
    ImVec2_Copy(pos, window.DC.CursorPos)
    local check_bb = ImRect(pos, pos + ImVec2(square_sz, square_sz))
    local total_bb = ImRect(pos, pos + ImVec2(square_sz + (label_size.x > 0.0 and style.ItemInnerSpacing.x + label_size.x or 0.0), label_size.y + style.FramePadding.y * 2.0))
    ImGui.ItemSize(total_bb, style.FramePadding.y)
    if not ImGui.ItemAdd(total_bb, id) then
        return false
    end

    local center = check_bb:GetCenter()
    center.x = IM_ROUND(center.x)
    center.y = IM_ROUND(center.y)
    local radius = (square_sz - 1.0) * 0.5

    local pressed, hovered, held = ImGui.ButtonBehavior(total_bb, id)
    if (pressed) then
        ImGui.MarkItemEdited(id)
    end

    ImGui.RenderNavCursor(total_bb, id)
    local num_segment = window.DrawList:_CalcCircleAutoSegmentCount(radius)
    local col
    if held and hovered then
        col = ImGui.GetColorU32(ImGuiCol.FrameBgActive)
    else
        if hovered then
            col = ImGui.GetColorU32(ImGuiCol.FrameBgHovered)
        else
            col = ImGui.GetColorU32(ImGuiCol.FrameBg)
        end
    end
    window.DrawList:AddCircleFilled(center, radius, col, num_segment)
    if active then
        local pad = ImMax(1.0, IM_TRUNC(square_sz / 6.0))
        window.DrawList:AddCircleFilled(center, radius - pad, ImGui.GetColorU32(ImGuiCol.CheckMark))
    end
    if style.FrameBorderSize > 0.0 then
        window.DrawList:AddCircle(center + ImVec2(1, 1), radius, ImGui.GetColorU32(ImGuiCol.BorderShadow), num_segment, style.FrameBorderSize)
        window.DrawList:AddCircle(center, radius, ImGui.GetColorU32(ImGuiCol.Border), num_segment, style.FrameBorderSize)
    end
    local label_pos = ImVec2(check_bb.Max.x + style.ItemInnerSpacing.x, check_bb.Min.y + style.FramePadding.y)
    if g.LogEnabled then
        -- ImGui.LogRenderedText(label_pos, active and "(x)" or "( )")
    end
    if label_size.x > 0.0 then
        ImGui.RenderText(label_pos, label, 1, label_end, false)
    end

    return pressed
end

-- `rawequal` is used here to check if v == v_button
--- @param label    string
--- @param v        any
--- @param v_button any
--- @return bool is_pressed
--- @return any  v          # Updated v
function ImGui.RadioButton(label, v, v_button)
    local pressed = ImGui.RadioButtonEx(label, rawequal(v, v_button))
    if pressed then
        v = v_button
    end
    return pressed, v
end

-- size_arg (for each axis) < 0.0f: align to end, 0.0f: auto, > 0.0f: specified size
--- @param fraction  float
--- @param size_arg? ImVec2
--- @param overlay?  string
function ImGui.ProgressBar(fraction, size_arg, overlay)
    if size_arg == nil then size_arg = ImVec2(-FLT_MIN, 0) end

    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    local style = g.Style

    local pos = ImVec2()
    ImVec2_Copy(pos, window.DC.CursorPos)
    local size = ImGui.CalcItemSize(size_arg, ImGui.CalcItemWidth(), g.FontSize + style.FramePadding.y * 2.0)
    local bb = ImRect(pos, pos + size)
    ImGui.ItemSize(size, style.FramePadding.y)
    if not ImGui.ItemAdd(bb, 0) then
        return
    end

    -- Fraction < 0.0f will display an indeterminate progress bar animation
    -- The value must be animated along with time, so e.g. passing '-1.0f * ImGui.GetTime()' as fraction works.
    local is_indeterminate = (fraction < 0.0)
    if not is_indeterminate then
        fraction = ImSaturate(fraction)
    end

    -- Out of courtesy we accept a NaN fraction without crashing
    local fill_n0 = 0.0
    local fill_n1 = (fraction == fraction) and fraction or 0.0

    if is_indeterminate then
        local fill_width_n = 0.2
        fill_n0 = ImFmod(-fraction, 1.0) * (1.0 + fill_width_n) - fill_width_n
        fill_n1 = ImSaturate(fill_n0 + fill_width_n)
        fill_n0 = ImSaturate(fill_n0)
    end

    -- Render
    ImGui.RenderFrame(bb.Min, bb.Max, ImGui.GetColorU32(ImGuiCol.FrameBg), true, style.FrameRounding)
    bb:Expand(ImVec2(-style.FrameBorderSize, -style.FrameBorderSize))

    local fill_x0 = ImLerp(bb.Min.x, bb.Max.x, fill_n0)
    local fill_x1 = ImLerp(bb.Min.x, bb.Max.x, fill_n1)
    if fill_x0 < fill_x1 then
        ImGui.RenderRectFilledInRangeH(window.DrawList, bb, ImGui.GetColorU32(ImGuiCol.PlotHistogram), fill_x0, fill_x1, style.FrameRounding)
    end

    -- Default displaying the fraction as percentage string, but user can override it
    -- Don't display text for indeterminate bars by default
    if not is_indeterminate or overlay ~= nil then
        if overlay == nil then
            overlay = ImFormatString("%.0f%%", fraction * 100 + 0.01)
        end

        local overlay_size = ImGui.CalcTextSize(overlay, nil)
        if overlay_size.x > 0.0 then
            local text_x = is_indeterminate and ((bb.Min.x + bb.Max.x - overlay_size.x) * 0.5) or (fill_x1 + style.ItemSpacing.x)
            ImGui.RenderTextClipped(ImVec2(ImClamp(text_x, bb.Min.x, bb.Max.x - overlay_size.x - style.ItemInnerSpacing.x), bb.Min.y), bb.Max, overlay, nil, overlay_size, ImVec2(0.0, 0.5), bb)
        end
    end
end

function ImGui.Bullet()
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    local style = g.Style
    local line_height = ImMax(ImMin(window.DC.CurrLineSize.y, g.FontSize + style.FramePadding.y * 2), g.FontSize)
    local bb = ImRect(window.DC.CursorPos, window.DC.CursorPos + ImVec2(g.FontSize, line_height))
    ImGui.ItemSize(bb)
    if not ImGui.ItemAdd(bb, 0) then
        ImGui.SameLine(0, style.FramePadding.x * 2)
        return
    end

    -- Render and stay on same line
    local text_col = ImGui.GetColorU32(ImGuiCol.Text)
    ImGui.RenderBullet(window.DrawList, bb.Min + ImVec2(style.FramePadding.x + g.FontSize * 0.5, line_height * 0.5), text_col)
    ImGui.SameLine(0, style.FramePadding.x * 2.0)
end

-- This is provided as a convenience for being an often requested feature.
-- FIXME-STYLE: we delayed adding as there is a larger plan to revamp the styling system.
-- Because of this we currently don't provide many styling options for this widget
-- (e.g. hovered/active colors are automatically inferred from a single color).
--- @param label string
function ImGui.TextLink(label)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return false
    end

    local g = GImGui
    local id = window:GetID(label)
    local label_end = ImGui.FindRenderedTextEnd(label)

    local pos = ImVec2(window.DC.CursorPos.x, window.DC.CursorPos.y + window.DC.CurrLineTextBaseOffset)
    local size = ImGui.CalcTextSize(label, label_end, false)
    local bb = ImRect(pos, pos + size)
    ImGui.ItemSize(size, 0.0)
    if not ImGui.ItemAdd(bb, id) then
        return false
    end

    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id)
    ImGui.RenderNavCursor(bb, id)

    if hovered then
        ImGui.SetMouseCursor(ImGuiMouseCursor.Hand)
    end

    local text_colf = ImVec4()
    ImVec4_Copy(text_colf, g.Style.Colors[ImGuiCol.TextLink])
    local line_colf = ImVec4()
    ImVec4_Copy(line_colf, text_colf)
    do
        -- FIXME-STYLE: Read comments above. This widget is NOT written in the same style as some earlier widgets,
        -- as we are currently experimenting/planning a different styling system.
        local h, s, v = ImGui.ColorConvertRGBtoHSV(text_colf.x, text_colf.y, text_colf.z)
        if held or hovered then
            v = ImSaturate(v + (held and 0.4 or 0.3))
            h = ImFmod(h + 0.02, 1.0)
        end
        text_colf.x, text_colf.y, text_colf.z = ImGui.ColorConvertHSVtoRGB(h, s, v)
        v = ImSaturate(v - 0.20)
        line_colf.x, line_colf.y, line_colf.z = ImGui.ColorConvertHSVtoRGB(h, s, v)
    end

    local line_y = bb.Max.y + ImFloor(g.FontBaked.Descent * g.FontBakedScale * 0.20)
    window.DrawList:AddLineH(bb.Min.x, bb.Max.x, line_y, ImGui.GetColorU32(line_colf), 1.0 * ImTrunc(g.Style._MainScale)) -- FIXME-TEXT: Underline mode -- FIXME-DPI

    ImGui.PushStyleColor(ImGuiCol.Text, ImGui.GetColorU32(text_colf))
    ImGui.RenderText(bb.Min, label, 1, label_end, false)
    ImGui.PopStyleColor()

    -- IMGUI_TEST_ENGINE_ITEM_INFO(id, label, g.LastItemData.StatusFlags)
    return pressed
end

--- @param label string
--- @param url   string
function ImGui.TextLinkOpenURL(label, url)
    local g = GImGui
    if url == nil then
        url = label
    end
    local pressed = ImGui.TextLink(label)
    if pressed and g.PlatformIO.Platform_OpenInShellFn ~= nil then
        g.PlatformIO.Platform_OpenInShellFn(g, url)
    end

    ImGui.SetItemTooltip(ImGui.LocalizeGetMsg(ImGuiLocKey.OpenLink_s), url) -- It is more reassuring for user to _always_ display URL when it is the same as the label.

    if ImGui.BeginPopupContextItem() then
        if ImGui.MenuItem(ImGui.LocalizeGetMsg(ImGuiLocKey.CopyLink)) then
            ImGui.SetClipboardText(url)
        end
        ImGui.EndPopup()
    end

    return pressed
end

-------------------------------------------------------------------------------
-- [SECTION] Widgets: Low-level Layout helpers
-------------------------------------------------------------------------------
-- - Spacing()
-- - Dummy()
-- - NewLine()
-- - AlignTextToFramePadding()
-- - SeparatorEx() [Internal]
-- - Separator()
-------------------------------------------------------------------------------

function ImGui.Spacing()
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end
    ImGui.ItemSize(ImVec2(0, 0))
end

--- @param size ImVec2
function ImGui.Dummy(size)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local bb = ImRect(window.DC.CursorPos, window.DC.CursorPos + size)
    ImGui.ItemSize(size)
    ImGui.ItemAdd(bb, 0)
end

function ImGui.NewLine()
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    local backup_layout_type = window.DC.LayoutType
    window.DC.LayoutType = ImGuiLayoutType.Vertical
    window.DC.IsSameLine = false

    if window.DC.CurrLineSize.y > 0.0 then -- In the event that we are on a line with items that is smaller that FontSize high, we will preserve its height.
        ImGui.ItemSize(ImVec2(0, 0))
    else
        ImGui.ItemSize(ImVec2(0.0, g.FontSize))
    end

    window.DC.LayoutType = backup_layout_type
end

function ImGui.AlignTextToFramePadding()
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    window.DC.CurrLineSize.y = ImMax(window.DC.CurrLineSize.y, g.FontSize + g.Style.FramePadding.y * 2)
    window.DC.CurrLineTextBaseOffset = ImMax(window.DC.CurrLineTextBaseOffset, g.Style.FramePadding.y)
end

-- Horizontal/vertical separating line
-- FIXME: Surprisingly, this seemingly trivial widget is a victim of many different legacy/tricky layout issues.
-- Note how thickness == 1.0f is handled specifically as not moving CursorPos by 'thickness', but other values are.
--- @param flags     ImGuiSeparatorFlags
--- @param thickness float
function ImGui.SeparatorEx(flags, thickness)
    if thickness == nil then thickness = 1.0 end

    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    local g = GImGui
    IM_ASSERT(ImIsPowerOfTwo(bit32.band(flags, bit32.bor(ImGuiSeparatorFlags.Horizontal, ImGuiSeparatorFlags.Vertical)))) -- Check that only 1 option is selected
    IM_ASSERT(thickness > 0.0)

    if bit32.band(flags, ImGuiSeparatorFlags.Vertical) ~= 0 then
        -- Vertical separator, for menu bars (use current line height).
        local y1 = window.DC.CursorPos.y
        local y2 = window.DC.CursorPos.y + window.DC.CurrLineSize.y
        local bb = ImRect(ImVec2(window.DC.CursorPos.x, y1), ImVec2(window.DC.CursorPos.x + thickness, y2))
        ImGui.ItemSize(ImVec2(thickness, 0.0))
        if not ImGui.ItemAdd(bb, 0) then
            return
        end

        -- Draw
        window.DrawList:AddRectFilled(bb.Min, bb.Max, ImGui.GetColorU32(ImGuiCol.Separator))
        if g.LogEnabled then
            ImGui.LogText(" |")
        end
    elseif bit32.band(flags, ImGuiSeparatorFlags.Horizontal) ~= 0 then
        -- Horizontal Separator
        local x1 = window.DC.CursorPos.x
        local x2 = window.WorkRect.Max.x

        -- Preserve legacy behavior inside Columns()
        -- Before Tables API happened, we relied on Separator() to span all columns of a Columns() set.
        -- We currently don't need to provide the same feature for tables because tables naturally have border features.
        local columns = (bit32.band(flags, ImGuiSeparatorFlags.SpanAllColumns) ~= 0) and window.DC.CurrentColumns or nil
        if columns then
            x1 = window.Pos.x + window.DC.Indent.x -- Used to be Pos.x before 2023/10/03
            x2 = window.Pos.x + window.Size.x
            ImGui.PushColumnsBackground()
        end

        -- We don't provide our width to the layout so that it doesn't get feed back into AutoFit
        -- FIXME: This prevents ->CursorMaxPos based bounding box evaluation from working (e.g. TableEndCell)

        -- Between 1.71 and 1.92.7, we maintained a hack where a 1.0f thin Separator() would not impact layout.
        -- This was mostly chosen to allow backward compatibility with user's code assuming zero-height when calculating height for layout (e.g. bottom alignment of a status bar).
        -- In order to handle scaling we need to scale separator thickness and it would not makes sense to have a disparity depending on height.
        ----float thickness_for_layout = (thickness == 1.0f) ? 0.0f : thickness; // FIXME: See 1.70/1.71 Separator() change: makes legacy 1-px separator not affect layout yet. Should change.
        local bb = ImRect(ImVec2(x1, window.DC.CursorPos.y), ImVec2(x2, window.DC.CursorPos.y + thickness))
        ImGui.ItemSize(ImVec2(0.0, thickness))

        if ImGui.ItemAdd(bb, 0) then
            -- Draw
            window.DrawList:AddRectFilled(bb.Min, bb.Max, ImGui.GetColorU32(ImGuiCol.Separator))
            if g.LogEnabled then
                ImGui.LogRenderedText(bb.Min, "--------------------------------")
            end
        end

        if columns then
            ImGui.PopColumnsBackground()
            columns.LineMinY = window.DC.CursorPos.y
        end
    end
end

function ImGui.Separator()
    local g = GImGui
    local window = g.CurrentWindow
    if window.SkipItems then
        return
    end

    -- Those flags should eventually be configurable by the user
    local flags
    if window.DC.LayoutType == ImGuiLayoutType.Horizontal then
        flags = ImGuiSeparatorFlags.Vertical
    else
        flags = ImGuiSeparatorFlags.Horizontal
    end

    -- Only applies to legacy Columns() api as they relied on Separator() a lot.
    if window.DC.CurrentColumns then
        flags = bit32.bor(flags, ImGuiSeparatorFlags.SpanAllColumns)
    end

    ImGui.SeparatorEx(flags, ImMax(g.Style.SeparatorSize, 1.0))
end

--- @param id         ImGuiID
--- @param label      string
--- @param label_end? int
--- @param extra_w    float
function ImGui.SeparatorTextEx(id, label, label_end, extra_w)
    local g = GImGui
    local window = g.CurrentWindow
    local style = g.Style

    local label_size = ImGui.CalcTextSize(label, label_end, false)
    local pos = ImVec2(window.DC.CursorPos.x, window.DC.CursorPos.y)
    local padding = style.SeparatorTextPadding

    local separator_thickness = style.SeparatorTextBorderSize
    local min_size = ImVec2(label_size.x + extra_w + padding.x * 2.0, ImMax(label_size.y + padding.y * 2.0, separator_thickness))

    local bb = ImRect(pos, ImVec2(window.WorkRect.Max.x, pos.y + min_size.y))
    local text_baseline_y = ImTrunc((bb:GetHeight() - label_size.y) * style.SeparatorTextAlign.y + 0.999) --ImMax(padding.y, ImTrunc((style.SeparatorTextSize - label_size.y) * 0.5f))

    ImGui.ItemSize(min_size, text_baseline_y)
    if not ImGui.ItemAdd(bb, id) then
        return
    end

    local sep1_x1 = pos.x
    local sep2_x2 = bb.Max.x
    local seps_y = ImTrunc((bb.Min.y + bb.Max.y) * 0.5 + 0.999)

    local label_avail_w = ImMax(0.0, sep2_x2 - sep1_x1 - padding.x * 2.0)
    local label_pos = ImVec2(pos.x + padding.x + ImMax(0.0, (label_avail_w - label_size.x - extra_w) * style.SeparatorTextAlign.x), pos.y + text_baseline_y) -- FIXME-ALIGN

    -- This allows using SameLine() to position something in the 'extra_w'
    window.DC.CursorPosPrevLine.x = label_pos.x + label_size.x

    local separator_col = ImGui.GetColorU32(ImGuiCol.Separator)

    if label_size.x > 0.0 then
        local sep1_x2 = label_pos.x - style.ItemSpacing.x
        local sep2_x1 = label_pos.x + label_size.x + extra_w + style.ItemSpacing.x

        if sep1_x2 > sep1_x1 and separator_thickness > 0.0 then
            window.DrawList:AddLineH(sep1_x1, sep1_x2, seps_y, separator_col, separator_thickness)
        end

        if sep2_x2 > sep2_x1 and separator_thickness > 0.0 then
            window.DrawList:AddLineH(sep2_x1, sep2_x2, seps_y, separator_col, separator_thickness)
        end

        if g.LogEnabled then
            ImGui.LogSetNextTextDecoration("---", nil)
        end

        ImGui.RenderTextEllipsis(window.DrawList, label_pos, ImVec2(bb.Max.x, bb.Max.y + style.ItemSpacing.y), bb.Max.x, label, label_end, label_size)
    else
        if g.LogEnabled then
            ImGui.LogText("---")
        end

        if separator_thickness > 0.0 then
            window.DrawList:AddLineH(sep1_x1, sep2_x2, seps_y, separator_col, separator_thickness)
        end
    end
end

--- @param label string
function ImGui.SeparatorText(label)
    local window = ImGui.GetCurrentWindow()
    if window.SkipItems then
        return
    end

    -- The SeparatorText() vs SeparatorTextEx() distinction is designed to be considerate that we may want:
    -- - allow separator-text to be draggable items (would require a stable ID + a noticeable highlight)
    -- - this high-level entry point to allow formatting? (which in turns may require ID separate from formatted string)
    -- - because of this we probably can't turn 'string label' into 'string fmt, ...'
    -- Otherwise, we can decide that users wanting to drag this would layout a dedicated drag-item,
    -- and then we can turn this into a format function.
    ImGui.SeparatorTextEx(0, label, ImGui.FindRenderedTextEnd(label), 0.0)
end

-------------------------------------------------------------------------------
-- [SECTION] Widgets: ComboBox
-------------------------------------------------------------------------------
-- - CalcMaxPopupHeightFromItemCount() [Internal]
-- - BeginCombo()
-- - BeginComboPopup() [Internal]
-- - EndCombo()
-- - BeginComboPreview() [Internal]
-- - EndComboPreview() [Internal]
-- - Combo()
-------------------------------------------------------------------------------

--- @param items_count float
--- @return float
local function CalcMaxPopupHeightFromItemCount(items_count)
    local g = GImGui
    if items_count <= 0 then
        return FLT_MAX
    end
    return (g.FontSize + g.Style.ItemSpacing.y) * items_count - g.Style.ItemSpacing.y + (g.Style.WindowPadding.y * 2)
end

--- @param label          string
--- @param preview_value? string
--- @param flags?         ImGuiComboFlags
function ImGui.BeginCombo(label, preview_value, flags)
    if flags == nil then flags = 0 end

    local g = GImGui
    local window = ImGui.GetCurrentWindow()

    local backup_next_window_data_flags = g.NextWindowData.HasFlags
    g.NextWindowData:ClearFlags() -- We behave like Begin() and need to consume those values
    if window.SkipItems then
        return false
    end

    local style = g.Style
    local id = window:GetID(label)
    IM_ASSERT(bit32.band(flags, bit32.bor(ImGuiComboFlags.NoArrowButton, ImGuiComboFlags.NoPreview)) ~= bit32.bor(ImGuiComboFlags.NoArrowButton, ImGuiComboFlags.NoPreview)) -- Can't use both flags together
    if bit32.band(flags, ImGuiComboFlags.WidthFitPreview) ~= 0 then
        IM_ASSERT(bit32.band(flags, bit32.bor(ImGuiComboFlags.NoPreview, ImGuiComboFlags.CustomPreview)) == 0)
    end

    local arrow_size
    if (bit32.band(flags, ImGuiComboFlags.NoArrowButton) ~= 0) then
        arrow_size = 0.0
    else
        arrow_size = ImGui.GetFrameHeight()
    end

    local label_end = ImGui.FindRenderedTextEnd(label)
    local label_size = ImGui.CalcTextSize(label, label_end, false)

    local preview_width
    if ((bit32.band(flags, ImGuiComboFlags.WidthFitPreview) ~= 0) and (preview_value ~= nil)) then
        preview_width = ImGui.CalcTextSize(preview_value, nil, false).x
    else
        preview_width = 0.0
    end

    local w
    if bit32.band(flags, ImGuiComboFlags.NoPreview) ~= 0 then
        w = arrow_size
    elseif bit32.band(flags, ImGuiComboFlags.WidthFitPreview) ~= 0 then
        w = arrow_size + preview_width + style.FramePadding.x * 2.0
    else
        w = ImGui.CalcItemWidth()
    end

    local bb = ImRect(window.DC.CursorPos, window.DC.CursorPos + ImVec2(w, label_size.y + style.FramePadding.y * 2.0))
    local label_offset = (label_size.x > 0.0) and (style.ItemInnerSpacing.x + label_size.x) or 0.0
    local total_bb = ImRect(bb.Min, bb.Max + ImVec2(label_offset, 0.0))

    ImGui.ItemSize(total_bb, style.FramePadding.y)
    if not ImGui.ItemAdd(total_bb, id, bb) then
        return false
    end

    -- Open on click
    local pressed, hovered, held = ImGui.ButtonBehavior(bb, id)
    local popup_id = ImHashStr("##ComboPopup", nil, id)
    local popup_open = ImGui.IsPopupOpen(popup_id, ImGuiPopupFlags.None)
    if pressed and not popup_open then
        ImGui.OpenPopupEx(popup_id, ImGuiPopupFlags.None)
        popup_open = true
    end

    -- Render shape
    local frame_col = ImGui.GetColorU32(hovered and ImGuiCol.FrameBgHovered or ImGuiCol.FrameBg)
    local value_x2 = ImMax(bb.Min.x, bb.Max.x - arrow_size)

    ImGui.RenderNavCursor(bb, id)

    if bit32.band(flags, ImGuiComboFlags.NoPreview) == 0 then
        window.DrawList:AddRectFilled(bb.Min, ImVec2(value_x2, bb.Max.y), frame_col, style.FrameRounding, (bit32.band(flags, ImGuiComboFlags.NoArrowButton) ~= 0) and ImDrawFlags.RoundCornersAll or ImDrawFlags.RoundCornersLeft)
    end

    if bit32.band(flags, ImGuiComboFlags.NoArrowButton) == 0 then
        local bg_col = ImGui.GetColorU32((popup_open or hovered) and ImGuiCol.ButtonHovered or ImGuiCol.Button)
        local text_col = ImGui.GetColorU32(ImGuiCol.Text)

        window.DrawList:AddRectFilled(ImVec2(value_x2, bb.Min.y), bb.Max, bg_col, style.FrameRounding, (w <= arrow_size) and ImDrawFlags.RoundCornersAll or ImDrawFlags.RoundCornersRight)

        if value_x2 + arrow_size - style.FramePadding.x <= bb.Max.x then
            ImGui.RenderArrow(window.DrawList, ImVec2(value_x2 + style.FramePadding.y, bb.Min.y + style.FramePadding.y), text_col, ImGuiDir.Down, 1.0)
        end
    end

    ImGui.RenderFrameBorder(bb.Min, bb.Max, style.FrameRounding)

    -- Custom preview
    if bit32.band(flags, ImGuiComboFlags.CustomPreview) ~= 0 then
        g.ComboPreviewData.PreviewRect = ImRect(bb.Min.x, bb.Min.y, value_x2, bb.Max.y)
        IM_ASSERT(preview_value == nil or preview_value == "")
        preview_value = nil
    end

    -- Render preview and label
    if preview_value ~= nil and bit32.band(flags, ImGuiComboFlags.NoPreview) == 0 then
        if g.LogEnabled then
            ImGui.LogSetNextTextDecoration("{", "}")
        end
        ImGui.RenderTextClipped(bb.Min + style.FramePadding, ImVec2(value_x2, bb.Max.y), preview_value, nil, nil)
    end

    if label_size.x > 0 then
        ImGui.RenderText(ImVec2(bb.Max.x + style.ItemInnerSpacing.x, bb.Min.y + style.FramePadding.y), label, 1, label_end, false)
    end

    if not popup_open then
        return false
    end

    g.NextWindowData.HasFlags = backup_next_window_data_flags
    return ImGui.BeginComboPopup(popup_id, bb, flags)
end

--- @param popup_id ImGuiID
--- @param bb       ImRect
--- @param flags    ImGuiComboFlags
function ImGui.BeginComboPopup(popup_id, bb, flags)
    local g = GImGui
    if not ImGui.IsPopupOpen(popup_id, ImGuiPopupFlags.None) then
        g.NextWindowData:ClearFlags()
        return false
    end

    -- Set popup size
    local w = bb:GetWidth()
    if bit32.band(g.NextWindowData.HasFlags, ImGuiNextWindowDataFlags.HasSizeConstraint) ~= 0 then
        g.NextWindowData.SizeConstraintRect.Min.x = ImMax(g.NextWindowData.SizeConstraintRect.Min.x, w)
    else
        if bit32.band(flags, ImGuiComboFlags.HeightMask_) == 0 then
            flags = bit32.bor(flags, ImGuiComboFlags.HeightRegular)
        end
        IM_ASSERT(ImIsPowerOfTwo(bit32.band(flags, ImGuiComboFlags.HeightMask_))) -- Only one
        local popup_max_height_in_items = -1
        if bit32.band(flags, ImGuiComboFlags.HeightRegular) ~= 0 then
            popup_max_height_in_items = 8
        elseif bit32.band(flags, ImGuiComboFlags.HeightSmall) ~= 0 then
            popup_max_height_in_items = 4
        elseif bit32.band(flags, ImGuiComboFlags.HeightLarge) ~= 0 then
            popup_max_height_in_items = 20
        end
        local constraint_min = ImVec2(0.0, 0.0)
        local constraint_max = ImVec2(FLT_MAX, FLT_MAX)
        if bit32.band(g.NextWindowData.HasFlags, ImGuiNextWindowDataFlags.HasSize) == 0 or g.NextWindowData.SizeVal.x <= 0.0 then -- Don't apply constraints if user specified a size
            constraint_min.x = w
        end
        if bit32.band(g.NextWindowData.HasFlags, ImGuiNextWindowDataFlags.HasSize) == 0 or g.NextWindowData.SizeVal.y <= 0.0 then
            constraint_max.y = CalcMaxPopupHeightFromItemCount(popup_max_height_in_items)
        end
        ImGui.SetNextWindowSizeConstraints(constraint_min, constraint_max)
    end

    -- This is essentially a specialized version of BeginPopupEx()
    local name = ImFormatString("##Combo_%02d", g.BeginComboDepth) -- Recycle windows based on depth

    -- Set position given a custom constraint (peak into expected window size so we can position it)
    -- FIXME: This might be easier to express with an hypothetical SetNextWindowPosConstraints() function?
    -- FIXME: This might be moved to Begin() or at least around the same spot where Tooltips and other Popups are calling FindBestWindowPosForPopupEx()?
    local popup_window = ImGui.FindWindowByName(name)
    if popup_window then
        if popup_window.WasActive then
            -- Always override 'AutoPosLastDirection' to not leave a chance for a past value to affect us.
            local size_expected = ImGui.CalcWindowNextAutoFitSize(popup_window)
            popup_window.AutoPosLastDirection = (bit32.band(flags, ImGuiComboFlags.PopupAlignLeft) ~= 0) and ImGuiDir.Left or ImGuiDir.Down -- Left = "Below, Toward Left", Down = "Below, Toward Right (default)"
            local r_outer = ImGui.GetPopupAllowedExtentRect(popup_window)
            local pos
            pos, popup_window.AutoPosLastDirection = ImGui.FindBestWindowPosForPopupEx(bb:GetBL(), size_expected, popup_window.AutoPosLastDirection, r_outer, bb, ImGuiPopupPositionPolicy.ComboBox)
            ImGui.SetNextWindowPos(pos)
        end
    end

    -- We don't use BeginPopupEx() solely because we have a custom name string, which we could make an argument to BeginPopupEx()
    local window_flags = bit32.bor(ImGuiWindowFlags.AlwaysAutoResize, ImGuiWindowFlags.Popup, ImGuiWindowFlags.NoTitleBar, ImGuiWindowFlags.NoResize, ImGuiWindowFlags.NoSavedSettings, ImGuiWindowFlags.NoMove)
    ImGui.PushStyleVarX(ImGuiStyleVar.WindowPadding, g.Style.FramePadding.x) -- Horizontally align ourselves with the framed text
    local _, ret = ImGui.Begin(name, nil, window_flags)
    ImGui.PopStyleVar()
    if not ret then
        ImGui.EndPopup()
        if not g.IO.ConfigDebugBeginReturnValueOnce and not g.IO.ConfigDebugBeginReturnValueLoop then
            -- Begin may only return false with those debug tools activated.
            IM_ASSERT(false) -- This should never happen as we tested for IsPopupOpen() above
        end
        return false
    end

    g.BeginComboDepth = g.BeginComboDepth + 1

    return true
end

function ImGui.EndCombo()
    local g = GImGui
    g.BeginComboDepth = g.BeginComboDepth - 1

    local name = ImFormatString("##Combo_%02d", g.BeginComboDepth) -- FIXME: Move those to helpers?

    if g.CurrentWindow.Name ~= name then
        IM_ASSERT_USER_ERROR_RET(false, "Calling EndCombo() in wrong window!")
    end

    ImGui.EndPopup()
end

-- Submit preview contents for BeginCombo()/EndCombo(), to display contents that's more than just a text label.
-- - [BETA] See GitHub issues: #1658, #4168.
-- - Call directly after the BeginCombo/EndCombo block (requires ImGuiComboFlags.CustomPreview).
-- - The preview is designed to only host non-interactive elements.
-- - Not compatible with ImGuiComboFlags.WidthFitPreview.
function ImGui.BeginComboPreview()
    local g = GImGui
    local window = g.CurrentWindow
    local preview_data = g.ComboPreviewData

    if window.SkipItems or not (bit32.band(g.LastItemData.StatusFlags, ImGuiItemStatusFlags.Visible) ~= 0) then
        return false
    end

    IM_ASSERT(g.LastItemData.Rect.Min.x == preview_data.PreviewRect.Min.x and g.LastItemData.Rect.Min.y == preview_data.PreviewRect.Min.y) -- Didn't call after BeginCombo/EndCombo block or forgot to pass ImGuiComboFlags.CustomPreview flag?

    if not window.ClipRect:Overlaps(preview_data.PreviewRect) then -- Narrower test (optional)
        return false
    end

    -- FIXME: This could be contained in a PushWorkRect() api
    ImVec2_Copy(preview_data.BackupCursorPos, window.DC.CursorPos)
    ImVec2_Copy(preview_data.BackupCursorMaxPos, window.DC.CursorMaxPos)
    ImVec2_Copy(preview_data.BackupCursorPosPrevLine, window.DC.CursorPosPrevLine)
    preview_data.BackupPrevLineTextBaseOffset = window.DC.PrevLineTextBaseOffset
    preview_data.BackupLayout = window.DC.LayoutType

    ImVec2_Copy(window.DC.CursorPos, preview_data.PreviewRect.Min + g.Style.FramePadding)
    ImVec2_Copy(window.DC.CursorMaxPos, window.DC.CursorPos)
    window.DC.LayoutType = ImGuiLayoutType.Horizontal
    window.DC.IsSameLine = false

    ImGui.PushClipRect(preview_data.PreviewRect.Min, preview_data.PreviewRect.Max, true)

    return true
end

function ImGui.EndComboPreview()
    local g = GImGui
    local window = g.CurrentWindow
    local preview_data = g.ComboPreviewData

    -- FIXME: Using CursorMaxPos approximation instead of correct AABB which we will store in ImDrawCmd in the future
    local draw_list = window.DrawList
    if window.DC.CursorMaxPos.x < preview_data.PreviewRect.Max.x and window.DC.CursorMaxPos.y < preview_data.PreviewRect.Max.y then
        if draw_list.CmdBuffer.Size > 1 then -- Unlikely case that the PushClipRect() didn't create a command
            ImVec4_Copy(draw_list.CmdBuffer.Data[draw_list.CmdBuffer.Size].ClipRect, draw_list.CmdBuffer.Data[draw_list.CmdBuffer.Size - 1].ClipRect)
            ImVec4_Copy(draw_list._CmdHeader.ClipRect, draw_list.CmdBuffer.Data[draw_list.CmdBuffer.Size].ClipRect)
            draw_list:_TryMergeDrawCmds()
        end
    end

    ImGui.PopClipRect()

    ImVec2_Copy(window.DC.CursorPos, preview_data.BackupCursorPos)
    ImVec2_Copy(window.DC.CursorMaxPos, ImMax(window.DC.CursorMaxPos, preview_data.BackupCursorMaxPos)) -- No need to do the same with IdealMaxPos
    ImVec2_Copy(window.DC.CursorPosPrevLine, preview_data.BackupCursorPosPrevLine)
    window.DC.PrevLineTextBaseOffset = preview_data.BackupPrevLineTextBaseOffset
    window.DC.LayoutType = preview_data.BackupLayout
    window.DC.IsSameLine = false

    preview_data.PreviewRect = ImRect()
end

-- Getter for the old Combo() API: Lua array of strings (1-based), `idx` is 0-based
local function Items_ArrayGetter(data, idx)
    return data[idx + 1]
end

-- Getter for the old Combo() API: "item1\0item2\0item3\0"
local function Items_SingleStringGetter(data, idx)
    local items_count = 0
    local p = 1
    while p <= #data and string.byte(data, p) ~= 0 do
        local e = string.find(data, "\0", p, true) or (#data + 1)
        if idx == items_count then
            return string.sub(data, p, e - 1)
        end
        p = e + 1
        items_count = items_count + 1
    end
    return nil
end

local function Items_SingleStringCount(data)
    local items_count = 0
    local p = 1
    while p <= #data and string.byte(data, p) ~= 0 do
        p = (string.find(data, "\0", p, true) or #data) + 1
        items_count = items_count + 1
    end
    return items_count
end

-- Normalizes the 3 upstream overloads to (getter, user_data, items_count, height)
-- - (items: string[], items_count?, height?)
-- - (items_separated_by_zeros: string, height?)
-- - (getter: fun(user_data, idx): string?, user_data, items_count, height?)
local function Items_ResolveArgs(a, b, c, d)
    if type(a) == "function" then
        return a, b, c, d
    elseif type(a) == "string" then
        return Items_SingleStringGetter, a, Items_SingleStringCount(a), b
    else
        return Items_ArrayGetter, a, b or #a, c
    end
end

-- Old API, prefer using BeginCombo() nowadays if you can.
--- @param label        string
--- @param current_item int     # 0-based
--- @return int  current_item
--- @return bool value_changed
function ImGui.Combo(label, current_item, a, b, c, d)
    local g = GImGui
    local getter, user_data, items_count, popup_max_height_in_items = Items_ResolveArgs(a, b, c, d)
    if popup_max_height_in_items == nil then popup_max_height_in_items = -1 end

    -- Call the getter to obtain the preview string which is a parameter to BeginCombo()
    local preview_value = nil
    if bit32.band(bit32.bor(g.NextItemData.ItemFlagsSet, g.CurrentItemFlags), ImGuiItemFlags.MixedValue) ~= 0 then
        preview_value = ""
    elseif current_item >= 0 and current_item < items_count then
        preview_value = getter(user_data, current_item)
    end

    -- The old Combo() API exposed "popup_max_height_in_items". The new more general BeginCombo() API doesn't have/need it, but we emulate it here.
    if popup_max_height_in_items ~= -1 and bit32.band(g.NextWindowData.HasFlags, ImGuiNextWindowDataFlags.HasSizeConstraint) == 0 then
        ImGui.SetNextWindowSizeConstraints(ImVec2(0, 0), ImVec2(FLT_MAX, CalcMaxPopupHeightFromItemCount(popup_max_height_in_items)))
    end

    if not ImGui.BeginCombo(label, preview_value, ImGuiComboFlags.None) then
        return current_item, false
    end

    -- Display items
    local value_changed = false
    local clipper = ImGuiListClipper()
    clipper:Begin(items_count)
    clipper:IncludeItemByIndex(current_item)
    while clipper:Step() do
        for i = clipper.DisplayStart, clipper.DisplayEnd - 1 do
            local item_text = getter(user_data, i)
            if item_text == nil then
                item_text = "*Unknown item*"
            end

            ImGui.PushID(i)
            local item_selected = (i == current_item)
            if ImGui.Selectable(item_text, item_selected) and current_item ~= i then
                value_changed = true
                current_item = i
            end
            if item_selected then
                ImGui.SetItemDefaultFocus()
            end
            ImGui.PopID()
        end
    end

    ImGui.EndCombo()
    if value_changed then
        ImGui.MarkItemEdited(g.LastItemData.ID)
    end

    return current_item, value_changed
end

